-- Quest reward and progress texts in Spanish, German, French and Chinese with the reader's character filled in, the same fault
-- 2026_11_12_11 fixed for Russian. The 2026_10_10 quest catalog was read from game caches, so in some rows the gender marker
-- $Gm:f; stands as the male form only (esES "preparado" for $gpreparado:preparada;), deDE has the literal "<Volk>" where $R
-- belongs, and zhCN has two character names ("Aestra", "Verify") where $N belongs. 887 rows: esES 401, esMX 205, deDE 211,
-- frFR 37, zhCN 33.
-- Markers are put back word by word from the AzerothCore text of the same language (data/sql/base/db_world, official WotLK
-- client text) only where ours has plain words and AzerothCore a marker; a marker we already have is never touched, the rest
-- of our text stays as it is, only short stretches are swapped, and only when every $G marker comes out closed. In zhCN only
-- the two names and markers of at most a few characters; one zhCN row (5253) whose wording differs is left alone.
-- Each statement only changes a row that still holds the catalog text (MD5 check). Safe to run again.
SET NAMES utf8mb4;
UPDATE `quest_offer_reward_locale` SET `RewardText`='Saludos, joven $C, ha llegado el momento de que conozcas nuestra forma acuática. Te permitirá moverte libre e indefinidamente por el agua. Encontrarás muy útil este aspecto, pronto te darás cuenta de que es una bendición. Pero debes ganártelo antes de dominarlo.$B$BDeberás superar dos pruebas. La primera probará tu capacidad para trabajar en el agua bajo presión. La segunda, tu resolución y tu comprensión de los aspectos de la forma acuática.$B$BEstate $gpreparado:preparada;, el momento de la prueba se acerca.' WHERE `ID`=26 AND `locale`='esES' AND MD5(`RewardText`)='6c437e5702c4d55777af271578a059eb';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡$gOtro:Otra; $C que completa la Prueba del Lago! Buen trabajo.$B$BMe llamo Tajarri y tengo el honor de ser el guardián de este santuario, un tributo a la conservación de la naturaleza y su equilibrio. Este adorno señala la importancia de este lugar para el Círculo Cenarion.' WHERE `ID`=28 AND `locale`='esES' AND MD5(`RewardText`)='bb6561057235896acc8106eb4714e32e';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡$gOtro:Otra; $C que completa la Prueba del Lago! Buen trabajo.$B$BMe llamo Tajarri y tengo el honor de ser el guardián de este santuario, un tributo a la conservación de la naturaleza y su equilibrio. Este adorno señala la importancia de este lugar para el Círculo Cenarion.' WHERE `ID`=29 AND `locale`='esES' AND MD5(`RewardText`)='bb6561057235896acc8106eb4714e32e';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Estupendo! Qué ganas de $gamigo:amiga;, el diente...$B$BEn pago, elige lo que quieras de aquí.' WHERE `ID`=33 AND `locale`='esES' AND MD5(`RewardText`)='32607cadcf2d3f4e40d3cd5b50ff3d69';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Impresionante. Creo que casi estás $gpreparado:preparada;.' WHERE `ID`=187 AND `locale`='esES' AND MD5(`RewardText`)='375a400b1dfe1a883466caeac652e68e';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Absolutamente impresionante! ¡Eres $gun:una; $gauténtico:auténtica; $gmaestro:maestras; $gcazador:cazadora; de tigres, $N!' WHERE `ID`=188 AND `locale`='esES' AND MD5(`RewardText`)='7ab4cd1ddbeab1aa6d3d080bd5b10567';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Así que la gran Bhag''thera está muerta! Enhorabuena, $N. ¡Eres $gun:una; $gpoderoso:poderosa; $C!' WHERE `ID`=193 AND `locale`='esES' AND MD5(`RewardText`)='5e71b6e3cf35e4b8a11cb1bbeac99160';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Un trabajo magistral, $gamigo:amiga;.' WHERE `ID`=194 AND `locale`='esES' AND MD5(`RewardText`)='a201b830f3bc1848e2c99989ef89aa99';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡¡Jo, jo!! ¡Tenemos $gun:una; $gauténtico:auténtica; cazaraptores! Un trabajo magistral, $gamigo:amiga;.' WHERE `ID`=196 AND `locale`='esES' AND MD5(`RewardText`)='8fed8c35d84838b6f2efec00f0248c5b';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Pero qué maravilla! ¡Eso es! Enhorabuena, $N, por salir $gvictorioso:victoriosa; ahí donde otros fracasaron.$B$BEs un honor para mí contarte entre mis camaradas de caza mayor. ¡Nadie podrá poner en duda tu pericia en la caza y el rastreo!$B$B¡Levanto mi copa por ti, salud! ¡Salud!' WHERE `ID`=208 AND `locale`='esES' AND MD5(`RewardText`)='8686ea760ade26c62c31d841bba269ba';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Muy bien, $C, ¡pero que muy bien! Seguiré mandando tropas para diezmar a los furbolgs, pero al menos cuento con una ruta diferente que estará libre de enredos con la Alianza. ¡La conquista de Vallefresno por la Horda está bien encarrilada!$B$BTe has ganado el jornal, $ghéroe:heroína;. ¡Te saludo!' WHERE `ID`=216 AND `locale`='esES' AND MD5(`RewardText`)='e4c2018ef7a270c384c759a3d3847ee1';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ah, un vial de agua creado y bendecido por Brine y reunido por ti, nada menos.$B$BEl líquido de este vial será vital en la creación de sapta para ti pero también se usará en otra tarea.$B$BLa sapta que cree para ti también servirá para ver los espíritus del agua del altar que se encuentra en el Bosque de Argénteos, al sur de Entrañas. En cuanto a las gotas restantes, pues, te lo contaré si crees que estás $gpreparado:preparada;.$B$B¿Estás $gpreparado:preparada; para otro viaje, $N?' WHERE `ID`=220 AND `locale`='esES' AND MD5(`RewardText`)='1a0ea198f61751e55a09d21effdb5a62';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Perdona mi frío recibimiento, $N, pero ya te habrás dado cuenta de que soy un hombre muy ocupado. Veo que has impresionado a Calor, cosa que no es en absoluto fácil de conseguir, y veo que te ha dado una recomendación.$B$BHemos de afrontar seres de lo más desagradable, $N, y necesitamos la ayuda de cualquiera que haya demostrado su valía. Combatimos contra demonios, no-muertos y contra aquellos que les proporcionan ayuda. Mantente alerta, sé $gprecavido:precavida; y no confíes en nadie que no colabore con nuestra causa.$B$BGloria bajo la Luz.' WHERE `ID`=223 AND `locale`='esES' AND MD5(`RewardText`)='4878d01566e19afcc9b3819a8c4e7a28';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Lo supe en cuanto te vi, $N. Sabía que Forjaz se enorgullecería de ti. Has servido bien al rey Magni. Ahora que has demostrado ser $gun:una; ayudante leal del reino, quizás deberías hablar con el capitán para que te confíe más detalles.$B$BTe saludo, $N.' WHERE `ID`=263 AND `locale`='esES' AND MD5(`RewardText`)='2ae60f7c31df64aa8f49e0ca5d98fd59';
UPDATE `quest_offer_reward_locale` SET `RewardText`='El hierro Forjaluz es un metal precioso, pero parece que tu misión es muy peligrosa. Has hecho un largo camino, $ghermano:hermana;. Con suerte, encontrarás lo que buscas.$B$BY, si consigues el hierro, sé quién puede forjar un arma para luchar contra ese Necromántico del que hablas del Bosque del Ocaso.' WHERE `ID`=270 AND `locale`='esES' AND MD5(`RewardText`)='ce68e4952da7d082eba935dbae7b0581';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Cumples bien tus órdenes, $C. Has demostrado ser $gun:una; valiente soldado y $gun:una; leal $gservidor:servidora; del rey Magni, ¡te rindo homenaje! Gracias a la presión que ejerciste sobre el campamento Hierro Negro tenemos ahora una oportunidad para expulsarlos definitivamente de nuestras tierras... si tan solo aparecieran las condenadas fuerzas de reserva...' WHERE `ID`=303 AND `locale`='esES' AND MD5(`RewardText`)='4a2ec287d32ce1e53d810593bd78335c';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¿Es para mí? ¡Eres $gun héroe:una heroína;, $N!' WHERE `ID`=308 AND `locale`='esES' AND MD5(`RewardText`)='0fad45cb6cefaea86332167b98bf6118';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¿Entonces has visto a Renato? Aquí estamos, $gcaballero:dama;. Una botella de nuestro pinot noir especial. ¡No encontrarás nada mejor en todo Azeroth!' WHERE `ID`=332 AND `locale`='esES' AND MD5(`RewardText`)='5585bdcd1d2bb62595e70f47747e58a2';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Ay, ay! Este libro no descansa en estos estantes desde antes de la reconstrucción de Ventormenta. Habrá que restaurarlo, claro, está en un estado lamentable, pero me honraría colocarlo entre los otros libros raros de nuestra colección.$B$BGracias, $gseñor:señora;. ¡Acepta esto como pago por la devolución del libro!' WHERE `ID`=337 AND `locale`='esES' AND MD5(`RewardText`)='58b0691b4c77886c3679b856cbbf2fcc';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Lo has hecho muy, muy bien, $N. Con $gluchadores despiadados:luchadoras despiadadas; como tú actuando en nombre de los Renegados, nuestra raza está cada vez más cerca de derrotar a Arthas de una vez por todas. Tengo un buen presentimiento respecto a ti, camarada.' WHERE `ID`=372 AND `locale`='esES' AND MD5(`RewardText`)='6852b4dcf96fee5e1b4fa5d5f6417d94';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Así que finalmente, Dextren Tutor pagó por sus crímenes contra la humanidad... Eso sí que es hacer limpieza. ¡Y enhorabuena, $gamigo:amiga;! No solo has dado a las familias de los muertos la tranquilidad de espíritu que merecen, además has enviado un contundente mensaje a esos burócratas corruptos de la Casa de Nobles. Ventormenta debe escuchar las necesidades de la gente del Bosque del Ocaso o nos independizaremos y nos liberaremos de su tiranía.' WHERE `ID`=377 AND `locale`='esES' AND MD5(`RewardText`)='51116564324cc2a2e99eb919605f1542';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¿Tienes mis herramientas? ¡Bien hecho, $gmuchacho:muchacha;! Acabo de romper mi último destornillador hace una hora y necesitaba otro para acabar de reparar la máquina de asedio del piloto Roscapiedra. Desde luego, me has hecho un favor enorme trayendo estas herramientas hasta aquí, $N.$B$BTen unas monedas.' WHERE `ID`=400 AND `locale`='esES' AND MD5(`RewardText`)='b9ad6111eb77b680a996473a96233dcc';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Has derrotado a Lillith Nefara, lo que demuestra que eres $genemigo:enemiga; de la Plaga. Es increíble.$B$BHubiera jurado que era el único no-muerto con voluntad propia pero me has demostrado que también hay otros libres de la dominación del rey Exánime.' WHERE `ID`=409 AND `locale`='esES' AND MD5(`RewardText`)='b94eb94cc78897e38bd8a0b318496ae2';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Las hiedras y helechos hablan muy bien de ti, $gpequeño:pequeña;. Aunque tengo muchos nombres, solo respondo a unos pocos. Tú puedes llamarme Rethiel.$B$BDebes aguzar el oído... lamentar el destino de estas tierras heridas y te encargaré la misión de sanarlas.' WHERE `ID`=463 AND `locale`='esES' AND MD5(`RewardText`)='4ea9a6740d2580acdced4326cda7d467';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Umm... No creo que estés $ginteresado:interesada; en convertirte en mi aprendiz, ¿verdad?$B$B¡Ja! No, estoy bromeando. Eres demasiado mayor. Además por tu aspecto se diría que tienes otras ambiciones. Bueno, en cualquier caso, me has traído buenas pieles y me serán muy útiles.' WHERE `ID`=471 AND `locale`='esES' AND MD5(`RewardText`)='33dbd23a4b0f9a83502681a7cce43fb1';
UPDATE `quest_offer_reward_locale` SET `RewardText`='$N. Valstag me ha informado de tus éxitos sobre los orcos Faucedraco en Dun Algaz. Eres $gun:una; $R de gran valor.$B$BY tengo una tarea para ti.' WHERE `ID`=473 AND `locale`='esES' AND MD5(`RewardText`)='c718004f14691b80e43adfcec7610eee';
UPDATE `quest_offer_reward_locale` SET `RewardText`='$N, has demostrado ser $gun:una; $C de gran talento y valentía. $gUn:Una; $R que sigue el camino del honor del modo en que tú lo haces, sin duda alcanzará la gloria en este mundo.$B$BQue los espíritus del bosque te acompañen allá donde vayas.' WHERE `ID`=486 AND `locale`='esES' AND MD5(`RewardText`)='9ef6cad1c084573e7f2b512cae093d33';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Ja, ja, ja! ¡Lo has hecho!$B$B¿Quién habría imaginado que yo, Zenn Nauseapezuña, conseguiría que $gun:una; $R hiciera lo que se me antojara? ¡Yo no, la verdad! Pero así es... este maravilloso mundo está lleno de sorpresas.$B$B¡Tres hurras por $gnuestro:nuestra; inocente de hoy!' WHERE `ID`=488 AND `locale`='esES' AND MD5(`RewardText`)='4ead006e9c0c95e5c8f69429f8a44757';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡GUAU! ¡Me has conseguido un autógrafo de Lady Jaina! ¡Muchas gracias! Y... ¡guau!... hay un mensaje para mí, ¡para mí! Sabía que era genial, quizás algún día pueda agradecérselo en persona... ¡cuando me convierta en un héroe de la Alianza!$B$BEres $gel:la; mejor, $N. Gracias por ser tan bueno conmigo.' WHERE `ID`=558 AND `locale`='esES' AND MD5(`RewardText`)='9fdb2ea90ff88fafc1f20785dadb6bd2';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Un placer conocerte, $N. Hacía mucho tiempo que no veía a $gun:una; $C por aquí.$B$BMe metí en esta expedición por una razón: para cazar a una gran bestia esquiva. Viendo que eres $gun:una; gran $ghéroe:heroína;, voy a permitirte participar en la cacería, pero primero, debes demostrar tu valía.$B$BTe enseñaré cómo matar raptores. Ajeck te instruirá en la cacería de tigres. Y Sir Erlgadin es un maestro del rastreo de panteras.$B$BDemuestra tu habilidad y te permitiré participar en la gran cacería.' WHERE `ID`=583 AND `locale`='esES' AND MD5(`RewardText`)='c3c87ce8e52af858f43d45e507ec22de';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Muy bien hecho, $N! ¡Y justo cuando yo también tengo que embarcar! No te lo puedo agradecer bastante, $gviejo:vieja; $gamigo:amiga;.' WHERE `ID`=587 AND `locale`='esES' AND MD5(`RewardText`)='1ccc1d17ecb8ee356997da3847a279bf';
UPDATE `quest_offer_reward_locale` SET `RewardText`='<Myzrael habla a través de la piedra.>$B$B¡Lo has logrado! ¡Has abierto las Piedras de vínculo! Siento cómo los grilletes se sueltan y la libertad se acerca.$B$BComo $C, eres muy noble, $N. ¡Mi $gsalvador:salvadora;!' WHERE `ID`=651 AND `locale`='esES' AND MD5(`RewardText`)='792c0158d7e09f18651891d87a933018';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Buen trabajo, sí $gseñor:señora;, $r.$B$BEsa escoria se ha llevado su merecido. Aunque nada me devolverá mi barco o mi tripulación, la muerte de esos nagas me brinda algo de consuelo.' WHERE `ID`=664 AND `locale`='esES' AND MD5(`RewardText`)='7e895112b29f890e3c1f979a88105684';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Hemos sobrevivido al ataque!$B$BNo lo habríamos logrado sin ti, $N.$B$BPartiremos en cuanto suba la marea. Si no fueras una promesa como $ghéroe:heroína; te ofrecería un puesto en mi tripulación. Pero se te nota que te esperan peces más gordos.$B$BAunque no seas más que $gun:una; enclenque $R...' WHERE `ID`=667 AND `locale`='esES' AND MD5(`RewardText`)='9436fe020f69d8335a3d4b6a93508996';
UPDATE `quest_offer_reward_locale` SET `RewardText`='$gBienvenido:Bienvenida;, $C. La Señora me informó de tu visita y si hemos de devolverla a la superficie, entonces tenemos mucho de qué hablar...' WHERE `ID`=688 AND `locale`='esES' AND MD5(`RewardText`)='4589244b810f296ee913e426a14736ca';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Increíble! Ahora entiendo por qué Malin te pidió que te unieras a nosotros, ¡gran idea, digo! $B$BA este paso, Skuerto y yo estaremos de vuelta en Ventormenta antes de que nos demos cuenta. $B$BCreo que mi compañero enano ha vuelto de su exploración de la Sala de Puño de Roca; ve a hablar con él cuando estés $glisto:lista;. $B$BAl parecer, tuvo una escaramuza con los ogros. Aunque ni se lo mentes, es muy sensible ante las críticas a sus habilidades y a su trabajo como explorador.' WHERE `ID`=691 AND `locale`='esES' AND MD5(`RewardText`)='d6778baace0f8c46220eb366e6a4f28a';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ah, empezaré con esas alas enseguida. ¡Ya casi puedo saborearlas!$B$B¡Aquí tienes la receta en caso de que las quieras preparar tú $gmismo:misma;!' WHERE `ID`=703 AND `locale`='esES' AND MD5(`RewardText`)='e3a0d1a629e8b332ee65a23296bfcd93';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Te doy la bienvenida a la nueva frontera, $N. Vallefresno es una tierra de oportunidades en la que $gun:una; joven $C como tú cuenta con innumerables oportunidades de demostrar lo que vale. Date una vuelta por el Puesto del Hachazo y no olvides visitar La Ensenada de Zoram, la otra avanzada de la Horda.$B$BTu presencia aquí me indica que has venido a instruirte en las artes de la caza. Escucha con atención y con gusto te enseñaré todo lo que has de saber.' WHERE `ID`=742 AND `locale`='esES' AND MD5(`RewardText`)='dd191a386d605a5f7e0b2a7fb5637239';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Gracias, $N. Ha sido un suplicio, ¿verdad?$B$BNo estoy seguro de qué puede haber fallado. Menos mal que hemos contado con mi magia para enviar a la criatura de vuelta a su hogar.$B$B¿Quizás una muestra de aprecio por ser tan $gdenodado:denodada;...?' WHERE `ID`=778 AND `locale`='esES' AND MD5(`RewardText`)='46f150020ec91069833719dc39ba8b05';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Según tu descripción de la bestia creo que estás hablando de Sarkoth. No me extraña que pudiera con Hana''zua. Le prestaremos ayuda inmediatamente, ya no necesitas seguir preocupándote por su situación.$B$BPero hay una cosa que debo decir, me ha impresionado saber que acabaste con la vida de Sarkoth. Es una hazaña de la que estar $gorgulloso:orgullosa;, $N. Además, el haber luchado por el honor de un desconocido, dejando a un lado tus propias tareas, es, sin duda alguna, todo un signo de honor por tu parte.' WHERE `ID`=804 AND `locale`='esES' AND MD5(`RewardText`)='f92f8c5d298f08f84d4ee31795bb9756';
UPDATE `quest_offer_reward_locale` SET `RewardText`='$gBienvenido:Bienvenida;, $N. Fui informado de tu llegada y de tus hazañas en Durotar.$B$BEstás desarrollando tus habilidades... Te estás haciendo un nombre en este mundo, $C.$B$BMantente en el camino de la pureza y tendrás un gran futuro.' WHERE `ID`=828 AND `locale`='esES' AND MD5(`RewardText`)='73931844859c19f0f1697c230266b2e9';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Veo que eres muy $gtrabajador:trabajadora;, $C.$B$BSin duda tendremos pronto una sorpresa apropiada para esos enanos.' WHERE `ID`=846 AND `locale`='esES' AND MD5(`RewardText`)='b8facebe2b4726bc4f245cfdadb7051b';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Lo has hecho muy bien, $N! Que en todo Cima del Trueno te veneren como un defensor de las sagradas tierras tauren y como $gcampeón:campeona; de la tribu perdida.' WHERE `ID`=849 AND `locale`='esES' AND MD5(`RewardText`)='6d1995312617c1c7a30d5da69d0fbf9d';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Muy bien. Debes de haber causado mucho revuelo entre los centauros, nuestros guardias detectaron actividad cerca de El Oasis Estancado, y probablemente fueras tú.$B$BPuedes sentirte $gorgulloso:orgullosa; por este acto heroico, $N. Eres muy valiente.' WHERE `ID`=851 AND `locale`='esES' AND MD5(`RewardText`)='3efe8305735e0aedf77642516414ee42';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¿Deseas cazar en Los Baldíos?$B$BEres joven e irradias entusiasmo, pero todavía no estás $gpreparado:preparada; para perseguir a una presa por las llanuras de este lugar.$B$BDe todos modos, no te preocupes. Trabajaremos para fortalecer tu cuerpo y tu mente y aprenderás que cazar no solo consiste en encontrar y matar a tu presa.$B$BPrepárate pues tu viaje comienza aquí y ahora.' WHERE `ID`=860 AND `locale`='esES' AND MD5(`RewardText`)='f3dff3f638b47f87ececdbae6c0d2667';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Sí, sí, ¡hermosos ejemplares! Cultivaré estas raíces y las estudiaré. Espero descubrir nuevas propiedades. ¡Ocultas y valiosas propiedades...!$B$BY no te preocupes, si lo consigo, serás $gel primero:la primera; en saberlo. ¡Porque necesitaré más!' WHERE `ID`=866 AND `locale`='esES' AND MD5(`RewardText`)='d4475fdaaf4a43f8fcab77724c4bd29f';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Te has librado de los raptores!$B$BGracias, $N. $B$BEres $gun:una; $C de gran valía.' WHERE `ID`=869 AND `locale`='esES' AND MD5(`RewardText`)='eba39f0ec250048e235e271ce995179a';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Excelente trabajo, $gamigo:amiga;. Creo que llegarás lejos con la Horda.' WHERE `ID`=875 AND `locale`='esES' AND MD5(`RewardText`)='f9438f53afa0dc932f538e18fed662b7';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Sí, sí... me llena de alegría <gruñe> los Erizapúas conocen el dolor de mi tribu, $r. Así es cómo debería sentirme pero <gruñe> no es el caso.$B$BAyudas a tu pueblo y te rinden honores. Quebrantadientes ayuda a su pueblo ¿y qué hacen? Le dan la espalda. ¡Lo olvidan y lo abandonan para que se pudra en una jaula!$B$BIncluso los ayudo entre rejas ¡y no mandan a nadie a rescatarme!' WHERE `ID`=878 AND `locale`='esES' AND MD5(`RewardText`)='a15ab093bb0cea1792473228b3e9b75d';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Lo has conseguido, $gchaval:chavala;. Un poco más de trabajo igual de bueno y habrá una cosa menos por lo que preocuparse. Con suerte, se convencerán de que deben operar en otro lugar.$B$BMientras tanto, ¡está el asuntillo de recuperar la mercancía que me robaron!' WHERE `ID`=887 AND `locale`='esES' AND MD5(`RewardText`)='ec38a294b2b4fbd772d2e9ca8fdfa019';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Es un alivio recuperar todo esto, gracias por tu ayuda, $N. ¿Sabes?, no me vendría mal $gun:una; $R como tú para ayudarme aquí. Si cualquier día buscas trabajo, ¡recuerda lo bien que paga Gazlowe!' WHERE `ID`=888 AND `locale`='esES' AND MD5(`RewardText`)='97d5f00436d7fa5898021f3f4c347368';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Tú, al igual que el halcón trueno, deberías sentirte $gorgulloso:orgullosa;. Has derrotado a todos los enemigos que te hemos marcado y lo has hecho con fuerza, valor y honor.$B$BPero ahí no acaba tu camino, $N. De hecho, te darás cuenta de que los verdaderos cazadores siempre van a más, siempre siguen su camino con el mismo orgullo que me has demostrado.$B$BAhora debes seguir adelante.' WHERE `ID`=913 AND `locale`='esES' AND MD5(`RewardText`)='7447e2f7d7a98466ce62249a98d8459c';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡GUAU! ¡Me has conseguido las huellas pezuñales de Cairne Pezuña de Sangre! ¡Muchas gracias! Y... ¡guau!... hay un mensaje para mí, ¡para mí! Sabía que era genial, ¡lo sabía! Quizás algún día se lo pueda agradecer en persona... ¡cuando me convierta en un héroe de la Horda!$B$BEres $gel:la; mejor, $N. Gracias por ser tan $gbueno:buena; conmigo.' WHERE `ID`=925 AND `locale`='esES' AND MD5(`RewardText`)='1c419607a36caa9116c786b7de492966';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Saludos, $C. Me alegro de ver que estás $ginteresado:interesada; en colaborar en nuestra investigación. Queda mucho trabajo por delante y te mentiría si te dijese que no entraña peligro. Esperemos que esto no te haga desistir... aunque ya se ve que no es la primera vez que le plantas cara al peligro.' WHERE `ID`=936 AND `locale`='esES' AND MD5(`RewardText`)='a59f1bc1e3af905720678dc2245ad9c6';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ah, una copia de Los Poderes Subyacentes. Es un texto interesante. Y hay quien lo encuentra útil también...$B$BPero este ejemplar está en muy mal estado. ¡Mira esto! ¡Hay notas en los márgenes de casi todas las páginas!$B$BMm... Yo conozco este ejemplar. Se lo vendí a Bolgar el año pasado. ¿Eres... amigo $gamigo:amiga;? Eso pensaba, sí. ¡Tienes el mismo fuego en los ojos!$B$BPues, por definición, $gun amigo:una amiga; de Bolgar es $gamigo mío:amiga mia;. Y a los amigos hay que cuidarlos, ¿no te parece?' WHERE `ID`=968 AND `locale`='esES' AND MD5(`RewardText`)='b4763034bb5b251f99407d3b1b15f376';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Hoy has hecho algo grande, $N. Puedes sentirte $gorgulloso:orgullosa; de haberte enfrentado a tan poderoso brujo.$B$BAhora, veamos qué podemos averiguar en los escritos de Ilkrud.' WHERE `ID`=973 AND `locale`='esES' AND MD5(`RewardText`)='72e677a2511517036e97d5803935f087';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Has hecho un gran servicio a Auberdine, $gmuchacho:muchacha;. Cuidaremos bien de sus efectos.$B$BPor favor, acepta esto. Es lo mínimo que puedo hacer por alguien que ha tenido el valor suficiente para enmendar esta situación.' WHERE `ID`=982 AND `locale`='esES' AND MD5(`RewardText`)='29d3c5d203d31cd3d61acf11ee4e0fd3';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ah, $gun:una; $C de Costa Oscura. Selarin ha hecho bien en enviarte tan rápidamente, $N. Ojalá tu viaje aquí no se debiera a tan funesta urgencia. Quizás con tu ayuda logremos mejorar la situación.$B$BEmpezaría mi visita hablando con otros ciudadanos de Astranaar. Seguro que alguno te puede ayudar.' WHERE `ID`=990 AND `locale`='esES' AND MD5(`RewardText`)='ef1ec98104428b4047b05be32a0d172f';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Ah, aquí está! Llevo tiempo esperando este paquete con tierras especiales. Espero que todavía esté en buen estado...$B$BGracias por traérmela, $N. Eres $gun:una; $R $gcomprometido:comprometida; con su tiempo.' WHERE `ID`=997 AND `locale`='esES' AND MD5(`RewardText`)='40ffea639b1eb26071e082cd5036eb77';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Saludos, $C. $B$BMe alegra ver que alguien como tú se preocupa por el bienestar de la naturaleza. He oído hablar de tus hazañas por lo que eres bien $grecibido:recibida; aquí. Al mirarte tengo la certeza de que el Círculo Cenarion recibirá la ayuda que necesita. $B$BNuestra relación con el Círculo Cenarion en el Claro de la Luna trasciende la barrera racial y política; no lo olvides nunca.' WHERE `ID`=1000 AND `locale`='esES' AND MD5(`RewardText`)='6fcaf255c3bb60a2ef9e63d4e19eadea';
UPDATE `quest_offer_reward_locale` SET `RewardText`='La caja mecánica cobra vida en cuanto introduces los ojos de trillador. Después de un lapso de tiempo, oyes una vocecilla familiar...$B$B"El vino de reptador es lo mejor..." *hip*$B$B"¿Eh? Oh, ¿ya la has arreglado? Vaya, sí que eres $grápido:rápida;. Dime, ¿quieres arreglar otra caja?"$B$BOyes lo que parece el sonido de un líquido vertiéndose en una copa y luego ruidos ansiosos de alguien tragando.' WHERE `ID`=1001 AND `locale`='esES' AND MD5(`RewardText`)='c8898a06780d76ecb6af29a0411c2f1d';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Estos son tiempos oscuros. Cada rama que se mece al viento susurra noticias funestas y el mal puede encontrarse bajo cada piedra del camino.$B$BY en estos tiempos, $gun perfecto extraño:una perfecta extraña; entra en mi casa y me habla de ferocanis... No pediré perdón por mis sospechas, solo respuestas.$B$BY respuestas es lo que obtendré.' WHERE `ID`=1042 AND `locale`='esES' AND MD5(`RewardText`)='eaf6c24930ab21b97cd69527b59bd78f';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Tú buen $r. Yo echo de menos mis cosas. Mucho. Ahora me gustas.' WHERE `ID`=1166 AND `locale`='esES' AND MD5(`RewardText`)='38297370832777439f26611252907b10';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Tú matar a muchos del ejército de dragones negros. Tú valiente $r.$B$BPoner a Tharg contento.' WHERE `ID`=1168 AND `locale`='esES' AND MD5(`RewardText`)='720b441584be3d9248cc659997e11959';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Hola, $gciudadano:ciudadana;. Este es un lugar peligroso para las visitas. Yo no me quedaría mucho por aquí si valoras tu vida.$B$BSi tus preguntas son cortas, intentaré ayudarte. Mantén los ojos abiertos y ten cuidado con esos sucios ogros. Según los rumores, hay una base de la Horda cerca del pantano. Los infiltrados hacen todo lo que pueden para encontrarla, pero el proceso va lento y no hemos conseguido avanzar mucho.' WHERE `ID`=1266 AND `locale`='esES' AND MD5(`RewardText`)='274b7119b5f5ae15b00b67922c4f0f69';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Vino Apestoso con las hierbas que le pedí y me dijo que le habías ayudado a salir de un aprieto. ¡Bien hecho! ¡$gUn amigo:Una amiga; de Apestoso es $gamigo mío:amiga mía;!$B$BPoco antes de dirigirse hacia el sur, hacia el pantano, me pidió que te diera esto si te veía.' WHERE `ID`=1270 AND `locale`='esES' AND MD5(`RewardText`)='366852c50b7fea6d67785326141bda62';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¿Te envía Regthar? Entonces has venido a cazar centauros. Bien.$B$BEspero que hayas venido $gdescansado:descansada;. No sé cómo acabará nuestra campaña contra los centauros, pero sé que la lucha será larga.$B$BToma asiento y escucha.' WHERE `ID`=1362 AND `locale`='esES' AND MD5(`RewardText`)='d29d9c367dc38c7086315be7677bc736';
UPDATE `quest_offer_reward_locale` SET `RewardText`='La tierra me habla. Y me dice que has matado muchos Magram. Y eso está bien.$B$BSi eres $gamigo:amiga; de los Gelkis, escucha. Tengo dos misiones más para ti.' WHERE `ID`=1368 AND `locale`='esES' AND MD5(`RewardText`)='4febab8b93d429f22b5e20427cb1576c';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¿Has conseguido el arma del terrorífico Noboru? ¿Eso quiere decir que está muerto?$B$BEste es un día de júbilo para El Malecón. Noboru y los suyos representaban una seria amenaza para nosotros pues vagaban por los pantanos matando a todos los draenei que se cruzaban en su camino. Sin duda, ponía en peligro nuestra existencia pero nosotros no teníamos la fuerza suficiente para hacerle frente.$B$BSomos afortunados por tenerte como $gamigo:amiga;, $N.' WHERE `ID`=1392 AND `locale`='esES' AND MD5(`RewardText`)='dd6c3a9efd78a2cbefe5a9bf76feb3d8';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ah, $N. Hacía tiempo que no venías por aquí. Parece que hayan pasado muchas lunas desde que diste el primer salto que te inició en tu camino.$B$BY ahora regresas a mí más fuerte de lo que una vez fuiste... y más $gsabio:sabia;. Eso me complace y creo que deberías recibir una recompensa por haber superado mis pruebas.' WHERE `ID`=1394 AND `locale`='esES' AND MD5(`RewardText`)='aa42bcf08585c56631d1b324e69432f4';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Esto es terrible! Pero supongo que era necesario. Si no lo hubieras hecho tú, seguramente mi gente habría intervenido. Supongo que debería darte las gracias... perdóname si no parezco muy sincera. No es mi intención ofenderte.$B$BAhora que sé qué suerte corrió mi hermano, parece que ha llegado el momento de que huya. Si aún sigue en pie tu ofrecimiento, aceptaré tu ayuda para escapar de este horrible lugar.$B$BCuando estés $glisto:lista;, podemos emprender nuestro camino hacia la salvación.' WHERE `ID`=1439 AND `locale`='esES' AND MD5(`RewardText`)='7d1c2f970e6692d57a69f6f85a089f66';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Valiente $C, has demostrado ser $gun gran campeón:una gran campeona; de la Horda.$B$BAhora, hay que encargarse de esta colección de fetiches de Hakkar.' WHERE `ID`=1445 AND `locale`='esES' AND MD5(`RewardText`)='f167c0c24dbd89f7ba321b8ed291b792';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¿Qué quieres, $gmuchacho:muchacha;? ¿No ves que tengo cosas que hacer aquí? ¿A quién le sobra el tiempo para perderlo con $gun:una; $R $gcharlatán:charlatana;?$B$B¡Hay trols saliendo de la carpintería! Habla rápido.' WHERE `ID`=1449 AND `locale`='esES' AND MD5(`RewardText`)='10a99de4b113cd117ef59bd9026eed11';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Hip!$B$BTe estoy mirando y no paras de moverte. Tás mareándome. ¡Jo, jo!$B$B¡Hip!$B$B¡Guau! ¿Lo has sentido? La tierra se mueve, $gamigo:amiga;. Necesito una copa.$B$B¡Hip!' WHERE `ID`=1451 AND `locale`='esES' AND MD5(`RewardText`)='1b46d771856f84a1b8df95dd455ae5a0';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Aún no has sido $gprobado:probada; y estás al principio de tu aprendizaje, pero has demostrado que posees la habilidad suficiente para invocar y poseer a un diablillo. No te dejes engañar por su tamaño. No posee fuerza física, pero sí poderes y una inteligencia que te vendrán bien.$B$BAtiéndeme bien, $N, porque no repetiré esta lección; dejaré que la domines por tu cuenta.' WHERE `ID`=1470 AND `locale`='esES' AND MD5(`RewardText`)='ed7bf498ebd8efec591208c54dc178a6';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Estupendo! Perrine no tenía ni idea de la importancia de este libro.$B$BAhora no permitiremos que nos lo vuelvan a arrebatar. Observa, $n, la estructura del hechizo y el modo en el que debes canalizar tu poder.' WHERE `ID`=1473 AND `locale`='esES' AND MD5(`RewardText`)='d244a3515f8c67fa8517dd9c742fe41f';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Un cristal del oráculo precioso, sin mácula... Qué belleza.$B$BEmpecemos: debemos encontrar y eliminar al señor demoníaco.$B$BApártate, $c; voy a concentrarme para descubrir su paradero.' WHERE `ID`=1482 AND `locale`='esES' AND MD5(`RewardText`)='8c41b2b27039e728dae63f267eced0ca';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Mis más cordiales saludos, $N. Eres $gbienvenido:bienvenida; entre nosotros. Te convendría hacer un acopio de todas tus fuerzas... la tarea que te espera... es extremadamente ardua.' WHERE `ID`=1489 AND `locale`='esES' AND MD5(`RewardText`)='31370a3c0ca3aef99b371bb762bb9bbf';
UPDATE `quest_offer_reward_locale` SET `RewardText`='No esperaba menos de mi $galumno:alumna; estrella.$B$BHas probado tu valor; yo te enseñaré a invocar a tu súcubo dominado. Ve y sigue aprendiendo; la próxima vez que nos veamos, habrás dominado a tu súcubo.$B$BRecuerda la tragedia de Dogran y Zankaja como protección contra el poder ocuro que has aprendido a invocar hoy.' WHERE `ID`=1513 AND `locale`='esES' AND MD5(`RewardText`)='57d18569f47570c6466e8045d6fda62a';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ah... $N... la tierra se complace de tenerte aquí.$B$B$gComprometido:Comprometida; en cuerpo y espíritu, avanzarás sabiendo que las montañas son tu fuerza, las llanuras tu paciencia y el mundo tu esencia.$B$BLa humildad ante la tierra es todo lo que necesitas para pasar este rito. Pero los otros no son tan pasivos. Pueden ser caóticos y violentos... tal es la naturaleza de los elementos, naturalezas duales en eterna oposición. Debes aprender estas cosas en toda su complejidad.' WHERE `ID`=1517 AND `locale`='esES' AND MD5(`RewardText`)='e8507b5c080ba0a2fae901776f679d37';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ah... $n... la tierra se regocija en tu presencia aquí.$B$B$gComprometido:Comprometida; adelante sabiendo que las montañas son tu fuerza, las llanuras tu paciencia y el mundo mismo tu esencia.$B$BPara superar el rito, solo debes mostrar humildad ante la tierra. Los demás ritos son violentos, pero esa es la naturaleza de los elementos: aprenderás que vivimos en un mundo de dualidades.' WHERE `ID`=1520 AND `locale`='esES' AND MD5(`RewardText`)='76127552387b743a9316229798cf0b8e';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Magnífico.$B$BVoy a crear un tótem que es más que un símbolo. Podrás usarlo en hechizos vinculados a la tierra, y a medida que ganas sabiduría, ganarás más facultades de la tierra. En todo Kalimdor encontrarás instructores que $glisto:lista; tu formación cuando sientan que ha llegado el momento.$B$BDe momento, toma este tótem de la tierra...' WHERE `ID`=1521 AND `locale`='esES' AND MD5(`RewardText`)='ff3d58da92c6e014d04486e26b524d02';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Así que... te manda Searn, ¿eh?$B$BBien. Siempre he confiado en Searn. Si te envía a mí, es que estás $gpreparado:preparada; para participar en la siguiente sapta... la sapta de fuego.$B$BYa puedo ver esa chispa, esa llama de impaciencia en tus ojos. Has probado el poder y ahora estás $glisto:lista; para adquirir más. Paciencia, $N. Recuerda lo que la tierra te enseñó. El poder y la destrucción llegan fácilmente, pero siempre has de saber cuándo detener tu mano.' WHERE `ID`=1522 AND `locale`='esES' AND MD5(`RewardText`)='e42a204ceb6b8bea580b3c707ccaac06';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¿Sí?$B$BMm, me parece que sé lo que vas a preguntarme: ¿qué posee a alguien para vivir en el más remoto rincón de Los Baldíos, rodeado de la amenaza de los jabaespines y sin protección? Bueno, todos tenemos nuestros motivos para justificar la forma en que actuamos. La verdadera cuestión es qué trae a $gun:una; humilde $R a lo más recóndito de Los Baldíos para hablar con una mujer que a todas luces no se preocupa por su propio bien.$B$BApostaría que ambos conocemos la respuesta.' WHERE `ID`=1530 AND `locale`='esES' AND MD5(`RewardText`)='89dbb8a1d08a92a87b3783d3df948390';
UPDATE `quest_offer_reward_locale` SET `RewardText`='De momento, te daré lo que necesitas para realizar tus hechizos e invocar a los espíritus del aire. Coge este tótem y, cuando estés $gpreparado:preparada;, ven a verme para continuar con tu instrucción.' WHERE `ID`=1531 AND `locale`='esES' AND MD5(`RewardText`)='505c2e3583da66e1df1c2acec4b77828';
UPDATE `quest_offer_reward_locale` SET `RewardText`='De momento, te daré lo que necesitas para realizar tus hechizos e invocar a los espíritus del aire. Coge este tótem y, cuando estés $gpreparado:preparada;, ven a verme para continuar con tu instrucción.' WHERE `ID`=1532 AND `locale`='esES' AND MD5(`RewardText`)='505c2e3583da66e1df1c2acec4b77828';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡No puedo creer que los hayas encontrado! ¡Eres sin duda $gel:la; $r más $gafortunado:afortunada; de Kalimdor!' WHERE `ID`=1579 AND `locale`='esES' AND MD5(`RewardText`)='f6def3275ec3c995cd251b6f3d6488c4';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Son unas buenas piezas. Tienes manos hábiles y un buen ojo para los detalles. Tu futuro como $gpeletero:peletera; es prometedor.$B$BTen, $N. Deja que te enseñe el patrón para hacer el jubón de brillo lunar.' WHERE `ID`=1582 AND `locale`='esES' AND MD5(`RewardText`)='7ab9eaf3d63959ccaffc5bc6ebe57de2';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Oh, jo! Tómate un trago conmigo, $gmuchacho:muchacha;. A primera vista pareces muy $gduro:dura;, pero veamos si puedes arreglártelas con algunas jarras de las especialidades más potentes de El Cerdo Borracho$B$BO bien... ¿has venido para recibir instrucción?' WHERE `ID`=1638 AND `locale`='esES' AND MD5(`RewardText`)='a3e2d115e958f09cf5d00a975742d14e';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Hola $gmuchachito:muchachita;! ¿Qué hace $gun:una; repipi como tú en El Cerdo Borracho? Ten cuidado, se te podría romper una uña...' WHERE `ID`=1639 AND `locale`='esES' AND MD5(`RewardText`)='da3aa4b155a826a7a50b8897e88a41cf';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Hola de nuevo, $N. ¿Cómo van tus estudios del Libro de la Divinidad?$B$BSi lo has estudiado, deberías estar preparado para pasar una prueba. Siempre hay cosas que hacer en la ciudad y en nuestras tierras. Actos de compasión y comprensión, gente a la que ayudar, criaturas a las que matar...$B$BSi demuestras que tienes la paciencia necesaria para ayudar a otros, especialmente a los menos afortunados, demostrarás que estás en pleno uso de tus facultades y que eres $gun:una; siervo de la Luz.' WHERE `ID`=1642 AND `locale`='esES' AND MD5(`RewardText`)='1e4360c71be5e5caf794026b50e57d95';
UPDATE `quest_offer_reward_locale` SET `RewardText`='$gBienvenido:Bienvenida; de nuevo, $N. Espero que hayas dedicado un rato a leer el libro.$B$BSi lo has hecho, deberías estar $gpreparado:preparada; para pasar una prueba. Siempre hay cosas que hacer en la ciudad y en nuestras tierras, actos de compasión y comprensión, gente a la que ayudar, criaturas a las que matar.$B$BSi demuestras que tienes la paciencia necesaria para ayudar a otros, especialmente a los menos afortunados, demostrarás que estás en pleno uso de tus facultades y que eres $gun siervo:una sierva; de la Luz.' WHERE `ID`=1646 AND `locale`='esES' AND MD5(`RewardText`)='00cb4293cb558872aeee685cbcdbc3b6';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡La tienes! Seguro que no quería separarse de ella pero has sido muy $gpersuasivo:persuasiva;. Bien hecho.$B$BPasemos ahora a tu lección...' WHERE `ID`=1665 AND `locale`='esES' AND MD5(`RewardText`)='190650d7ff7992af15b4613348cbcb48';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Vejrek tenía que ser bastante feo, ¿eh? ¡Bien hecho, $N! Tienes todo lo necesario, comencemos nuestra lección...$B$BTal vez no lo sepas, pero una defensa fuerte es fundamental para $gun:una; $C. Le permite mantenerse en pie frente a enemigos que derribarían al resto, y eso es lo que necesitan de ti tus aliados.' WHERE `ID`=1678 AND `locale`='esES' AND MD5(`RewardText`)='c3b31d88d2680d2967e7787917be15c9';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Recibe mis más cordiales saludos, $N. Tu nombre es muy conocido en Darnassus, eres $gprometedor:prometedora;. Pero pronto veremos si tienes la fuerza de voluntad necesaria para seguir recorriendo la senda del $C.' WHERE `ID`=1684 AND `locale`='esES' AND MD5(`RewardText`)='d88663c845985943f6036b24b962e3f6';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Bien hecho, $N. ¡Has superado La Reyerta! $B$BEres $gun digno:una digna; digno $C y es un honor instruirte...' WHERE `ID`=1719 AND `locale`='esES' AND MD5(`RewardText`)='5a848a588481c819915ef03a7d6f63e8';
UPDATE `quest_offer_reward_locale` SET `RewardText`='No sé cómo darte las gracias, $ghermano:hermana;.$B$BVeo que llevas el Símbolo de la Vida, así que solo puedo deducir que Tiza y Muiredon te enviaron a ayudarme.$B$BCaí combatiendo contra los Hierro Negro cuando intentaba hacerme con uno de los textos. Conseguí retenerlos lo suficiente para que Muiredon escapara, pero cuando llegaste, la Luz casi me había abrazado por completo. El hecho de que tuvieras la fuerza para utilizar el Símbolo tiene mucha importancia para ti, pero ya hablaremos de eso más adelante.' WHERE `ID`=1783 AND `locale`='esES' AND MD5(`RewardText`)='46d5f52102dbdca3e79351212e58732e';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Hoy has hecho un gran favor a todo Forjaz, $N. Me enorgullece contarte entre los nuestros y, si te sientes $gpreparado:preparada;, quisiera bendecirte con este pergamino. El Símbolo de la Vida solo habría funcionado en manos de $gun:una; $C que estuviera $glisto:lista; para una de las mayores bendiciones de la Luz: el poder de devolver la vida a los muertos.$B$BTe enseñaré cómo resucitar a tus compañeros. Utiliza ese don con sabiduría, $N. Te doy las gracias, también de parte de mi marido y de Forjaz.' WHERE `ID`=1785 AND `locale`='esES' AND MD5(`RewardText`)='3f11f61b39688c5c1f8f0f376c1345ba';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Gracias, $ghermano:hermana;.$B$BVeo que portas el Símbolo de la Vida, ¿puedo deducir de eso que te envían Duthorian o Gazin?$B$BCaí ante los hechizos de los Defias cuando Gazin y yo intentábamos hacernos con sus planes. Conseguí aguantar el tiempo suficiente para que Gazin escapara, pero al final, su magia me superó.$B$BY entonces llegaste tú y me trajiste de nuevo a la vida. La habilidad de utilizar el Símbolo no la tiene cualquiera, $N. Debes apreciar lo que significa que pudieras utilizarlo con ayuda de tu fe.' WHERE `ID`=1786 AND `locale`='esES' AND MD5(`RewardText`)='538bcfb196ac1e6caee9a9c183e3aeab';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Has actuado bien, $N. Deberías enorgullecerte de lo que has conseguido.$B$BDeberías estar $gorgulloso:orgullosa; de tus habilidades. No todo el mundo puede utilizar el poder del Símbolo de la Vida. Si puedes invocar a la Luz para devolver a los muertos a la vida, es que estás $gpreparado:preparada; para uno de los mayores honores de los paladines: el poder de resucitar.$B$BPodrás devolver a la vida a compañeros caídos, tal y como hiciste con Henze.$B$BCuídate, $N. La Luz te ilumina. Recíbela en ti.' WHERE `ID`=1788 AND `locale`='esES' AND MD5(`RewardText`)='fdd70875a45a281e6b1b7ad31e58b7b8';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Debo decir que estoy impresionado, $N. Cuando me enfrenté a mi primer manáfago, salí con vida de milagro. Presiento que tienes el potencial para convertirte en $guno de los más poderosos brujos:una de las más poderosas brujas; de esta era.' WHERE `ID`=1795 AND `locale`='esES' AND MD5(`RewardText`)='9dfbcad160d4dfb8b9501f5703392240';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Oh, así que te envía Menara. Vale... Supongo que puedes quedarte como $ginvitado:invitada; por ahora. Pero debes estar detrás de algún asunto urgente, ¿en busca de poder perdido quizás? A lo mejor me equivoco. A lo mejor la corrupción ni se te ha acercado después de todo.' WHERE `ID`=1799 AND `locale`='esES' AND MD5(`RewardText`)='38f7318d863982c07b2779b5ddcb311b';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Bien hecho, $N. Ulag no era un agente menor de la Plaga. Has mostrado a los guardias de la muerte y, por tanto, a la Dama Oscura, que eres $gun:una; $C  y firme y que mereces seguir avanzando en tu instrucción.' WHERE `ID`=1819 AND `locale`='esES' AND MD5(`RewardText`)='aea59189591018d72c314cfb7fb42631';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Muy bien hecho, $N! Al superar la prueba en Tierra de Gigantes has dado un gran paso adelante en la senda $gdel:de la; $C.' WHERE `ID`=1824 AND `locale`='esES' AND MD5(`RewardText`)='a126793e4c826543e078b817fb04310d';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Mm, interesante. Has probado sobradamente tu valía, $N. Considérate $gel:la; miembro más reciente de Mano Destrozada. Y toma esto; te ayudará mucho en el futuro.' WHERE `ID`=1858 AND `locale`='esES' AND MD5(`RewardText`)='aec4dca456424e3babbf64afeb885d09';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¿Te han enviado para ayudarme con mi tarea, $N? Bien. Es alentador ver cómo $glos:las; jóvenes $gmagos:magas; se esfuerzan por ayudar a nuestra causa...$B$B¿Qué causa, dices? A su debido tiempo, joven. Lo sabrás... a su debido tiempo.' WHERE `ID`=1860 AND `locale`='esES' AND MD5(`RewardText`)='0a04fb3b63259a6b871a76aa59450c62';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Oh, veo que eres prometedor, ¡sí, lo eres! Pero hace falta algo más que una promesa para ser $gun buen:una buena; buen $C. Y si no eres $gun buen:una buena; buen $C, eres $gun:una; $c $C. Y los malos magos son parte del problema, ¡sí, lo son!$B$BUps, me estoy adelantando... ¡empecemos por el principio!' WHERE `ID`=1879 AND `locale`='esES' AND MD5(`RewardText`)='5d966b3d8805acb9412f213c24f0aff6';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Saludos, $N. Fuiste $gsabio:sabia; al responder a mi llamada, y aún lo serás más si escuchas lo que voy a decirte...' WHERE `ID`=1881 AND `locale`='esES' AND MD5(`RewardText`)='acbf2803bb207607a3e3c54ff61329ac';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ave, $N. Loado seas, has respondido a mi petición de auxilio. Esperemos que estés $gpreparado:preparada; para esta tarea...' WHERE `ID`=1883 AND `locale`='esES' AND MD5(`RewardText`)='00aa68789b7112c1db21767e27092dd5';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¿Mm? No hay duda de que has venido tan pronto te has enterado de que requería tu presencia. Claro que no esperaría otra cosa de $gun futuro mortacechador:una futura mortacechadora;.' WHERE `ID`=1885 AND `locale`='esES' AND MD5(`RewardText`)='0c915890015a977151c79d8669aeb466';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Ah! Te estaba esperando. Seguro que quienes te envían están satisfechos con la información que les he dado hasta el momento, ¿no? $B$BSupongo que no tiene mucho sentido que te haga esta pregunta pues seguro que desconoces la respuesta. No creo que confiaran tanto en $gun simple mensajero:una simple mensajera;...' WHERE `ID`=1898 AND `locale`='esES' AND MD5(`RewardText`)='7ba7a02cb8fe137af351f696a949c612';
UPDATE `quest_offer_reward_locale` SET `RewardText`='$N, tengo una misión para ti, aquí en el distrito de los $c. Escucha atentamente, no hay tiempo que perder.' WHERE `ID`=1919 AND `locale`='esES' AND MD5(`RewardText`)='970f3fe48b318219fd26395cdca87130';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Sí, son unas piezas de lino excelentes. Podré hacer una bonita túnica y cuando entreteja las gemas de la falla, ¡tendremos una prenda realmente digna de $gun:una; $C!' WHERE `ID`=1921 AND `locale`='esES' AND MD5(`RewardText`)='f73123aa2367ffb7a079c869da2ac1e4';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Muy bien, $N! Has aprendido a forzar cerraduras ¡y mucho más rápido de lo que esperaba!$B$BSabía que podía confiar en ti. Créeme $gmuchacho:muchacha;, te digo que llegarás lejos.' WHERE `ID`=1999 AND `locale`='esES' AND MD5(`RewardText`)='bf026a3d0444db435e4d653a0d241eff';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ah sí, en paquete de hierbas de Cañada Umbría. Es una lástima que no lo haya podido traer el propio Porthannius pues él y yo tenemos mucho de qué hablar. No obstante, me alegro de hayas venido a traerme las hierbas.$B$BYa que estás aquí, aprovecha para descansar. $gLos héroes:Las heroínas; han de velar por su fuerza y ánimo, y buscar descanso y solaz cuando sea necesario. Si no se proporciona paz al cuerpo y a la mente, el fracaso es inevitable.$B$BAsí pues... descansa.' WHERE `ID`=2159 AND `locale`='esES' AND MD5(`RewardText`)='86745733ac8558ce6b7b3d3b050dbc93';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Ah, por fin! ¡Los suministros! Empezaba a preocuparme. Hemos tenido pocas noticias de Yunquemar desde que los troggs se hicieron con el paso.$B$BGracias por traerme esto, $N. Te lo ruego, ponte $gcómodo:cómoda;. Debes de estar $gcansado:cansada; del viaje.' WHERE `ID`=2160 AND `locale`='esES' AND MD5(`RewardText`)='9e65b30156d63ae69799945282686ae6';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¿Así que te consideras un bribón? ¿Destinado a convertirte en uno de los elegidos de Barbanegra... un oficial del Círculo Oculto? $B$BSolo un pillo redomado se lo tendría así de creído. $B$B¡Y eso es exactamente lo que buscamos! ¡$gBienvenido:Bienvenida; a bordo, $N!|n' WHERE `ID`=2218 AND `locale`='esES' AND MD5(`RewardText`)='eee447058d81c6f00e3104684e3255b1';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¿Un camino largo? ¡Por mis barbas!$B$BHas hecho bien, $N. Ten esta daga y retírate. El Círculo te convocará cuando la fase tres esté preparada.$B$B¿Que qué es la fase tres? Pues la que viene justo después de las dos, claro. Es cuando yo te pongo la bota en el culo.$B$B¿$gInteresado:Interesada;?' WHERE `ID`=2239 AND `locale`='esES' AND MD5(`RewardText`)='5991ace7780396e3c5eaac7cfe76c511';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Si hubiera guardado todas las flores que ese necio de Jannok me ha enviado, podría montar una floristería. Eso sí, creo que el último mensajero de Jannok podría resultarme útil.$B$B¿Te interesa $ginteresado:interesada; conmigo, $C?' WHERE `ID`=2241 AND `locale`='esES' AND MD5(`RewardText`)='1ed31154abf8d447dc3b195ffc7baaa3';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¿Qué tienes ahí? ¡Vaya! ¿Dónde encontraste esto?$B$B¿De verdad?$B$B¿Qué hablaste de qué con quién?$B$B¡NO PUEDE SER VERDAD!$B$BMi $gquerido:querida; $C, ¡este puede ser el descubrimiento arqueológico del año! ¿¡Qué digo del año!? ¡Del siglo! Si estos discos son lo que creo que son, ¡tenemos delante la última pieza del rompecabezas! Esto podría demostrar de una vez por todas la legitimidad de la creación encantada de los enanos.' WHERE `ID`=2279 AND `locale`='esES' AND MD5(`RewardText`)='fca34282a7ce8952eb2d6fb5aaab375f';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Siempre viene bien contar con uno de $glos pícaros:las pícaras; de Hulfdan entre nuestras filas!' WHERE `ID`=2298 AND `locale`='esES' AND MD5(`RewardText`)='6d29f7d5c530ca99a4902bbe287f2bea';
UPDATE `quest_offer_reward_locale` SET `RewardText`='$gPoderoso:Poderosa; $C, sé a qué has venido a las Tierras Inhóspitas. Me necesitas por mi vasto conocimiento de otras lenguas y estás buscando las piezas del collar que encontraste en Uldaman.$B$B¿Sorprendido? No lo estés tanto, mi trabajo consiste en averiguar estas cosas. Así pues, centrémonos en el diario y dime qué recibiré a cambio de su traducción. Créeme, no encontrarás a nadie más que pueda hacerlo.$B$BEs más, te haré una oferta mejor que la de Dran Droffers de modo que todavía puedas cumplir su trato. ¿Qué dices?' WHERE `ID`=2318 AND `locale`='esES' AND MD5(`RewardText`)='ca60f9fde943698cd9d1b923167253b2';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Lo que me trajiste superó todas mis expectativas; tengo un collar para mí, uno para ti y me ha sobrado para hacer 3 más. Voy a hacer un buen negocio, al margen de Rescates Droffers e Hijos.$B$BTen; tienes, $gamigo:amiga;. Te doy las gracias por tu ayuda y algo muy especial como muestra de gratitud.' WHERE `ID`=2341 AND `locale`='esES' AND MD5(`RewardText`)='1e0a78e0645952ea39f401ddc163ec83';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ah, mi pergamino. Oí que habías venido al Valle, $N. Me alegra saber que lo has conseguido... esperemos que sobrevivas todos los retos que te aguardan. Como dije, ven a verme cuando crezca tu poder, haré todo lo que pueda por instruirte en las artes $gdel:de la; $C.$B$BBuena suerte, $N, y vuelve a verme cuando creas que estás $gpreparado:preparada;.' WHERE `ID`=2383 AND `locale`='esES' AND MD5(`RewardText`)='b11047042d345cef29ac2358341935a2';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Fantástico, encontraste algunas! Mil gracias, $N. ¡Eres $gel:la; $R más formal que he conocido! $B$BMe muero por probarlas en unos dispositivos que he fabricado. Apuesto que, en las circunstancias apropiadas, los dispositivos impulsados con estas piedras funcionarán, y funcionarán y funcionarán...' WHERE `ID`=2418 AND `locale`='esES' AND MD5(`RewardText`)='18342bdcb5a537fe8f1165a232d6631e';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¿Qué estoy haciendo? ¿Qué parece que estoy haciendo? ¡Estoy preparando un remedio para tu ''itis''! ¡No te enfades ahora conmigo, $N!$B$BUnos segundos más. ¡Ya está! Rocíate con esta, mmm, medicina de olor tan fantástico, y volverás a $gnuevo:nueva;.' WHERE `ID`=2609 AND `locale`='esES' AND MD5(`RewardText`)='8ca8b6fbdd88ca97e11ffb07a9f56464';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡La leyenda de los Omosh perdurará!$B$BHas demostrado tu habilidad $gherrero:herrera;, $n. premio será ver tus armas y armaduras bañadas con la sangre de tus enemigos.$B$B¡Que tus creaciones protejan a tus aliados y destruyan a tus enemigos!' WHERE `ID`=2751 AND `locale`='esES' AND MD5(`RewardText`)='ac5245caaa2d0c398f64a12611e38c6b';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¿Vienes a ayudar? ¡Genial!$B$BNecesito una pieza para un experimento y me $gun:una; $c valiente como tú para conseguirla.' WHERE `ID`=2769 AND `locale`='esES' AND MD5(`RewardText`)='244d12c324bc6fabb0fe2cfbdacc6a9a';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Listo! ¡Cuando estés $gpreparado:preparada;, súbete a la plataforma!' WHERE `ID`=2843 AND `locale`='esES' AND MD5(`RewardText`)='86eb73e9e071e0ab0856b0ff4a5ad289';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Bien, $N, me alegro de tenerte como aprendiz. Has tomado una buena decisión como $gpeletero:peletera;, quienes llevan armaduras de cuero te aclamarán cuando domines el arte del cuero salvaje.$B$BPongámonos a trabajar, ¿por dónde quieres empezar?' WHERE `ID`=2854 AND `locale`='esES' AND MD5(`RewardText`)='7e6d631373d7e156e8a8194d054e3dd1';
UPDATE `quest_offer_reward_locale` SET `RewardText`='El equipamiento Nochefugaz que me has traído es perfecto, $N. No esperaba menos de $gun peletero:una peletera; de tu calibre.$B$BTe has ganado el honor de crear cascos de cuero salvaje. Te doy este patrón de buen grado y espero que te beneficies de él como mereces.' WHERE `ID`=2857 AND `locale`='esES' AND MD5(`RewardText`)='adeb71ae7c5086e495bdb80734bdaf59';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Esto es un buen comienzo, $N. Tus habilidades de combate son encomiables.$B$BY no eres $gel primero al:la primera a la; que he asignado esta misión. Muchos antes que tú han combatido contra ellos. Nuestros esfuerzos los han mantenido a raya hasta ahora. Pero últimamente, sus intentos de avanzar hacia el norte por nuestra tierra, se han redoblado. Y sus ataques son cada vez más salvajes... casi como si estuvieran desesperados.$B$BPero yo tengo un plan que podría solucionar esto de una vez por todas.' WHERE `ID`=2862 AND `locale`='esES' AND MD5(`RewardText`)='ba466ab5ef0de696bbd0e957651d3001';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Oh, genial! ¡Los conseguiste! $B$BGracias, $N. ¡Eres $gun:una; $gauténtico:auténtica; salvavidas!' WHERE `ID`=2865 AND `locale`='esES' AND MD5(`RewardText`)='f0edc7e67dc117d7c91e18330f1067b7';
UPDATE `quest_offer_reward_locale` SET `RewardText`='$gBienvenido:Bienvenida;, $N. Tu informe sobre la glorieta es... preocupante. Parece que, aunque los naga no estuvieran planeando un ataque, su presencia es una mala señal para nuestra ofensiva en Feralas. En cualquier caso, aquí tienes tu compensación por tu servicio.$B$BParece que el Bastión Plumaluna necesita desesperadamente ayuda con el problema de los naga Crestafuria. Quisiera ofrecerte a ti la misión, si te parece. Hay mucho que hacer.' WHERE `ID`=2867 AND `locale`='esES' AND MD5(`RewardText`)='c81322862597093d1131b0bda0347fde';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Bien, $N! La muerte de Señor Shalzaru desconcertará a los naga durante un tiempo, si no para siempre. La amenaza que suponen ahora está más descontrolada que nunca, y eso te lo debemos a ti.$B$BAquí tienes más dinero del tesoro del Bastión. Te has ganado cada pieza. Tú y los tuyos sois siempre bienvenidos en el Bastión Plumaluna, $gamigo:amiga;.$B$BUna cosita más, antes de que te vayas, $N... si pudieras...' WHERE `ID`=2870 AND `locale`='esES' AND MD5(`RewardText`)='4b9ec8110af827196ff20fc850acdb15';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Me alegra ver que te $ginteresado:interesada; interesando la exploración, $N! ¡Con esa maña que te das, podríamos desvelar secretos inimaginables!$B$BLos Discos de Norgannon contenían muchísima información; tú no llegaste a ver sino las capas superiores. Se dice que los Creadores tenían almacenes de información dispersos por todo Azeroth. Y eso nos lleva a Uldum...' WHERE `ID`=2963 AND `locale`='esES' AND MD5(`RewardText`)='5b623abdc9ad5a413d72426487e178ce';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Así que... te manda Swart, ¿eh?$B$BBien. Siempre he confiado en Swart. Si te envía a mí, es que estás $glisto:lista; para participar en la siguiente sapta... la sapta de fuego.$B$BYa puedo ver esa chispa, esa llama de impaciencia en tus ojos. Has probado el poder y ahora estás listo para adquirir más. Paciencia, $N. Recuerda lo que la tierra te enseñó. El poder y la destrucción llegan fácilmente, pero siempre has de saber cuándo detener tu mano.' WHERE `ID`=2983 AND `locale`='esES' AND MD5(`RewardText`)='17f423bf7f74839e42ba4385ce57022c';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Así que... te manda Narm, ¿eh?$B$BBien. Siempre he confiado en Narm. Si te envía a mí, es que estás $glisto:lista; para participar en la siguiente sapta... la sapta de fuego.$B$BYa puedo ver esa chispa, esa llama de impaciencia en tus ojos. Has probado el poder y ahora estás listo para adquirir más. Paciencia, $N. Recuerda lo que la tierra te enseñó. El poder y la destrucción llegan fácilmente, pero siempre has de saber cuándo detener tu mano.' WHERE `ID`=2984 AND `locale`='esES' AND MD5(`RewardText`)='588cc745b17499c6a112508ea9b8f90b';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Cuando sigas instruyéndote en las artes $gdel:de la; $C encontrarás este lugar muy adecuado. Si tienes cualquier duda no temas en preguntar a cualquiera y cuando te sientas preparado vuelve a verme para recibir instrucción. Tengo el mismo dominio que cualquier otro $C del Valle y puedo transmitirte ese conocimiento... por un precio, claro.' WHERE `ID`=3065 AND `locale`='esES' AND MD5(`RewardText`)='dbd4e5bd15f98c78ef587ea827f339ac';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ahora les enseñamos todo eso y ellos nos enseñan otras cosas. Nos hacemos una única raza... o casi. Somos aliados desde hace mucho, así que recuerda ayudarles. Y Jen''shan recordará ayudarte.$B$BJen''shan te instruye en las artes $gdel:de la; $C, te instruye bien. No olvides nunca, el $C es muy respetado en la tribu. Tú ir a tener un importante papel en el futuro... no olvides nunca.$B$BCuando lo necesites, ven a Jen''shan. Ella te enseña todo lo que pueda cuando crea que estás $gpreparado:preparada;.' WHERE `ID`=3082 AND `locale`='esES' AND MD5(`RewardText`)='051051e20a9e46117cb915af29fe7674';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Como seguramente ya sabrás, los elementos nos confieren nuestro poder. Fuego, tierra, agua y aire... esas son nuestras herramientas. $B$BNuestra fuerza nace de los espíritus de nuestros antepasados. Somos los líderes de nuestro pueblo. Lo que Thrall es para la Horda somos nosotros para los poblados y ciudades que visitamos. Buscan en nosotros sabiduría y protección. Para estar más $gpreparado:preparada; debes entrenar e instruirte a menudo. Cuando sientas que has ganado más poder ven a verme y te enseñaré todo lo que pueda.' WHERE `ID`=3084 AND `locale`='esES' AND MD5(`RewardText`)='ecf4613d4f82e76dd508fd6b335dc43b';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Tú estar entre los seres más poderosos del planeta, $N... no hay duda. Y todos lo saben... ¡lo saben bien!$B$BPero debes estar $gcansado:cansada;! No haber orco, ni elfo, ni enano al que tú temas... pero haber cosas que no puedes ver. Magia ser poderosa. Te obliga a hacer cosas que no quieres hacer. Te hace creer que eres más poderoso de lo que ser. Ten paciencia. Sé $glisto:lista;.$B$BCuando creas que estás $gpreparado:preparada; para instruirte vuelve con Mai''ah. Te enseña lo que estás listo para aprender, sin problema.' WHERE `ID`=3086 AND `locale`='esES' AND MD5(`RewardText`)='e7285c34ac3a75b676a791c627028fa0';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ahora que sabes dónde me encuentro te diré algo: la Mano Destrozada me pidió que diera contigo. Quieren que te instruya y te mantenga $ginformado:informada; de todo lo que necesiten. Aunque todavía no estés interesado en ayudarles (serías un idiota si no estás $ginteresado:interesada; en ayudarlos, lo estuvieras) haré todo lo que pueda por instruirte... a cambio de un pequeño pago, por supuesto. Vuelve a verme cuando creas que estás estar $glisto:lista; y veremos si estás preparado para aprender.' WHERE `ID`=3088 AND `locale`='esES' AND MD5(`RewardText`)='3bf2bb36b65c32c0ac44c44de2da7146';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Serás el medio que utilizarán nuestros antepasados para comunicarse. Tendrás el poder de los elementos a tu entera disposición. Despedazar a tus enemigos será como un juego de niños y sanar a tus aliados tan fácil como respirar. Recuerda todo esto cuando afrontes nuevos retos y vuelve a verme siempre que quieras. Me quedaré aquí para enseñarte nuevos hechizos y para mostrarte el camino correcto cuando estés $glisto:lista;.' WHERE `ID`=3089 AND `locale`='esES' AND MD5(`RewardText`)='fa567b385a6c880588b058e7f4db05b2';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Paso la mayor parte del tiempo en la posada. Me fijo en las caras nuevas, por si aparece alguien prometedor. Si no te metes en líos, haré lo posible por enseñarte algunas cosas. Vuelve cuando quieras y veremos si estás $glisto:lista; para una o dos habilidades nuevas.' WHERE `ID`=3096 AND `locale`='esES' AND MD5(`RewardText`)='07f0146ae48dbd6c3e8ae29d9cb49728';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Solo hay una cosa que debes saber: hemos sobrevivido solo con voluntad. Es la fe en nosotros mismos lo que nos separa de los demás y, con nuestros poderes, provocaremos un gran cambio en todo Azeroth. Los débiles acabarán dependiendo de ti. Los leprosos te llamarán señor. Y los ignorantes se volverán a ti en busca de guía. Mi deber es asegurarme de que tienes las herramientas necesarias para que, cuando llegue el momento, estés $gpreparado:preparada;. Cuando adquieras más experiencia, búscame. Si estás $gpreparado:preparada;, te enseñaré poderes mayores.' WHERE `ID`=3097 AND `locale`='esES' AND MD5(`RewardText`)='e4f84939dd1bc12ff71d106a9befa722';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Debes volver a mí a menudo si quieres adquirir el poder necesario para destruir a quienes se nos oponen. Aún estás $gsometido:sometida; a las reglas de la magia, $N. La corrupción te seguirá como un lobo hambriento en la noche. Te darás cuenta de que su caricia es como una adicción, como $guna antigua:un antiguo; amante que aún quiere estar a tu lado. Pero esas cosas pueden evitarse. Esas cosas solo te controlan si se lo permites.$B$BAhora, vete. Y vuelve a mí cuando seas más fuerte.' WHERE `ID`=3098 AND `locale`='esES' AND MD5(`RewardText`)='6354348f46956d36a5924b8e6271cddd';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Hablé de los esclavos que siguen siendo esclavos, sea cual sea su amo. ¿Lo recuerdas? Ambos sabemos que es ese tipo de control, ese tipo de poder, lo que nos guía ahora. Buscamos criaturas que nos sirvan. Ahora somos más poderosos y merecemos más respeto del que nos dan los otros... Por eso, intentamos conseguirlo.$B$BSeré tu aliado en esta lucha... la lucha por conseguir nuestra libertad. La libertad de forjar nuestras propias alianzas. Cuando te sientas $gpreparado:preparada;, vuelve a mí. Yo te enseñaré todo lo que sé.' WHERE `ID`=3099 AND `locale`='esES' AND MD5(`RewardText`)='2bb32e9beb5d1f2967e4f2755563d451';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Verás otras cosas también, así que, solo para tu información: verás enanos usando magia en combate en lugar de rifles, algunos de nosotros adorando a la Luz Sagrada como si fuéramos humanos y por último, y no menos importante, verás troggs. Ya aprenderás cosas sobre ellos más adelante, lo único que tienes que saber de momento es que estoy aquí para ayudarte.$B$BEstoy aquí para convertirte en un $gun verdadero:una verdadera; $C. Cuando sientas que necesitas un poco de entrenamiento, vuelve aquí y veremos qué puedo hacer.' WHERE `ID`=3106 AND `locale`='esES' AND MD5(`RewardText`)='9a2a7c9fad706e6716a1d445507c0c6c';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Los humanos nos han enseñado mucho sobre la Luz Sagrada y lo importante que su orden es para ellos... y para proteger a todo Azeroth. Respetamos su arraigada tradición y el hecho de que una sola figura, un solo sacrificio pueda marcar la diferencia entre el dolor y la salvación.$B$BNosotros dos vamos a trabajar juntos durante un tiempo. Cuando creas que estás estár $glisto:lista;, vuelve a mí y hablaremos de empezar tu entrenamiento. No podemos permitir que salgas al mundo sin estar $gpreparado:preparada;, ¿no te parece?' WHERE `ID`=3107 AND `locale`='esES' AND MD5(`RewardText`)='54059337d462c689c58e045e7f2bd126';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Hay algo que no deberías olvidar nunca: tienes que respetar el mundo en el que vives. Las bestias que elijan combatir a tu lado, el brillo de tu arma, el peso de tu munición, el mordisco del viento en tu cara... tienes que conocer bien estas cosas.$B$BYo haré lo que pueda para ayudarte, pero tú tendrás que hacer la mayor parte del trabajo. Cuando creas que estás $glisto:list;, vuelve y habla conmigo. Yo te instruiré cuando pueda.' WHERE `ID`=3108 AND `locale`='esES' AND MD5(`RewardText`)='77a3fe198d42ff556143e602dab10660';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Soy el único que puede instruirte ahora que comienzas a encontrar tu camino por el Valle de Crestanevada. Cuando te sientas $glisto:lista;, vuelve a mí. Te enseñaré uno o dos hechizos para expulsar a esos malditos troggs del Valle.$B$BLa Luz está de tu lado, junto con Forjaz, $N... Pero no te sientas presionado para convertirte en algo especial.' WHERE `ID`=3110 AND `locale`='esES' AND MD5(`RewardText`)='044bebf7280a565cd5283c46f8ded5f6';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Oh, sí! Artes Arcanas... claro.$B$BEsto es lo que necesitas saber, $N: no te metas en muchos líos, reserva algún dinerillo para invitarme a cerveza... o comprarme algún hechizo... y mantente $galejado:alejada; de Gnomeregan. Eso es todo. ¡Que tengas un buen día! Estaré por aquí por si me necesitas, o por si quieres entrenar o... lo que sea.' WHERE `ID`=3114 AND `locale`='esES' AND MD5(`RewardText`)='36f3382d7f31ec568e62cdf8da819548';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ven a verme a menudo mientras estés en Cañada Umbría; te ayudaré a entender el rol $gdel:de la; $C y tus capacidades.$B$BNo confíes demasiado en la ayuda de tus mascotas. En estos tiempos hay cosas más peligrosas de lo que puedas imaginar.' WHERE `ID`=3117 AND `locale`='esES' AND MD5(`RewardText`)='52f0a2add93bcf6dddfcbedf5b50d82a';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Saludos, joven. ¿Has venido para seguir el camino $gdel:de la; $c?$B$BMuy bien. Empecemos.' WHERE `ID`=3261 AND `locale`='esES' AND MD5(`RewardText`)='f92180ced03c80a6d580b59153ae6730';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¿Vienes de parte de Falla? Bueno, veamos el fragmento del que dices que era tan reacia a hablar... $B$B<Hamuul intenta mirar dentro del fragmento>$B$BOh... yo no.. bien.$B$B$n, Gracias por traérmelo. Pero no es muy inteligente hablar de cosas como esta, te lo advierto. No deberías meterte en este tipo de asuntos.$B$BDigamos que las cosas del Sueño Esmeralda no son como creíamos...$B$BQuizás nuestros caminos se vuelvan a encontrar en el futuro.' WHERE `ID`=3369 AND `locale`='esES' AND MD5(`RewardText`)='46d8123769add8ddbb33bc873919c11c';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¿Vienes de parte de Falla? Bueno, veamos el fragmento del que dices que era tan reacia a hablar... $B$B<Mathrengyl intenta mirar dentro del fragmento>$B$BOh... yo no.. bien.$B$B$n, gracias por traérmelo. Pero no es muy inteligente hablar de cosas como esta, te lo advierto. Son asuntos que deben quedar en manos de los druidas Cenarion.$B$BDigamos que las cosas del Sueño Esmeralda no son como creíamos...$B$BQuizás nuestros caminos se vuelvan a encontrar en el futuro.' WHERE `ID`=3370 AND `locale`='esES' AND MD5(`RewardText`)='f97bc1eefa73fc7e300b1d45716748dc';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Me alegro de verte $gsano:sana; una $gsalvo:salva;, $N.$B$BVoy a enviarle los calcos a Tymor; se va a emocionar con solo mirarlos.$B$BTira la pistola de bengalas; no creo que te sirva para nada y yo ya tengo una.' WHERE `ID`=3449 AND `locale`='esES' AND MD5(`RewardText`)='fc22117c15efa4ec6db5fa790e3f9d39';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Me produces asco, $R. ¿$gUn hombre hecho y derecho:Una mujer hecha y derecha; babeando sobre una pila de baratijas? ¡Qué pena das! Toma tu recompensa y desaparece de mi vista.' WHERE `ID`=3501 AND `locale`='esES' AND MD5(`RewardText`)='400c4fc23a230afb50f0d25773e9a781';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Me produces asco, $r. ¿$gUn hombre hecho y derecha:Una mujer hecha y derecha; babeando sobre una pila de baratijas? ¡Qué pena das! Toma tu recompensa y desaparece de mi vista.$B$B¿Te suena? Debería, porque lo digo mil veces al día.$B$B¡Oh, cómo aborrezco este mundo!' WHERE `ID`=3502 AND `locale`='esES' AND MD5(`RewardText`)='3ad74ef6e1aaab341905aff139bc580f';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Al $guno digno:una digna; de la sabiduría de Arkkoroc!' WHERE `ID`=3510 AND `locale`='esES' AND MD5(`RewardText`)='28d4a24d97409690c595b7b4f1eab636';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Eres $gduro:dura;! La limpieza de El Cubil de Rynthariel es un gran avance, $N. Tardarán en reagruparse y por lo tanto, cabe esperar que habrá menos mensajeros de la Alianza en Los Baldíos. Se lo pensarán dos veces antes de volver a enviar alguno hacia aquí.$B$BGracias.' WHERE `ID`=3514 AND `locale`='esES' AND MD5(`RewardText`)='9df6f9aef7b2d5e367e787fa70cee28e';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Pareces curtida por la batalla, $N. ¿Estás $gpreparado:preparada; para enfrentarte a Razelikh y a sus esbirros?' WHERE `ID`=3626 AND `locale`='esES' AND MD5(`RewardText`)='b6154c319bcb75b4a388dcb838ba3686';
UPDATE `quest_offer_reward_locale` SET `RewardText`='En vista de que eres $gun:una; profesional de la ingeniería goblin con buena reputación, te voy a renovar tu tarjeta caducada por una cuota de dos piezas de oro. Cuando hayas pagado esta cuota, recibirás una nueva tarjeta de miembro con la que podrás recibir nuevos esquemas de ingeniería goblin de los instructores apropiados.$B$BEsta tarjeta tiene una validez de dos semanas de actividad, período tras el cual tendrás que pagar la cuota de nuevo. Si quieres tener acceso a los esquemas, tendrás que saldar tus deudas antes.' WHERE `ID`=3644 AND `locale`='esES' AND MD5(`RewardText`)='1a16323b1762a5352569ac6bb8257db7';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Gracias por encontrar mi collar, $gseñor:señora; $C... Mi gatita también dice gracias, ¿a que sí, Effsee?' WHERE `ID`=3741 AND `locale`='esES' AND MD5(`RewardText`)='4ed34adc1772c9c060adaf9ec86f9921';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Saludos, $C. Me alegro de ver que te $ginteresado:interesada; colaborar en nuestra investigación. Queda mucho trabajo por delante y te mentiría si te dijese que no entraña peligro. Esperemos que esto no te haga desistir... aunque ya se ve que no es la primera vez que le plantas cara al peligro.' WHERE `ID`=3762 AND `locale`='esES' AND MD5(`RewardText`)='50d6fe3cb1f0ba7d74a3d5a63d5d9d27';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Así que te ha enviado aquí mi hermano Argos, ¿eh? Supongo que debes de estar $gagotado:agotada; de tanto viaje. Pero tenemos mucho que hablar.' WHERE `ID`=3765 AND `locale`='esES' AND MD5(`RewardText`)='97118d2df30624d17f09b54fd9154f7a';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Gracias por venir, $gviajero:viajera;! Permite que me presente: soy Quintis Jonguja, druida y humilde servidor de Malfurión y del Círculo Cenarion. Mis colegas (el general Shandris Plumaluna y el Protectorado, igual has oído hablar de nosotros) y yo, queríamos hablar contigo sobre el trabajo que estás haciendo para Fandral Corzocelada en Darnassus.$B$BAntes de proseguir, quisiera pedirte que esta conversación quede entre nosotros. Si esto no te supone un problema, podemos continuar.' WHERE `ID`=3788 AND `locale`='esES' AND MD5(`RewardText`)='a096fd682bcc7b0206da9cf6b3ccbde1';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Bien, $C, veo que fuiste $ginformado:informada; de que yo encabezaba la investigación en persona, y es evidente que viniste tan rápido como pudiste. $B$BAhora que estás aquí, presta atención, pues te daré los detalles una sola vez, no me gusta repetirme.' WHERE `ID`=3790 AND `locale`='esES' AND MD5(`RewardText`)='47d7fafd1ceae90eadcab3533f1a7d1b';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Fantástico trabajo, soldado! ¡Sencillamente asombroso! Oh, me darán la medalla al valor por esto, digo… que ¡te $grecompensado:recompensada; generosamente por esto!' WHERE `ID`=3825 AND `locale`='esES' AND MD5(`RewardText`)='335e95c0af69d9a177a309d1328eb937';
UPDATE `quest_offer_reward_locale` SET `RewardText`='He acabado contigo, $N. Has demostrado ser $gmerecedor:merecedora; de la libertad que te ha sido concedida. Muchos serán los que se alzarán contra ti por lo que eres ahora, pero debes saber que, intenten lo que intenten contra nosotros, somos libres y no volverán a encadenarnos.$B$BCoge esto y ponte en camino. Tienes mucho que lograr, $C.' WHERE `ID`=3901 AND `locale`='esES' AND MD5(`RewardText`)='520b9719376394694995e9760063aaec';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Buen trabajo, $N, sabía que no eras $gun:una; inútil. Ten, acepta uno de los mejores objetos que he encontrado entre los lotes que hemos reunido hasta ahora.' WHERE `ID`=3902 AND `locale`='esES' AND MD5(`RewardText`)='fc357f7c773fec23b8dbae3f76820563';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Gracias $n! traerme la uva! Espero que hayas dado una lección a unos cuantos Defias.$B$B¡Aunque tengamos pocas tropas, tenemos la suerte de contar con valientes como tú!' WHERE `ID`=3904 AND `locale`='esES' AND MD5(`RewardText`)='fa455bfb533ecbdc63ff6afc13da910e';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¿Qué es esto? ¡¿Qué?! ¡Es un churumbele! ¿Dónde lo has conseguido? ¿Has estado curioseando por las instalaciones de Ventura y Cía. en Los Baldíos?$B$BDebes de ser muy valiente, o muy $gestúpido:estúpida;.' WHERE `ID`=3923 AND `locale`='esES' AND MD5(`RewardText`)='bdc6e560cb276cf4615fdd28081844d3';
UPDATE `quest_offer_reward_locale` SET `RewardText`='<Thrall se muestra muy afectado por la información que acabas de darle.>$B$BUna nueva amenaza se cierne sobre el horizonte. Se acaban los años de Magni y con ello tendrá vía libre la estirpe no nata de Hierro Negro para gobernar Forjaz.$B$BHas cumplido lo que te había encargado y por ello serás $grecompensado:recompensada;.$B$B¡Márchate, $N! Debo discutir algo con Sylvanas y Cairne.' WHERE `ID`=4004 AND `locale`='esES' AND MD5(`RewardText`)='734a106185229e17c0ae01ebba479a2d';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡La encontraste! ¡Muy bien! ¡Y espero que les dieras a esos Hierro Negro y a Hurley Negrálito una buena paliza!$B$BLos Cebatruenos están a tu servicio, $N. ¡Eres $gun héroe:una heroína; entre $ghéroes:heroínas;!' WHERE `ID`=4126 AND `locale`='esES' AND MD5(`RewardText`)='cc4fb477e1a6e3f275407b8b7c3ce24b';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Has $n, bien en venir a verme! Cualquiera puede aprender lo básico en ingeniería; mira a los gnomos de Gnomeregan. Pero hace falta mucha inteligencia y mucha, mucha firmeza para dominar los principios de la ingeniería goblin.$B$BEscucha con atención, $n, y aprende todo lo que puedas.' WHERE `ID`=4181 AND `locale`='esES' AND MD5(`RewardText`)='3730e3edab0a84f4b3a3db7297331669';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Lo has logrado! Ahora puedo preparar mi poción y usarla sobre Sinroca. ¡Por fin caerá víctima de mis encantos!$B$BGracias, $N. ¡Eres $gun campeón:una campeona; del amor!' WHERE `ID`=4201 AND `locale`='esES' AND MD5(`RewardText`)='f431dce87beebfbfc24b46fdc4e0d9bd';
UPDATE `quest_offer_reward_locale` SET `RewardText`='“¡Dios mío! ¿Estás $gseguro:segura; de que Incendius dijo “”Ragnaros?””$B$B<Jalinda te tiende algo y te da una palmada en la muñeca y se queda pensativa.>”' WHERE `ID`=4263 AND `locale`='esES' AND MD5(`RewardText`)='8d373f7aed383107af5cd19a6049be9b';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Bienvenido a casa, $N. Raschal llegó hace no mucho y me contó lo que ocurrió.$B$BYo... no, todo el Bastión, te agradece enormemente lo que has hecho. Raschal habría muerto si no hubieras llegado tú, y tu ayuda nos ha llegado por apenas la tasa de un mercenario. Eres $gun auténtico héroe:una auténtica heroína;. Siempre contarás con la amistad de Ginro Mechogar.' WHERE `ID`=4265 AND `locale`='esES' AND MD5(`RewardText`)='4fa6c3b2391b65222e7ce9f1c0c6a41c';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Esta carne servirá, $N. Parece que Lar''korwi no pasa hambre, ¿eh? Me pregunto dónde habrá encontrado un trillanodonte... es extraño.$B$BDe cualquier modo, guardaré esto hasta que estés $gpreparado:preparada; pare enfrentarte a él. No te preocupes por mí, pues estoy seguro de que has enfadado tanto a Lar''korwi que no me hará daño hasta que te haya echado el diente a ti.' WHERE `ID`=4290 AND `locale`='esES' AND MD5(`RewardText`)='ee956edae8d2c0a61d326bc0663880a4';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Alabada sea la Madre Tierra! ¡Lo has conseguido! No cabe duda de que eres $gun:una; gran $gcazador:cazadora;. Has demostrado poseer fortaleza de espíritu y una valentía inigualable, y además has incrementado tu fuerza. Mereces todo mi respeto.$B$BSolo el más poderoso de mis ancestros habría sido capaz de realizar una hazaña como la tuya. Enhorabuena.' WHERE `ID`=4292 AND `locale`='esES' AND MD5(`RewardText`)='271ce4c354897e39975d7e7851cffd59';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¿Qué es esto? ¡Ah! ¡Es el aroma de la cerveza Hierro Negro! La bebida me nubla la vista pero puedo decirte algo, $gseñor:señora;, ¡tú sí que eres $gun amigo:una amiga;!' WHERE `ID`=4295 AND `locale`='esES' AND MD5(`RewardText`)='0cd984511b232215dbe6e08a7b47c9fa';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Ah, has encontrado la tablilla! ¡Y tu transcripción es excelente! Seguro que eres $gun:una; $C y no $gun:una; escriba?$B$BAquí tienes, $N. Aquí tienes el pago que te prometí.' WHERE `ID`=4296 AND `locale`='esES' AND MD5(`RewardText`)='0400fd772bce55adaaec44c61f404bcf';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Es una noticia excelente, $N. Con esas bestias fuera de nuestro camino podemos pensar en adentrarnos en Cuna del Invierno. ¿Estás $glisto:lista; para más?' WHERE `ID`=4521 AND `locale`='esES' AND MD5(`RewardText`)='ccebe9ac0e4758eae058f147172add60';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Otro de los reclutas de Kaltunk, ¿eh?$B$BPues sí que están mal las cosas, si esto es lo mejor que puede ofrecer la Horda. No importa. Para cuando te llegue el momento de salir del Valle, serás $gun:una; $c $gdigno:digna; de la Horda.' WHERE `ID`=4641 AND `locale`='esES' AND MD5(`RewardText`)='80a45253da39122b7b6b8342a60df0c5';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ah, te envía Brezospina. Bien. Entonces la voz se corre muy lejos para encontrar futuros alumnos. Me gusta.$B$BEs normal entre los de nuestra clase, $N, arrimar el hombro, independientemente de la raza. Es especialmente importante ya que aquellos con los que tratamos no hacen diferencias en su malicia si no logramos apaciguarlos o controlarlos debidamente.$B$BMe da la impresión de que has aprendido muchas cosas y, si estás $gdispuesto:dispuesta;, te ayudaré a crear herramientas a la altura de tus habilidades.' WHERE `ID`=4736 AND `locale`='esES' AND MD5(`RewardText`)='e2cc1cd992103c33e7be6b951193c77c';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ah, te envía Zevrost. Bien. Entonces la voz se corre muy lejos para encontrar futuros alumnos. Me gusta.$B$BEs normal entre los de nuestra clase, $N, arrimar el hombro, independientemente de la raza. Es especialmente importante ya que aquellos con los que tratamos no hacen diferencias en su malicia si no logramos apaciguarlos o controlarlos debidamente.$B$BMe da la impresión de que has aprendido muchas cosas y, si estás $gdispuesto:dispuesta;, te ayudaré a crear herramientas a la altura de tus habilidades.' WHERE `ID`=4737 AND `locale`='esES' AND MD5(`RewardText`)='707248d318a0b1a30a97fa3ed003f688';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ah, te envía Demisette. Bien. Entonces la voz se corre muy lejos para encontrar futuros alumnos. Me gusta.$B$BEs normal entre los de nuestra clase, $N, arrimar el hombro, independientemente de la raza. Es especialmente importante ya que aquellos con los que tratamos no hacen diferencias en su malicia si no logramos apaciguarlos o controlarlos debidamente.$B$BMe da la impresión de que has aprendido muchas cosas y, si estás $gdispuesto:dispuesta;, te ayudaré a crear herramientas a la altura de tus habilidades.' WHERE `ID`=4738 AND `locale`='esES' AND MD5(`RewardText`)='89e678cb70eaf3e4f32e1726077ca432';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Vaya, diría que no has venido aquí solo a informarte! Los ciudadanos estarán encantados de saber que hoy podrán dormir un poco más tranquilos.$B$BHas traído un poco de paz y justicia a la gente de Auberdine, $N y por eso, quisiera ofrecerte esto como recompensa... Serás $gel héroe:la heroína; de las gentes de Auberdine.' WHERE `ID`=4740 AND `locale`='esES' AND MD5(`RewardText`)='b005b8dab4d607f880f6f7b1fcecd247';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Has derrotado a Vectus! Y dime, ¿funcionó el Gambito del Alba?$B$BOh... Aunque no funcionara como yo esperaba, me alegro de que supieras manejar la situación. ¡Bien hecho, $n!$B$BAlba Argenta y las gentes de Azeroth están en deuda contigo.' WHERE `ID`=4771 AND `locale`='esES' AND MD5(`RewardText`)='efed0aa1073f8ead35315ebfeb41e804';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Bien, has vuelto, $N. ¿Y dónde está el hilo?$B$BAh, entiendo. Eso es aceptable. El goblin y su hermano no nos han fallado todavía, supongo que es comprensible que no lo tuviera preparado entonces. Bueno, sea... tenemos otras cosas a las que dedicarnos mientras tanto.$B$B¿Estás $gpreparado:preparada; para el paso siguiente?' WHERE `ID`=4782 AND `locale`='esES' AND MD5(`RewardText`)='34145bebfcdef9e85337b6bb52fe059a';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Fantástico, $N. Estos restos nos servirán. Los prepararé ahora mientras tú sigues con los 2 últimos componentes. ¿Estás $glisto:lista;?' WHERE `ID`=4783 AND `locale`='esES' AND MD5(`RewardText`)='a3b1cb17686c44538d800561e289465b';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Fantástico, $N! Tenemos todos los componentes y estamos $glisto:listas;.$B$BConfío en que te agradará el resultado.' WHERE `ID`=4784 AND `locale`='esES' AND MD5(`RewardText`)='734e1a34e0c2a24ca39a54af14245f25';
UPDATE `quest_offer_reward_locale` SET `RewardText`='No esperaba oír menos, $gmuchacho:muchacha;. Imaginaba que esas bestias enloquecidas habrían destruido todas mis pertenencias...$B$BPero encontraste mis herramientas y, lo más importante, ¡el amuleto! Me pregunto por qué los lechúcicos defendías tan fervientemente este objeto... En cualquier caso, ¡me lo pensaré dos veces antes de volver a cruzarme en su camino!' WHERE `ID`=4864 AND `locale`='esES' AND MD5(`RewardText`)='a0cc5033c937049fc3f05ff016d6a0f6';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Eso es! Ya siento cómo vuelven mis poderes. Y mi mente ya no sufre el atroz dolor de la maldición de Urok.$B$B¡Gracias, $N! Estoy por encima de la humildad pero debo reconocer tu ayuda.$B$BY te deseo que la Fortuna te acompañe en tus viajes por la Cumbre de Roca Negra. Eres $gun necio:una necia; si crees que vas a alcanzar la cumbre pero tu valor es incuestionable.' WHERE `ID`=4867 AND `locale`='esES' AND MD5(`RewardText`)='4798fd9ed712ce84cd9f1a043d9cf9d2';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ah, sí que buscas algo con más... sustancia. En eso te puedo ayudar si estás $gpreparado:preparada; de verdad.$B$BEs un cambio agradable ver que $guno:una; de nuestra clase busca más poder en formas distintas al conocimiento.$B$BAsí que ¿sientes que estás $gpreparado:preparada;, $N?' WHERE `ID`=4965 AND `locale`='esES' AND MD5(`RewardText`)='851233ca3344826a1be6ef609a11b33f';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Esto es exactamente lo que necesito, $N. Gracias.$B$BPermíteme recompensarte adecuadamente. Quizás no comprendas para qué podrías necesitar un instrumento así. Puede que ni siquiera sepas qué es. Ay... no puedo decirte cuándo te será de utilidad, pero tienes que saber que llegará un momento en el que lo encontrarás extremadamente útil. Decidas o no conservarlo hasta que llegue ese momento... esto, $gamigo mío:amiga mía;, es tuyo.' WHERE `ID`=4972 AND `locale`='esES' AND MD5(`RewardText`)='f3214415c997392c93a8e66674dd8a22';
UPDATE `quest_offer_reward_locale` SET `RewardText`='No te mentiré, $r. ¡Necesitaba el dinero! Kibler paga muy pero que muy bien, mucho mejor de lo que lo haría nunca la F.E.K.$B$B¡Pero no pongas en duda mi lealtad! ¿Por qué crees que estoy aquí abajo? ¿Para conseguirle a algún goblin chalado unas patas de algún animal exótico o algo igualmente estúpido? No, solo alguien realmente tonto vendría a la Cumbre de Roca Negra para conseguir mascotas. Sí, y no creo que haya mucha gente así en este mundo.$B$B<Bijou suelta una carcajada.>$B$BLo último que necesitamos es esa clase de gente reproduciéndose.' WHERE `ID`=4981 AND `locale`='esES' AND MD5(`RewardText`)='9b313269ddbab783a5686814aa708c83';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Lo has logrado! Cuando Lexlort tenga estos planos, se olvidará de todas esas cosas desagradables que quería hacerme.$B$B$N, ¡eres $gmi héroe:mi heroína;!' WHERE `ID`=4982 AND `locale`='esES' AND MD5(`RewardText`)='155b944888301d219c753a445d9c3019';
UPDATE `quest_offer_reward_locale` SET `RewardText`='"Sé que los pardos ahora están en paz, y su tormento ha terminado. Yo... tengo algo más para ti. Lo escribí en... en esta rama, porque presentía que mi tiempo en este reino estaba por terminar.$B$BAsí es... mi vida se acaba. Gracias de nuevo, $gamigo:amiga;... Las criaturas de esta tierra maldita pueden descansar... y ahora las acompañaré".$B$BCon esas últimas palabras, el druida emite una profunda exhalación hasta perder el aliento. Su cuerpo yace inmóvil en el piso de la cabaña.' WHERE `ID`=4985 AND `locale`='esES' AND MD5(`RewardText`)='b9047dc6e8ebf96fd609e0843248ed78';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Esto... esto es muy extraño. Este druida, un druida tauren nada menos, te ha confiado mucha y valiosa información sobre la extensión de la Peste de la Plaga. Me sorprende que un tauren diera a $gun:una; $R tal información y mucho más si todo lo que dices es cierto. Haremos un buen uso de esto, te lo prometo. Quizás el tauren no cayera tan lejos de Cenario como Fandral podría pensar...$B$BErrr... de cualquier forma, por favor, acepta esto como muestra de gratitud del Círculo Cenarion.' WHERE `ID`=4986 AND `locale`='esES' AND MD5(`RewardText`)='8854471835b534bf05d7f733c3389ab0';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Que no falle tu disparo y la marca de tu arma sea verdadera, $R. $B$BEl espíritu de Agamaggan está contigo. Vuelve  aquí si quieres. Quebrantadientes volverá a bendecirte si el gran dios jabalí me considera $gdigno:digna;.' WHERE `ID`=5043 AND `locale`='esES' AND MD5(`RewardText`)='228f7b3d2bf49fa6a77f790b8f783fae';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Cierto, me llamo Emma Piedra Mácula, eres la primera persona que me llama así en años. ¿Quién... quién eres?$B$BDices que conoces... ¿a mi hermana? ¿¿Está viva?? A quién quiero engañar, claro que no. Cuando la Peste cayó sobre Lordaeron, me temí lo peor. Muchos de mi familia murieron... o sufrieron un destino peor. Y aquí estoy ahora, la vieja loca Emma, sola. ¿A qué te dedicas, $gun ladrón:una ladrona; profanar tumbas o algo así? ¿Buscas a tu próximo objetivo?$B$B¿Qué...? ¿Tienes un paquete para mí de mi hermana?' WHERE `ID`=5048 AND `locale`='esES' AND MD5(`RewardText`)='8993ea6b219369560e4b144c935995a0';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Sí. Has regresado. Ahora creo que eres un auténtico $c por naturaleza. Te has enfrentado a las criaturas más fieras y has regresado, superando todas mis expectativas.$B$BYa estás preparado para mi última petición.' WHERE `ID`=5055 AND `locale`='esES' AND MD5(`RewardText`)='48a5d9d53cab99d02231beb800e3436c';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Aprendemos de nuestras experiencias vitales, $N. Estoy seguro de que las tuyas solo conseguirán hacerte más fuerte y $gsabio:sabia;. Has crecido mucho desde la primera vez que hablamos.$B$BToma esto como recuerdo de todas las difíciles tareas que has superado como $r $C, y no olvides que siempre tendrás mi respeto y admiración.' WHERE `ID`=5057 AND `locale`='esES' AND MD5(`RewardText`)='722a1b735cd2109fe1afc2e0140e8e9b';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Impresionante, $N. Me $glisto:lista; de alegría poder enseñarte tu Forma acuática.$B$BAcepta esto como premio por tus logros en las dos pruebas; espero que te ayude en tu equipamiento como $gprotector:protectora; de proteger la naturaleza y $gguardián:guardiana; del equilibrio.' WHERE `ID`=5061 AND `locale`='esES' AND MD5(`RewardText`)='6b76f07ecd047b023a2d212f33f4f085';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Misión cumplida, $N! Buena jugada, buena jugada.$B$BDéjame recompensarte por tu trabajo con algunas monedas de las arcas de Ventormenta. Te recomendaría gastar el dinero en algo que te ayude en tu próxima misión... la que te llevará a las ruinas de Andorhal.$B$B¡Deberás estar $gpreparado:preparada;! ¡Mantente alerta!' WHERE `ID`=5092 AND `locale`='esES' AND MD5(`RewardText`)='9519f4bcd20fbcda451b6b74858a289d';
UPDATE `quest_offer_reward_locale` SET `RewardText`='$gBienvenido:Bienvenida; a las Tierras de la Peste, una de las fronteras más peligrosas de Azeroth, sobre todo con la amenaza de la Plaga desde el este. ¡Me alegra que hayas sentido la llamada del deber!$B$BNo te $gpreparado:preparada; misiones en estas desgraciadas tierras.' WHERE `ID`=5093 AND `locale`='esES' AND MD5(`RewardText`)='5341497c24fa33b91462d101ce399b66';
UPDATE `quest_offer_reward_locale` SET `RewardText`='$gBienvenido:Bienvenida; a las Tierras de la Peste. Esta es una de las fronteras más peligrosas de Azeroth, especialmente por la amenaza de la Plaga que se avecina desde el este. Me alegro de que hayas escuchado la llamada del deber y hayas venido a prestar servicio a la Horda. $B$BSi estás $gpreparado:preparada; para ponerte manos a la obra, hay mucho que puedes hacer aquí, en la frontera de las Tierras de la Peste.' WHERE `ID`=5095 AND `locale`='esES' AND MD5(`RewardText`)='b94a259fd1157ddd2da22972d554537c';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Que el poder de la Luz te ilumine en estos tiempos sombríos, $C. Me complace servirte como coordinadora en nuestro plan para sabotear las calderas de la Plaga.$B$BNuestro objetivo será alterar la composición de la peste que crean los calderos, convirtiéndola en algo que afecte negativamente a la Plaga. Para conseguir este cambio tendrás que acceder a las cuatro calderas de las Tierras de la Peste del Oeste.$B$BHas de estar $gpreparado, héroe:preparada, heroína;, ¡te espera una batalla gloriosa contra la vil Plaga!' WHERE `ID`=5215 AND `locale`='esES' AND MD5(`RewardText`)='17a67f9eaff6d6fadf2e6ffc63a3b1dd';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Desde las sombras, $ghermano:hermana; $R, te hago llegar mis saludos. Estoy aquí para servirte como coordinadora en nuestro plan para sabotear las calderas de la Plaga. $B$BNuestro objetivo será alterar la composición de la peste que crean las calderas, convirtiéndola en algo que afecte negativamente a la Plaga. Para conseguir este cambio tendrás que acceder a las cuatro calderas de las Tierras de la Peste del Oeste. $B$BHa llegado el momento de que lideres el ataque contra la Plaga, $ghéroe:heroína;.' WHERE `ID`=5228 AND `locale`='esES' AND MD5(`RewardText`)='590b812d5ddde9a3490e16f34e49b71d';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Felicidades, $N, ¡has conseguido abrirnos la última caldera! El boticario Dithers pronto sabrá qué componentes se necesitan para la mezcla. $B$BEn cuanto a ti, seguro que el sumo ejecutor Derrington querrá agradecerte personalmente la ayuda que nos has prestado. Sin ti nuestra lucha contra la Plaga habría sido prácticamente insuperable. Muchas gracias, $gpoderoso:poderosa; $C.' WHERE `ID`=5236 AND `locale`='esES' AND MD5(`RewardText`)='2e8cf1ccafbb22074c037c1d6a52a8c3';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Bien hecho, $R. Has demostrado que, aunque eres $gcompasivo:compasiva;, no te detendrás ante nada para destruir a los esbirros de Kel''Thuzad.' WHERE `ID`=5243 AND `locale`='esES' AND MD5(`RewardText`)='6b2a30f059a34b2a23836c254439d272';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¿$gUn alumno:Una alumna; de Daryn Brisela? Un placer conocerte, $N.' WHERE `ID`=5250 AND `locale`='esES' AND MD5(`RewardText`)='1466b9d308b47e47725c177e6de2dbe5';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Hace muchos años que no recibo a $gun campeón:una campeona; entre nosotros. Eres $gel primero al:la primera a la; que Lord Maxwell recibe en años.' WHERE `ID`=5263 AND `locale`='esES' AND MD5(`RewardText`)='f3a6605d8173b09d4172a191d6fa3963';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Eres $gun valioso aliado:una valiosa aliada;, $N. Recogerás los frutos de tu incondicional dedicación.' WHERE `ID`=5264 AND `locale`='esES' AND MD5(`RewardText`)='8af85c186ed93efea9369f5854c6ebce';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Un trabajo excelente, $r. Ahora, para asegurar mi herencia...' WHERE `ID`=5341 AND `locale`='esES' AND MD5(`RewardText`)='e424c0b5ac5b7381ab9224715683cb01';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Este es un día glorioso! Por fin, la gangrena de la casa Barov ha sido eliminada, ¡y mi fortuna está asegurada!$B$BToma esto y desaparece de mi vista, $gcampesino:campesina;.' WHERE `ID`=5344 AND `locale`='esES' AND MD5(`RewardText`)='fd60f302358bcb4a3186a5b35d3fc7ae';
UPDATE `quest_offer_reward_locale` SET `RewardText`='No sé de qué conoces a mi hermano pero parece que confía en ti, $C.$B$BYo soy Nataka Cuernolargo y te doy la bienvenida al Campamento del Espíritu Errante. ¡La ayuda de $gun:una; $C nunca viene mal! Habla con los demás, seguro que hay algo que puedas hacer.' WHERE `ID`=5361 AND `locale`='esES' AND MD5(`RewardText`)='baa942cc58c1d05b1962bdb95951fcbb';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Felicidades, $N. ¡Es un placer recompensarte con una muestra de valor del Alba Argenta!$B$BAdquirir una muestra de valor de esta forma indica que eres un auténtico héroe de la causa del bien. Valoramos todo esfuerzo hecho contra la Plaga, ¡pero acabar con uno de sus líderes es un auténtico avance hacia su derrota!$B$B¡Por el Alba, $ghermano:hermana;!' WHERE `ID`=5404 AND `locale`='esES' AND MD5(`RewardText`)='807e34ad6317c778f066e9fe1ca6fa76';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Felicidades, $N. ¡Es un placer recompensarte con una muestra de valor de El Alba Argenta!$B$BAdquirir una muestra de valor de esta forma indica que eres un auténtico héroe de la causa del bien. Valoramos todo esfuerzo hecho contra la Plaga, ¡pero acabar con uno de sus líderes es un auténtico avance hacia su derrota!$B$B¡Por El Alba, $ghermano:hermana;!' WHERE `ID`=5406 AND `locale`='esES' AND MD5(`RewardText`)='c8c2c7b14c52409bfc6a5695cd982b83';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Que los espíritus te bendigan, $N. Has hecho más por Grunth de lo que nunca hubiera pensado. Gracias, eres la plasmación perfecta de lo que significa ser $gun héroe:una heroína; de la Horda.$B$BPor favor, si tienes algo de tiempo, vuelve a visitarnos. Sé que a Grunth le gustaría, y a mí también.$B$BGrunth se ha divertido mucho contigo, $N, y ha querido darte una de sus mascotas favoritas para que no te olvides de él.' WHERE `ID`=5502 AND `locale`='esES' AND MD5(`RewardText`)='d3e08aef636997c9fd9c84699f15ad52';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Excepcional, tu tributo al Alba queda debidamente anotado, $N. Logrado esto me es un placer poner a tu disposición nuestros mantos. Mientras mantengas tu estatus con nosotros podrás adquirir estos mantos de cualquier intendente autorizado del Alba Argenta.$B$B¡Por el Alba, $ghermano:hermana; mío!' WHERE `ID`=5507 AND `locale`='esES' AND MD5(`RewardText`)='79da258f27f0051a8d1f2ecf3784c254';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Enhorabuena, $N. Me enorgullece recompensarte con una muestra de valor del Alba Argenta.$B$BConseguir una muestra de valor como lo has hecho tú indica que eres un auténtico héroe del Bien. Valoramos todos los esfuerzos que tengan como objetivo acabar con la Plaga, pero acabar con uno de sus líderes... ¡eso sí que les llevará a una derrota aplastante!$B$B¡Por el Alba, $ghermano:hermana;!' WHERE `ID`=5508 AND `locale`='esES' AND MD5(`RewardText`)='1af960bb673d48b8dc435971a76b1764';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Excelente. Apreciamos tu tributo al Alba, $N. Ahora, puedo deleitarme ofreciéndote uno de nuestros mantos para que lo compres. Mientras mantengas tu estado actual con nosotros, podrás adquirir cualquiera de estos mantos de cualquier intendente autorizado del Alba Argenta.$B$B¡Por el Alba, $ghermano:hermana; mío!' WHERE `ID`=5513 AND `locale`='esES' AND MD5(`RewardText`)='55b40c66820b59f0f7e6ab040c69c73b';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Sí, esto servirá. Mete por aquí, saca por allí... Je, je, ¡funcionará de maravilla! <La cara del goblin se ilumina con una amplia sonrisa.>$B$BYa está, ya estás $glisto:lista;. Pero recuerda que no es el objeto mejor elaborado del mundo. Te durará diez minutos y luego se deshará, ¡y entonces no engañarás a nadie! Póntelo poco antes de acercarte a él y recuerda que el traje solo le hará pensar que eres $gun aliado:una aliada;, ¡no su mejor $gamigo:amiga;!' WHERE `ID`=5518 AND `locale`='esES' AND MD5(`RewardText`)='fe85d25c6da1b1a3d06472bdba63f4fe';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Tú... eres $gel:la; mejor. Todos los demás no te llegan ni a la rodilla. ¡Gracias por liberarme!$B$B¡Sabía que mi destino no era acabar siendo el aperitivo de algún ogro!' WHERE `ID`=5525 AND `locale`='esES' AND MD5(`RewardText`)='9e1421e6751fa60a5e661b2e05df0398';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Bien hallado $C. He dedicado una parte importante de mis recientes estudios a Scholomance y creo conocer un medio para adquirir una llave... una que te permita cruzar la puerta delantera.$B$BSolo puedo imaginar las atrocidades que podrán verse en su interior, $N. No sé cómo hacéis $glos héroes:las heroinas;...' WHERE `ID`=5533 AND `locale`='esES' AND MD5(`RewardText`)='63ace73b14ba12ad743832b22fc4289e';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Muy bien, $C. Veo que no solo eres $ghabilidoso:habilidosa; sino también $gastuto:astuta;. La derrota de tales criaturas es un testimonio de tu lealtad a los inquilinos de la Madre Tierra, aunque no la reconozcas como tu propia deidad. Está presente en todas las cosas de este planeta y más allá. Sus ojos, uno oscuro y otro claro, viajan por el cielo siempre pendientes de nosotros.$B$BAcepta este puñado de monedas como muestra de aprecio por lo que has hecho.' WHERE `ID`=5536 AND `locale`='esES' AND MD5(`RewardText`)='ac5f9dcd8e765501925815e0af028f8e';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Que la Luz te guarde! $gBendito:Bendita; seas, joven.' WHERE `ID`=5544 AND `locale`='esES' AND MD5(`RewardText`)='ce83656f66f027264a0c226740ae7e7d';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Eres $gdigno:digna; de elogio, $N. Con tus esfuerzos has contribuido enormemente a la lucha contra la amenaza demoníaca y, gracias a eso, todo Azeroth está más seguro.' WHERE `ID`=5581 AND `locale`='esES' AND MD5(`RewardText`)='8cf6871df6a4da4c2e95b0d77a7de62d';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Lo has hecho muy bien y has servido a Elune. Por ello, te doy las gracias.$B$BPor favor, coge esta toga como muestra de mi gratitud. Esto significa que te has ganado un lugar en nuestra orden. Si lo deseas, puedes lucirla con orgullo pero, en cualquier caso, siempre te reconoceremos con $guno:una; de $glos nuestros:las nuestras;.$B$BQue Elune esté contigo, $N, y muchas gracias.' WHERE `ID`=5621 AND `locale`='esES' AND MD5(`RewardText`)='bdf37453c2bbd5bdf4a08e346ab9e812';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Me alegra que Shanda te haya enviado a verme, $N. Me produce gran satisfacción poder instruir a $glos sacerdotes:las sacerdotisas; sacerdotes en los caminos de Elune.' WHERE `ID`=5622 AND `locale`='esES' AND MD5(`RewardText`)='8e1898211d0fd7701650e4c3644197da';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Bien, has vuelto justo a tiempo. Tenemos temas importantes que tratar, $N. Tus facultades son cada vez más poderosas y debemos asegurarnos de que estás $gpreparado:preparada;.' WHERE `ID`=5646 AND `locale`='esES' AND MD5(`RewardText`)='a3562dfcb6b3d00d8c91b14bfcd01b76';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Bien, entonces Kor''ja vive y sale a defendernos de esos maliciosos humanos. A menudo recuerdo los días en los que, en combate, se demostraba poder y eran los sabios los que a menudo destruían a aquellos que se apoyaban solo en su fuerza.$B$BHas hecho algo bueno por mí, $N. Ten esta toga. Puede que te ayude, puede que no, pero te la has ganado y me enorgullece de llamarte $ghermano:hermana;.' WHERE `ID`=5648 AND `locale`='esES' AND MD5(`RewardText`)='6abc9225b8fd9b4efb04b73c4ee643ce';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Por fin has llegado. No podrás superar las pruebas que tienes por delante con la sola ayuda de tu fe, joven. Has de ser $gávido:ávida; y actuar con apremio.' WHERE `ID`=5651 AND `locale`='esES' AND MD5(`RewardText`)='cfc9dc385662762397f06289634ab462';
UPDATE `quest_offer_reward_locale` SET `RewardText`='La redención de Fordring será una tarea difícil. ¿Estás $gpreparado:preparada;?' WHERE `ID`=5742 AND `locale`='esES' AND MD5(`RewardText`)='42c86c17704f7c7eae66b511df4306e1';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Sí, ¡eso es! Vuelvo a asombrarme ante tu enorme valentía. Es increíble lo que estás $gdispuesto:dispuesta; a hacer para lograr la victoria de las fuerzas oscuras.$B$BPermíteme formar aunque sea una pequeña parte de todo esto. He preparado un solvente especial que me permite conseguir un escarabajo como cabeza de la llave, dotándola del poder para abrir la puerta cerrada de Scholomance.$B$BAhí va...' WHERE `ID`=5803 AND `locale`='esES' AND MD5(`RewardText`)='2ef336ed0f426d821627c9eaaf55d082';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Sí, eso es! Yo... siempre me sorprenden tus muestras de astucia y valentía. Me dejan atónitos todos tus $gdispuesto:dispuesta; a hacer para alzarte con la victoria.$B$BAhora permíteme hacer mi pequeña parte. He preparado un disolvente especial con el que debería poder fijar el escarabeo como cabeza de la llave, imbuyéndola del poder para forzar la puerta de Scholomance.$B$BMe llevará solo un momento...' WHERE `ID`=5804 AND `locale`='esES' AND MD5(`RewardText`)='61bedeecdb00f85918979b0fa6901c61';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Yo era la consejera en la que más confiaba Tirion cuando era el Señor de Mardenholde. Me opuse abiertamente a la sentencia transmitida por la Orden de la Mano de Plata y fui desterrada por mi insolencia.$B$BHa tenido que pasar por mucho dolor y sufrimiento, $R. ¿Estás $gpreparado:preparada; para reparar todo el daño hecho a los Vadín?' WHERE `ID`=5861 AND `locale`='esES' AND MD5(`RewardText`)='7fcd843c9f443797bce1ef485647c7e7';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Gracias, $N. Estas nos servirán.$B$BSi estás $glisto:lista;, podemos pasar a la fase siguiente.' WHERE `ID`=5901 AND `locale`='esES' AND MD5(`RewardText`)='e1f37dca38216ab97ad4d554ed4302a0';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Sin duda la Dama Oscura no te cree $gmerecedor:merecedora; de enfrentarte a su Campeón. ¿Has venido para convertirte en la merienda de mis canes? No puede haber otro motivo para esta interrupción.' WHERE `ID`=5961 AND `locale`='esES' AND MD5(`RewardText`)='06e8e19d5cfc1f6575fd4e890d64eb83';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡El Libro de los Ancestros! ¡El que tanto tiempo llevaba extraviado! Me aseguraré de que este libro llegue al Alto Consejo. Hoy has hecho algo magnífico. Deberíamos agradecértelo, y te lo agradecemos ¡como a $gun:una; $ghéroe:heroína;!' WHERE `ID`=6027 AND `locale`='esES' AND MD5(`RewardText`)='850e9f0ab5937f84a28c9a0ad7c7054b';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Has hecho un buen trabajo, $N. Creo que estás $glisto:lista; para tu siguiente tarea.' WHERE `ID`=6062 AND `locale`='esES' AND MD5(`RewardText`)='5c0577944fdd24475688d6fd0bf1a616';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Sí, ha llegado la también estás $glisto:lista;...' WHERE `ID`=6074 AND `locale`='esES' AND MD5(`RewardText`)='d9b04de263b2a10a4f596a8119a44458';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Sí, ha llegado la también estás $glisto:lista;...' WHERE `ID`=6075 AND `locale`='esES' AND MD5(`RewardText`)='d9b04de263b2a10a4f596a8119a44458';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Vaya, $gun:una; joven $C. Sí, te concederé las habilidades que necesitas para domar y guiar a una mascota. No solo podrás enseñar nuevas habilidades a tu mascota, además podrás darle de comer, e incluso resucitarla si cae en combate.$B$BAhora, retírate. Hablaremos más adelante.' WHERE `ID`=6081 AND `locale`='esES' AND MD5(`RewardText`)='6f7cbeed1a1f33138885759a1c9386a6';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Saludos, joven $C. Me alegra ver que estás $gdeseoso:deseosa; de aprender las curas para los venenos.$B$BEn el pasado, muchos druidas eran sometidos a diversas pruebas, pero tu trabajo no implicará tal cosa. En Auberdine ha habido una epidemia de envenenamientos de animales, pero allí no han sabido curarla. Un representante de Auberdine ha pedido ayuda al Claro de la Luna y nosotros vamos a enviarte a ti como respuesta. No es una prueba ni un ejercicio: lo que hagas será real. Tenlo en cuenta.' WHERE `ID`=6121 AND `locale`='esES' AND MD5(`RewardText`)='ddf44100e1c1421434db4ac4420cf935';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Saludos, joven $C. Me alegra ver que estás $gdeseoso:deseosa; de aprender sobre venenos de sanación.$B$BEn el pasado, muchos druidas eran sometidos a diversas pruebas, pero tu trabajo no implicará tal cosa. En El Cruce de Los Baldíos ha habido una epidemia de envenenamientos de animales, pero allí no han sabido controlarla. Un representante de El Cruce ha pedido ayuda al Claro de la Luna y nosotros vamos a enviarte a ti como respuesta. No se trata de un ejercicio práctico, el trabajo que tendrás que realizar es real. Tenlo en cuenta.' WHERE `ID`=6126 AND `locale`='esES' AND MD5(`RewardText`)='e7bbf3ea9608dede2b239d94046a1b1d';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Buena cacería, $N! Besseleth es una vieja depredadora de esta zona... No la echaré de menos. Acepta esta recompensa por ser $gel campeón:la campeona; del bosque.$B$B$B$BQuizás ahora, muchos más irán al Refugio Roca del Sol sin temer lo que acecha en la oscuridad.' WHERE `ID`=6284 AND `locale`='esES' AND MD5(`RewardText`)='57d8735eb52d8c834c79a9e6f0239e64';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ah, un nuevo paquete de pieles. ¡Me pondré a trabajarlas de inmediato!$B$BGracias, $ghermano:hermana;. Me has hecho un gran favor. Aquí tienes unas monedas por tu tiempo y los gastos de viaje.' WHERE `ID`=6362 AND `locale`='esES' AND MD5(`RewardText`)='60db0f24a53a8c575cd6c97e5302357d';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¿Tenemos tan pocos soldados aptos que Nefarian se dedica a enviarme crías? Nunca superarás mis pruebas, $gcachorrito:cachorrita;.' WHERE `ID`=6570 AND `locale`='esES' AND MD5(`RewardText`)='643973c5cb0fe458f7c65f017f9a4197';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Dudaba de tu dedicación, $gmocoso:mocosa;. Has perseverado, dominando a nuestros enemigos, honorando a nuestro Vuelo.$B$BAhora debo preparar las calaveras para tu ascenso.' WHERE `ID`=6585 AND `locale`='esES' AND MD5(`RewardText`)='13af03427576d6b486cdaa2a7d8896c5';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Fantástico, $gamigo:amiga;. Mi hermano las necesita vivitas y coleando, si no, se vuelven amargas... Y no nos gustan los kebabs de rata amargos, ¿verdad?' WHERE `ID`=6661 AND `locale`='esES' AND MD5(`RewardText`)='628789ebbab0ca44724c6f03c8c20e7e';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Saludos, $gaventurero:aventurera;!$B$BLos goblins me han dicho que te has ganado un regalito especial. Aquí tienes. ¡Feliz Festival de Invierno!' WHERE `ID`=6984 AND `locale`='esES' AND MD5(`RewardText`)='a393d562bcdcdb32af2a818faa070211';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Espléndidamente espléndido! Me alegra ver que has vuelto con el residuo, ¡y con todos tus apéndices intactos, cabeza y todo! Eso está muy bien... no es que el Ultra-reductor fuera peligroso, pero, oye...$B$BAh, y aprecio mucho tu ayuda, $N. De verdad, eres $gun buen amigo:una buena amiga; de los goblins de todo el mundo. Acepta esto como muestra de mi agradecimiento.' WHERE `ID`=7003 AND `locale`='esES' AND MD5(`RewardText`)='87981c502334c975f59d0315e77a4c40';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Saludos, $gaventurero:aventurera;!$B$BLos goblins me han dicho que te has ganado un regalito especial. Aquí tienes. ¡Feliz Festival de Invierno!' WHERE `ID`=7045 AND `locale`='esES' AND MD5(`RewardText`)='a393d562bcdcdb32af2a818faa070211';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Es bueno ver a nuevos soldados aquí, $N, pero con un poco de suerte entrarás pronto en combate ¡y no serás $gun novato:una novata; por mucho tiempo! $B$BVuelve a hablar conmigo. Tengo tareas que tratar contigo...' WHERE `ID`=7121 AND `locale`='esES' AND MD5(`RewardText`)='9ef9862eac210717b384243e8e3ba1e6';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Que nuestros enemigos sepan que $gun:una; soldado de rango los ha atacado! ¡Lucha por la gloria de los Pico Tormenta!' WHERE `ID`=7168 AND `locale`='esES' AND MD5(`RewardText`)='d4a8cad74299c0f739c6e08a9f4cc995';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Cuando te conocí, nunca habría pensado que llegarías a ser $gun héroe:una heroína;. ¡Sigue así, soldado!' WHERE `ID`=7170 AND `locale`='esES' AND MD5(`RewardText`)='bfea5d2ac630e9296589e79de03ffec2';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Para convertirte en $gun:una; soldado Lobo Gélido, hay que ponerte a prueba...' WHERE `ID`=7241 AND `locale`='esES' AND MD5(`RewardText`)='3e306ae444a962e938f48b9aa1c2f567';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Gracias por liberarme! Tú... eres $gel:la; mejor. Todos los demás no te llegan ni a la rodilla.$B$B¡Sabía que mi destino no era acabar siendo el aperitivo de algún ogro!' WHERE `ID`=7429 AND `locale`='esES' AND MD5(`RewardText`)='747844c73f40803b6bb5f26f5a5667e7';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Te damos las gracias, $ghéroe:heroína;.' WHERE `ID`=7461 AND `locale`='esES' AND MD5(`RewardText`)='3c0beab0c7032bc7af9668c6e4b0b768';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Estupendo! ¿Quién decías que eras? Bah, no importa. ¿Qué era lo que te tenía que dar? Mm... bueno, como eres $c, puede que esto te resulte útil.' WHERE `ID`=7463 AND `locale`='esES' AND MD5(`RewardText`)='474f23913715051b95aa44265554660f';
UPDATE `quest_offer_reward_locale` SET `RewardText`='No te hagas daño cuando apliques el encantamiento, $r.' WHERE `ID`=7484 AND `locale`='esES' AND MD5(`RewardText`)='05d0609037b75045d454f11b9ae8daf9';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ah, me alegra ver que $gun:una; $C acude a mi llamada. Necesito tus servicios, $N. Y temo que lo que te pida te guiará por un camino peligroso...$B$BEl camino a La Masacre.' WHERE `ID`=7492 AND `locale`='esES' AND MD5(`RewardText`)='6811dcedef8be1365c9d8c8c0ef04584';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Un trabajo excelente, $r. Si encuentras más libros, no dudes en traérnoslos.$B$BCon el transcurso del tiempo, tendemos a cambiar e incluso añadir nuevas recompensas por los libros.' WHERE `ID`=7498 AND `locale`='esES' AND MD5(`RewardText`)='b9ce21b7f279948fc5e1b062830db205';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Oh $gchico:chica;, vaya, ya estamos otra vez.' WHERE `ID`=7601 AND `locale`='esES' AND MD5(`RewardText`)='1341483a61c957874a8ba0ba6a76a842';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Estupendo! Espero que no te costara demasiado conseguir esos elixires. A veces los alquimistas son tan mezquinos con sus creaciones...$B$BCrearé la campana y la guardaré hasta que estés $gpreparado:preparada; para el ritual.' WHERE `ID`=7626 AND `locale`='esES' AND MD5(`RewardText`)='88458b80384b5e629f581817053b1944';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Ahí están! He oído que el mineral de hierro negro solo se encuentra en las profundidades de Roca Negra y estoy seguro de que tampoco ha sido fácil encontrar estos fragmentos. Nunca deja de asombrarme la entrega de los brujos. Si decidieras concentrar toda esa energía en la captura de bichos, ¡nadarías en la abundancia!$B$BDisculpa, una pequeña digresión. Crearé la rueda y la guardaré hasta que estés $gpreparado:preparada; para el ritual.' WHERE `ID`=7627 AND `locale`='esES' AND MD5(`RewardText`)='efaf483bbf1039c16dd080d0af043d01';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Vaya... ¡tú ERES el rey $grey:reina;! ¡No creo que haya visto ese guantelete en mi vida! Parece que no hay más mojo... igual ese maldito elfo intentó estropear el guantelete. ¡Pues HAR HAR para él!$B$BMira, esta marca en el guantelete es marca mágica vieja vieja, de tiempos antes de Gordok. Como capitán de Gordok, aprendo una cosa una y otra vez: ¡cómo dar vida a una marca y dar poder otra vez al guantelete!$B$B¡Yo lo hago por ti, $grey:reina;! Ten, coge el guantelete ¡y reina PARA SIEMPRE!' WHERE `ID`=7703 AND `locale`='esES' AND MD5(`RewardText`)='f7f70a179acef1cddc54a54ef2e883ba';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Increíble! ¡Creo que has encontrado el rey de todos los pellejos de yeti!$B$BEstate $gseguro:segura; de que te pagaré bien por él. No suelo pagar mucho por un solo pellejo, pero sé que con este podré hacer algo muy especial. ¡Gracias por haber pensado en mí, $N!' WHERE `ID`=7735 AND `locale`='esES' AND MD5(`RewardText`)='a14ac7013bdde447fad902ff0226c1f1';
UPDATE `quest_offer_reward_locale` SET `RewardText`='$N, sin $ghéroes:heroínas; como tú trabajando para Ventormenta, sufriríamos mucho. ¡Gracias por tus continuos esfuerzos!' WHERE `ID`=7796 AND `locale`='esES' AND MD5(`RewardText`)='4a09f20a90bc6c5b1a512e8411cfee28';
UPDATE `quest_offer_reward_locale` SET `RewardText`='$N, sin $ghéroes:heroínas; como tú trabajando para Darnassus, sufriríamos mucho. ¡Gracias por tus continuos esfuerzos!' WHERE `ID`=7801 AND `locale`='esES' AND MD5(`RewardText`)='cfcf4ea8944a4dc3f4d661f67fe8cb94';
UPDATE `quest_offer_reward_locale` SET `RewardText`='$N, Forjaz estaría perdida sin $ghéroes:heroínas; como tú. ¡Gracias!' WHERE `ID`=7806 AND `locale`='esES' AND MD5(`RewardText`)='7379d67d3f35f3180eb061bd658d10ef';
UPDATE `quest_offer_reward_locale` SET `RewardText`='$N, los gnomos estaríamos perdidos sin $ghéroes:heroínas; como tú. ¡Gracias!' WHERE `ID`=7812 AND `locale`='esES' AND MD5(`RewardText`)='150729e86622ded11176ae0253e858af';
UPDATE `quest_offer_reward_locale` SET `RewardText`='$N, sin $ghéroes:heroínas; como tú trabajando para los Renegados, sufriríamos mucho. ¡Gracias por tus continuos esfuerzos!' WHERE `ID`=7819 AND `locale`='esES' AND MD5(`RewardText`)='dddc741820b4f9699304d6900cd75f29';
UPDATE `quest_offer_reward_locale` SET `RewardText`='$N, los trols Lanza Negra estarían perdidos sin $ghéroes:heroínas; como tú. ¡Gracias!' WHERE `ID`=7837 AND `locale`='esES' AND MD5(`RewardText`)='5056d498d79920b468c82590e1ba26bf';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Aquí tienes, aquí tienes! ¡Un premio digno de $gun rey:una reina;! ¡Enhorabuena, amigo!$B$BSi tienes más vales que quieras canjear, ¡házmelo saber! Mientras la Feria de la Luna Negra esté aquí, canjearé todos tus vales.' WHERE `ID`=7931 AND `locale`='esES' AND MD5(`RewardText`)='d4cefd8b9cc96d0481b649fce577660f';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Aquí tienes, aquí tienes! ¡Un premio digno de $gun rey:una reina;! ¡Enhorabuena, amiga!$B$BSi tienes más vales que quieras canjear, ¡házmelo saber! Mientras la Feria de la Luna Negra esté aquí, canjearé todos tus vales.' WHERE `ID`=7934 AND `locale`='esES' AND MD5(`RewardText`)='9291d90e0c8552878b1e21afeb6be49f';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Has sembrado mucha venganza en este día. Has tomado el rostro del vindicador. Has doblegado a los esbirros del Dios de la Sangre.$B$BToma esto. Alimentará tu venganza en el futuro. Ahora eres $gamigo:amiga; de los Zandalar.' WHERE `ID`=8058 AND `locale`='esES' AND MD5(`RewardText`)='990251fc6168272b549e843df94b206d';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Excepcional, $N! Es una gran hazaña haberme traído los Dechados. Has actuado sin duda alguna como nuestro confesor, defendiéndonos de la amenaza de Hakkar. Estos brazaletes son adecuados para $gun amigo:una amiga; de la tribu como tú!' WHERE `ID`=8061 AND `locale`='esES' AND MD5(`RewardText`)='268a4672b68425a152ae665485b78b19';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Impresionante... has conseguido reunir los Dechados de Poder que necesitábamos, $N. Las hazañas que has hecho por los Zandalar en Zul''Gurub son legendarias y por eso serás $gvenerado:venerada; por la tribu. ¡Aquí tienes tu túnica poderosa $C!' WHERE `ID`=8065 AND `locale`='esES' AND MD5(`RewardText`)='de8a1bea0e2805ca2c2e01cfd6fd0bc2';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Bien hecho, $N... Hoy seguramente los esbirros de los Hakkar han sentido la retribución de los Zandalar, y todo gracias a ti. Tus actos te han hecho $gmeritorio:meritoria; de nuestra veneración. Con tu bendición, acepta el manto de confesor como ofrenda.' WHERE `ID`=8071 AND `locale`='esES' AND MD5(`RewardText`)='829241957f37ff88a2749ffe816280a7';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ya conoces las artes del vindicador. Has honrado a la tribu. Te has honrado a ti $gmismo:misma;. Has sembrado el horror entre tus enemigos.$B$BEl Cinturón de vindicador es tuyo. Algún día te $guno:una; con las artes del vindicador.' WHERE `ID`=8078 AND `locale`='esES' AND MD5(`RewardText`)='ea72b8f015219539117d6e6e080031d8';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ah, el Corazón de Hakkar. ¡Así que el Cazador de Almas ha sido derrotado! ¡Nuestro mundo está a salvo!$B$B$N, tu ayuda es inestimable. ¡Eres un $gun héroe:una heroína; de este reino!' WHERE `ID`=8183 AND `locale`='esES' AND MD5(`RewardText`)='d62582ecfe93d49e3711819ba42b3b2c';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Un buen trato, $gamigo mío:amiga mía;, por favor, ¡disfruta de la bendición de Zanza y de un cordial saludo!' WHERE `ID`=8243 AND `locale`='esES' AND MD5(`RewardText`)='8e74e6cd69517dd3fa3bd97ed129aa16';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Un buen trato, $gamigo mío:amiga mía;, por favor, acepta sortija y la bendición de la tribu.' WHERE `ID`=8246 AND `locale`='esES' AND MD5(`RewardText`)='514e2950d26b215c373fa8d84d02c9fc';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Este ejemplar de coral es espléndido, $N. Tus habilidades son sin duda precisas y letales.$B$BNo creas que esto ha pasado desapercibido. Quizás seas $gdigno:digna; de una verdadera prueba para tu habilidad...' WHERE `ID`=8252 AND `locale`='esES' AND MD5(`RewardText`)='c60f1663b88bc1db235079231bd54450';
