UPDATE `quest_offer_reward_locale` SET `RewardText`='Esto... tiene la forma de un tótem ritual Nevada, pero está deformado por fuerzas que no puedo ni empezar a comprender. Sea cual sea el mal y la corrupción que ha puesto a los Nevada contra nosotros, está presente en este objeto, no hay duda.$B$BEl saber divino es el que os ha traído a ti y a este objeto a nosotros, $N. Lo estudiaremos detenidamente, quizás un día los Nevada dejen de dirigir su ira contra nosotros.$B$BGracias, $gamigo:amiga;, por favor, acepta estos regalos a cambio de toda tu bondad.' WHERE `ID`=8471 AND `locale`='esES' AND MD5(`RewardText`)='a0846f92bebd10d500acfa6cd37d6fbb';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Lo lograste, $gchico:chica;! Pondremos esos lingotes de cobre en la pila y le sacaremos provecho para el material de guerra ahora mismo. Es la entrega de gente como tú lo que me hace sentirme orgulloso de servir a la Alianza. ¡Buen trabajo, soldado!$B$BY si por casualidad te encontraras con más lingotes de cobre, asegúrate de que llegan hasta mí.' WHERE `ID`=8492 AND `locale`='esES' AND MD5(`RewardText`)='5f1b1f9872ab26e70913a4355b3245aa';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Has vuelto a demostrar lo que vales, $C. Me encargaré de que este cobre se use a su tiempo debido. Aunque por ahora, necesito que esos lingotes se coloquen en el palé y se actualice el recuento. Si deseas seguir sientes $ganimado:animada;, no nos vendría mal que consiguieras aún más lingotes de cobre.' WHERE `ID`=8533 AND `locale`='esES' AND MD5(`RewardText`)='fd46271eca4b418ea9b4d82785c4fbda';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¿Has recuperado mi banda? Entonces... tienes que haber matado a ese gigante marino Mok''rash. ¡Hurra!$B$BMe alegro de que ese villano asqueroso esté muerto. Mok''rash fue uno de los tres gigantes marinos que destrozó mis barcos y mató a mi tripulación.$B$BTres veces.$B$BEres $gun:una; $C de gran valía, $N.' WHERE `ID`=8552 AND `locale`='esES' AND MD5(`RewardText`)='85fae09fe22580b90050ca4f81109b83';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Has conseguido quitarle mi alfanje a Negolash! ¡No puedo creer que tenga tanta suerte, $N! Conocerte ha hecho que mi suerte cambiase, ¡para mejor, eso sin duda!$B$B¡Gracias! Y si alguna vez consigo un barco y quieres navegar los mares, ¡serás mi $ginvitado:invitada; de honor!' WHERE `ID`=8554 AND `locale`='esES' AND MD5(`RewardText`)='1d9cd6dc822908056d4240a3f9e9c020';
