UPDATE `quest_request_items_locale` SET `CompletionText`='La imagen de Talvash se dibuja en las aguas del cuenco de visión.$B$B"¡Vaya, todavía sigues con vida! ¿Encontraste mis gemas? ¿Eres quien va a salvar mi reputación, $gese:esa; a quien he estado esperando? Por favor, dime que no has desperdiciado una recarga de la ampolla solo para hablar de tonterías... Son muy caras y lo cierto es que no gozo precisamente de una buena situación económica."' WHERE `ID`=2201 AND `locale`='esES' AND MD5(`CompletionText`)='be4834e95b043db2a30340e503ee7266';
