UPDATE `quest_request_items_locale` SET `CompletionText`='¿Sí? ¿Puedo ayudarte?$B$BEspera, tú eres $gel:la; $C que ha estado ayudando a la general Plumaluna y a Latro con la amenaza naga, ¿no es así? Yo soy Vestia, la mujer de Latro... bueno, de Latronicus. ¡Es un placer conocerte!$B$BPerdona que hable tanto. Tú estás aquí por negocios, supongo. ¿Traes algo para mí... de él?' WHERE `ID`=2871 AND `locale`='esES' AND MD5(`CompletionText`)='1cfd0012f718c00ff3de5792ebc7c15a';
