UPDATE `quest_request_items_locale` SET `CompletionText`='$gOtro:Otra; $R para engrosar las filas. Parece lo bastante $gbueno:buena;.$B$BSeguramente no te será fácil blandir un buen arma como un hacha, pero una lanza es tan buena como cualquier otra cosa.$B$B$gBienvenido:Bienvenida; al Valle de los Retos.' WHERE `ID`=3065 AND `locale`='esES' AND MD5(`CompletionText`)='dd1606b53f181d69c5711a5aba8316f2';
UPDATE `quest_request_items_locale` SET `CompletionText`='Jen''shan ve ante ella $gun poderoso:una poderosa; poderoso $C y los espíritus dan su aprobación.$B$BLa senda $gdel:de la; $C es uno de los caminos más antiguos. La Horda se dirigió a nosotros cuando su lucha era solo por la supervivencia en Azeroth y nos pidieron que les enseñáramos y que les mostráramos muchos secretos. Ya eran fuertes: fuertes en las artes chamánicas y fuertes en las artes del guerrero. Pero la senda $gdel:de la; $C no era su senda... entonces.' WHERE `ID`=3082 AND `locale`='esES' AND MD5(`CompletionText`)='74cddfe0f3c0428ebacff83561343e6b';
UPDATE `quest_request_items_locale` SET `CompletionText`='Ah, $gbienvenido:bienvenida;, $N. Me alegra que hayas venido. Con tantos alumnos a los que instruir mis días son largos y ajetreados, pero la llegada de alguien como tú me hace sentir realizada... Todavía recuerdo los días en los que me instruía uno de sus chamanes.' WHERE `ID`=3084 AND `locale`='esES' AND MD5(`CompletionText`)='0dc27e4329bc9973059358a2846a6430';
UPDATE `quest_request_items_locale` SET `CompletionText`='Sé bienvenido, $ghermano:hermana;. Sabía que vendrías. Era solo cuestión de tiempo.$B$BLo que dije despertó tu interés, ¿cierto? Algo dentro de ti te dijo que lo que yo declaraba era verdad. Bien.$B$BPero debes saber una cosa: No estoy traicionando a Sylvanas. Es más bien ella quien debería darme la razón, si tenemos en cuenta que fueron sus propias creencias las que pusieron a los Renegados en la posición en la que están ahora.' WHERE `ID`=3099 AND `locale`='esES' AND MD5(`CompletionText`)='6e0adb4ba7ca398462c6b43a3bdd1fdd';
UPDATE `quest_request_items_locale` SET `CompletionText`='¡Así que lo has conseguido! Y justo a tiempo. Hay mucho que hacer en el Valle de Crestanevada y más allá. Voy a necesitar tu ayuda tanto como tú vas a necesitar la mía.$B$BAhora eres $gun:una; caballero de la Mano de Plata, debes hacer honor a tu título.' WHERE `ID`=3107 AND `locale`='esES' AND MD5(`CompletionText`)='1836d17b15d869d17c93da2e7b4e183d';
UPDATE `quest_request_items_locale` SET `CompletionText`='¡Eh! ¡Lo has conseguido, $N! ¡Estupendo!$B$BEmpezaba a creer que no llegarías y estaba a punto de perder la fe... ¿Lo pillas? ¿Lo de perder la fe? Era un chiste, $gmuchacho:muchacha;... déjalo, no importa. Además, no has venido aquí por mis pésimos chistes.' WHERE `ID`=3110 AND `locale`='esES' AND MD5(`CompletionText`)='b62ad28ba8aa0fb842ac0fdd267d4f4e';
UPDATE `quest_request_items_locale` SET `CompletionText`='Por favor, reúne los ingredientes, $n. Iverron necesita nuestra ayuda.' WHERE `ID`=3521 AND `locale`='esES' AND MD5(`CompletionText`)='943478f81ce3a55306398d0b355a6b98';
