UPDATE `quest_request_items_locale` SET `CompletionText`='La paz sea contigo, $gamigo:amiga;. Vienes aquí por comisión del archidruida en persona, ¿verdad?' WHERE `ID`=3782 AND `locale`='esES' AND MD5(`CompletionText`)='cef9a69915d8eb82185d4111a0c2266f';
