UPDATE `quest_request_items_locale` SET `CompletionText`='¿Te has dejado vencer por las criaturas, $N?$B$BNo te rindas tan fácilmente. Perseguir y derrotar a los simios de Un''Goro no es tarea fácil, ni siquiera para $gun:una; gran $c.' WHERE `ID`=4289 AND `locale`='esES' AND MD5(`CompletionText`)='3318ef73b83128afcb01724a831abbb1';
