UPDATE `quest_request_items_locale` SET `CompletionText`='Lingotes de oro, sí... sí. Tráeme uno y veremos qué puedo hacer para hilarte una bobina. Hasta entonces, te sugeriría que centraras tus esfuerzos en conseguir más poder. Las pruebas más duras están por venir. Y créeme... desearás estar más $gpreparado:preparada;, por muy $gpoderoso:poderosa; que llegues a ser.' WHERE `ID`=4781 AND `locale`='esES' AND MD5(`CompletionText`)='a18c1aaeaf5dc0584582d112add0732f';
