UPDATE `quest_request_items_locale` SET `CompletionText`='¿Y bien, $N? ¿Dónde está la runa? Eres $gun buen empleado:una buena empleada;, ¿verdad? ¿Estás aquí para ayudar?$B$BNo me hagas pensarme dos veces lo que acordamos que te pagaría. ¡¿Qué?! Ah, ¿no habíamos quedado en nada? Oh, bueno... entonces tómate tu tiempo, pero conste que la cantidad será mucho menor si te lleva mucho tiempo.' WHERE `ID`=5534 AND `locale`='esES' AND MD5(`CompletionText`)='5e590e3346ed32a4dc48dfedba225bfd';
