UPDATE `quest_request_items_locale` SET `CompletionText`='¡Eh, hola! Mmm...$B$BVoy a hablarte con sinceridad, $gamigo:amiga;... apestas un poco. Tienes olor a pies, o algo así. No es que te esté atacando ni nada de eso. Solo digo que... en el futuro, quizás quieras refrescarte un poco después de salir del campo de batalla. De esa forma, las primeras impresiones que causes no serán tan impresionantes.$B$BEn fin... ¿Qué puedo hacer por ti?' WHERE `ID`=6844 AND `locale`='esES' AND MD5(`CompletionText`)='6ca4252c5e9711300740805a897b8847';
