UPDATE `quest_offer_reward_locale` SET `RewardText`='¡$gOtro:Otra; $C que completa la Prueba del Lago! Buen trabajo. $B$BMe llamo Tajarri y tengo el honor y el deber de ser una celadora de Claro de la Luna y, en concreto, de este santuario. El guardián Remulos guía al Circulo Cenarion en la preservación y el balance de la naturaleza y este santuario sirve como tributo. Usar el adorno aquí es un guiño a la importancia de este lugar dentro del Círculo.' WHERE `ID`=28 AND `locale`='esMX' AND MD5(`RewardText`)='a2129c820ca94b697c080ca056051bde';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Impresionante. Creo que ya estás $gpreparado:preparada;.' WHERE `ID`=187 AND `locale`='esMX' AND MD5(`RewardText`)='76adeb08a70dd41068c4c3d4bbeda010';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Muy impresionante, sí! ¡Eres $gun:una; $gauténtico:auténtica; $gmaestro:maestras; $gcazador:cazadora; de tigres experto $N!' WHERE `ID`=188 AND `locale`='esMX' AND MD5(`RewardText`)='83b9132a76bc9eb6be24d1a2cdd8d727';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Así que la gran Bhag''thera está muerta! Enhorabuena, $N. ¡Eres $gun:una; $gpoderoso:poderosa; $C!' WHERE `ID`=193 AND `locale`='esMX' AND MD5(`RewardText`)='5e71b6e3cf35e4b8a11cb1bbeac99160';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Bien hecho, $gamigo:amiga;.' WHERE `ID`=194 AND `locale`='esMX' AND MD5(`RewardText`)='eedc11e5c2588afa7e2da343d473930a';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡¡Jo, jo!! ¡Estamos $gun:una; $gauténtico:auténtica; un auténtico asesino de raptores! Bien hecho, $gamigo:amiga;.' WHERE `ID`=196 AND `locale`='esMX' AND MD5(`RewardText`)='c27f8d322b4cb61886b7ab535d4dbfa4';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Pero qué maravilla! ¡Eso es! Enhorabuena, $N, por salir $gvictorioso:victoriosa; ahí donde otros fracasaron. $B$BEs un honor para mí contarte entre mis camaradas de caza mayor. ¡Nadie podrá poner en duda tu pericia en la caza y el rastreo! $B$B¡Levanto mi copa por ti, salud! ¡Salud!' WHERE `ID`=208 AND `locale`='esMX' AND MD5(`RewardText`)='6526505aa6b86d12c3d7bac713ff651d';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Muy bien, $C, ¡pero que muy bien! Seguiré mandando tropas para diezmar a los fúrbolgs, pero al menos cuento con una ruta diferente que estará libre de enredos con la Alianza. ¡La conquista de Vallefresno por la Horda está bien encarrilada! $B$BTe has ganado el jornal, $ghéroe:heroína;. ¡Te saludo!' WHERE `ID`=216 AND `locale`='esMX' AND MD5(`RewardText`)='d6b66ea68bc2c5b90cff505c924d9c25';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Perdona mi frío recibimiento, $N, pero ya te habrás dado cuenta de que soy un hombre muy ocupado. Veo que has impresionado a Calor, cosa que no es en absoluto fácil de conseguir, y veo que te ha dado una recomendación. $B$BHemos de afrontar seres de lo más desagradable, $N, y necesitamos la ayuda de cualquiera que haya demostrado su valía. Combatimos contra demonios, no-muertos y contra aquellos que les proporcionan ayuda. Mantente alerta, sé $gprecavido:precavida; y no confíes en nadie que no colabore con nuestra causa. $B$BGloria bajo la Luz.' WHERE `ID`=223 AND `locale`='esMX' AND MD5(`RewardText`)='0effcc141d6c5572a96b0983a9d979c1';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Lo supe en cuanto te vi, $N. Sabía que Forjaz se enorgullecería de ti. Has servido bien al rey Magni. Ahora que has demostrado ser $gun:una; ayudante leal del reino, quizás deberías hablar con el capitán para que te confíe más detalles.$B$BTe saludo, $N.' WHERE `ID`=263 AND `locale`='esMX' AND MD5(`RewardText`)='2ae60f7c31df64aa8f49e0ca5d98fd59';
UPDATE `quest_offer_reward_locale` SET `RewardText`='El hierro Forjaluz es un metal precioso, pero parece que tu misión es muy peligrosa. Has hecho un largo camino, $ghermano:hermana;. Con suerte, encontrarás lo que buscas. $B$BY, si consigues el hierro, sé quién puede forjar un arma para luchar contra ese nigromántico del que hablas del Bosque del Ocaso.' WHERE `ID`=270 AND `locale`='esMX' AND MD5(`RewardText`)='73ab66d1860ba57db9bd3f6a3019f592';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Cumples bien tus órdenes, $C. Has demostrado ser $gun:una; valiente soldado y $gun:una; leal $gservidor:servidora; del rey Magni, ¡te rindo homenaje! Gracias a la presión que ejerciste sobre el campamento Hierro Negro tenemos ahora una oportunidad para expulsarlos definitivamente de nuestras tierras... si tan solo aparecieran las condenadas fuerzas de reserva...' WHERE `ID`=303 AND `locale`='esMX' AND MD5(`RewardText`)='4a2ec287d32ce1e53d810593bd78335c';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¿Es para mí? ¡Eres $gun héroe:una heroína;, $N!' WHERE `ID`=308 AND `locale`='esMX' AND MD5(`RewardText`)='0fad45cb6cefaea86332167b98bf6118';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¿Entonces has visto a Renato? Aquí estamos, $gcaballero:dama;. Una botella de nuestro pinot noir especial. ¡No encontrarás nada mejor en todo Azeroth!' WHERE `ID`=332 AND `locale`='esMX' AND MD5(`RewardText`)='5585bdcd1d2bb62595e70f47747e58a2';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Ay, ay! Este libro no descansa en estos estantes desde antes de la reconstrucción de Ventormenta. Habrá que restaurarlo, claro, está en un estado lamentable, pero me honraría colocarlo entre los otros libros raros de nuestra colección. $B$BGracias, $gseñor:señora;. ¡Acepta esto como pago por la devolución del libro!' WHERE `ID`=337 AND `locale`='esMX' AND MD5(`RewardText`)='228e617920710fe113ace75bc02d64bf';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Lo has hecho muy, muy bien, $C. Con $gluchadores despiadados:luchadoras despiadadas; como tú actuando en nombre de los Renegados, nuestra raza está cada vez más cerca de derrotar a Arthas de una vez por todas. Tengo un buen presentimiento respecto a ti, camarada.' WHERE `ID`=372 AND `locale`='esMX' AND MD5(`RewardText`)='1974bb4e0f4ef0d0f19a742b4396399b';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¿Tienes mis herramientas? ¡Bien hecho, $gmuchacho:muchacha;! Acabo de romper mi último destornillador hace una hora y necesitaba otro para acabar de reparar la máquina de asedio del piloto Roscapiedra. Desde luego, me has hecho un favor enorme trayendo estas herramientas hasta aquí, $N. $B$BTen unas monedas.' WHERE `ID`=400 AND `locale`='esMX' AND MD5(`RewardText`)='936b3bdc7d5528b84e3de17cf1a7b1f6';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Has derrotado a Lillith Nefara, lo que demuestra que eres $genemigo:enemiga; de la Plaga. Es increíble. $B$BHubiera jurado que era el único no-muerto con voluntad propia pero me has demostrado que también hay otros libres de la dominación del Rey Exánime.' WHERE `ID`=409 AND `locale`='esMX' AND MD5(`RewardText`)='8b0b2a3bd9460d631d188d0a35ca6d13';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Las hiedras y helechos hablan muy bien de ti, $gpequeño:pequeña;. Aunque tengo muchos nombres, solo respondo a unos pocos. Tú puedes llamarme Rethiel. $B$BDebes aguzar el oído... lamentar el destino de estas tierras heridas y te encargaré la misión de sanarlas.' WHERE `ID`=463 AND `locale`='esMX' AND MD5(`RewardText`)='d94332f72fd1a00f7bf7f60976d486df';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Umm... No creo que estés $ginteresado:interesada; en convertirte en mi aprendiz, ¿verdad? $B$B¡Ja! No, estoy bromeando. Eres demasiado mayor. Además por tu aspecto se diría que tienes otras ambiciones. Bueno, en cualquier caso, me has traído buenas pieles y me serán muy útiles.' WHERE `ID`=471 AND `locale`='esMX' AND MD5(`RewardText`)='265953a8894d9215e1fb8d73641e8b8a';
UPDATE `quest_offer_reward_locale` SET `RewardText`='$N. Valstag me ha informado de tus éxitos sobre los orcos Faucedraco en Dun Algaz. Eres $gun:una; $R de gran valor. $B$BY tengo una tarea para ti.' WHERE `ID`=473 AND `locale`='esMX' AND MD5(`RewardText`)='276f6f2297dad98246b37dfb8b14e991';
UPDATE `quest_offer_reward_locale` SET `RewardText`='$N, has demostrado ser $gun:una; $C digno y capaz. $gUn:Una; $R que recorre el camino del honor con tanta seguridad, sin dudas encontrará la gloria en este mundo.$B$BQue los espíritus del bosque te protejan en todos tus viajes.' WHERE `ID`=486 AND `locale`='esMX' AND MD5(`RewardText`)='acfeaaaf39390ef7f9a202760cbf4e45';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Ja, ja, ja! ¡Lo has hecho! $B$B¿Quién habría imaginado que yo, Zenn Nauseapezuña, conseguiría que $gun:una; $R hiciera lo que se me antojara? ¡Yo no, la verdad! Pero así es... este maravilloso mundo está lleno de sorpresas. $B$B¡Tres hurras por $gnuestro:nuestra; inocente de hoy!' WHERE `ID`=488 AND `locale`='esMX' AND MD5(`RewardText`)='de6c9d3d9fb0129582c13fdd94a1cfb2';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Encantado de conocerte, $N. Llevaba tiempo sin ver a $gun:una; $C por aquí. $B$BMe he ubicado aquí con esta expedición con un propósito: cazar a una bestia enorme y muy escurridiza. Como te veo $gun:una; gran $ghéroe:heroína;, estoy dispuesto a incluirte en la partida de caza, pero antes tienes que probar tu valía. $B$BYo te enseñaré a cazar raptores. Ajeck te enseñará a cazar tigres y Sir Erlgadin es un maestro del rastreo de panteras. $B$BDemuestra tu capacidad y te dejaré participar en la gran caza.' WHERE `ID`=583 AND `locale`='esMX' AND MD5(`RewardText`)='ff8e4d3f205fafecf142027ee94221d1';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Muy bien hecho, $N! ¡Y jut-to cuando yo también tengo que embarcal! No te lo puedo agradecel bah''tante, $gviejo:vieja; $gamigo:amiga;.' WHERE `ID`=587 AND `locale`='esMX' AND MD5(`RewardText`)='40626b83a42442abb2fcc7dfe2df8941';
UPDATE `quest_offer_reward_locale` SET `RewardText`='<Myzrael habla a través de la piedra.> $B$B¡Lo has logrado! ¡Has abierto las Piedras de Vínculo! Siento cómo los grilletes se sueltan y la libertad se acerca. $B$BComo $C, eres muy noble, $N. ¡Mi $gsalvador:salvadora;!' WHERE `ID`=651 AND `locale`='esMX' AND MD5(`RewardText`)='003463c73b45a8b51b1b51bfbc238d7e';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Si le trae a Phin el descanso, acabaré personalmente con esos renegados uno a uno. Ha hecho tanto por nosotros desde la peste. Nunca pensé que volvería a ver a mis amigos o a la familia. $B$BDame un toque cuando estés $gpreparado:preparada;. Empezaremos enseguida.' WHERE `ID`=657 AND `locale`='esMX' AND MD5(`RewardText`)='8ad71b0e5b6dd5430556ed5f9d7a563a';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Buen trabajo, sí $gseñor:señora;, $N. $B$BEsa escoria se ha llevado su merecido. Aunque nada me devolverá mi barco o mi tripulación, la muerte de esos nagas me brinda algo de consuelo.' WHERE `ID`=664 AND `locale`='esMX' AND MD5(`RewardText`)='1a77aec429e97b7b993910c8674ab15b';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ah, empezaré con esas alas enseguida. ¡Ya casi puedo saborearlas! $B$B¡Aquí tienes la receta en caso de que las quieras preparar tú $gmismo:misma;!' WHERE `ID`=703 AND `locale`='esMX' AND MD5(`RewardText`)='47c03cb5ec03ff26ef31f843d6b8585f';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Gracias, $N. Ha sido un suplicio, ¿verdad? $B$BNo estoy seguro de qué puede haber fallado. Menos mal que hemos contado con mi magia para enviar a la criatura de vuelta a su hogar. $B$B¿Quizás una muestra de aprecio por ser tan $gdenodado:denodada;...?' WHERE `ID`=778 AND `locale`='esMX' AND MD5(`RewardText`)='a4652e28a6a66d7c75c17d9803a130c5';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Según tu descripción de la bestia creo que estás hablando de Sarkoth. No me extraña que pudiera con Hana''zua. Le prestaremos ayuda inmediatamente, ya no necesitas seguir preocupándote por su situación. $B$BPero hay una cosa que debo decir, me ha impresionado saber que acabaste con la vida de Sarkoth. Es una hazaña de la que estar $gorgulloso:orgullosa;, $N. Además, el haber luchado por el honor de un desconocido, dejando a un lado tus propias tareas, es, sin duda alguna, todo un signo de honor por tu parte.' WHERE `ID`=804 AND `locale`='esMX' AND MD5(`RewardText`)='74716f2089cbd86b1282856ad3b8918e';
UPDATE `quest_offer_reward_locale` SET `RewardText`='$gBienvenido:Bienvenida;, $N. Fui informado de tu llegada y de tus hazañas en Durotar. $B$BEstás desarrollando tus habilidades... Te estás haciendo un nombre en este mundo, $C. $B$BMantente en el camino de la pureza y tendrás un gran futuro.' WHERE `ID`=828 AND `locale`='esMX' AND MD5(`RewardText`)='2367f01ed3cfc08b12dcbbf036adb289';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Veo que eres muy $gtrabajador:trabajadora;, $C. $B$BSin duda tendremos pronto una sorpresa apropiada para esos enanos.' WHERE `ID`=846 AND `locale`='esMX' AND MD5(`RewardText`)='9d50b5e55e9433373b9ddfc2cbce437e';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Lo has hecho muy bien, $N! Que en todo Cima del Trueno te veneren como un defensor de las sagradas tierras tauren y como $gcampeón:campeona; de la tribu perdida.' WHERE `ID`=849 AND `locale`='esMX' AND MD5(`RewardText`)='1334ab6a31fdcebed4e31cd4c71ff831';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Muy bien. Debes haber alborotado mucho a esos centauros... Nuestros guardias avistaron actividad cerca del Oasis Estancado, seguro que fuiste tú.$B$BDeberías sentirte $gorgulloso:orgullosa; por tus actos, $N. Siento una gran valentía en ti.' WHERE `ID`=851 AND `locale`='esMX' AND MD5(`RewardText`)='f8ecf83cb57d26806dae11bae281580a';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Eres $gdigno:digna; de elogio, $N. Estos centauros son indisciplinados y no pueden concentrar su furia como los orcos, pero no son menos feroces. Al derrotarlos, has demostrado tu valentía.' WHERE `ID`=852 AND `locale`='esMX' AND MD5(`RewardText`)='ddc835cb8dc4671fdae8cdf6e826f484';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¿Deseas cazar en Los Baldíos? $B$BEres joven e irradias entusiasmo, pero todavía no estás $gpreparado:preparada; para perseguir a una presa por las llanuras de este lugar. $B$BDe todos modos, no te preocupes. Trabajaremos para fortalecer tu cuerpo y tu mente y aprenderás que cazar no solo consiste en encontrar y matar a tu presa. $B$BPrepárate pues tu viaje comienza aquí y ahora.' WHERE `ID`=860 AND `locale`='esMX' AND MD5(`RewardText`)='d6f405ec661eecdf2cf74c88e390e8bb';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Sí, sí, ¡hermosos ejemplares! Cultivaré estas raíces y las estudiaré. Espero descubrir nuevas propiedades. ¡Ocultas y valiosas propiedades...! $B$BY no te preocupes, si lo consigo, serás $gel primero:la primera; en saberlo. ¡Porque necesitaré más!' WHERE `ID`=866 AND `locale`='esMX' AND MD5(`RewardText`)='be2d59147d2a6d454b0e0772a5aeb90f';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Te deshiciste de los raptores!$B$BGracias, $N. Eres $gun:una; $C digno.' WHERE `ID`=869 AND `locale`='esMX' AND MD5(`RewardText`)='bd5b2ba034d25128c79fceb5d9eea935';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Excelente trabajo, $gamigo:amiga;. Creo que llegarás muy lejos en la Horda.' WHERE `ID`=875 AND `locale`='esMX' AND MD5(`RewardText`)='28727242fcc10ab6ec95d01013730a69';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Hiciste un buen trabajo, $gchaval:chavala;. Si sigues así un poco más, tendré un problema menos del que preocuparme. Espero que esto los convenza de reubicar su operación.$B$BMientras tanto, ¡está el pequeño problema de recuperar los bienes que me robaron!' WHERE `ID`=887 AND `locale`='esMX' AND MD5(`RewardText`)='9aa3f750b3f877e760e9cc2d104f59d5';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Es un alivio recuperar todo esto, gracias por tu ayuda, $N. ¿Sabes?, no me vendría mal $gun:una; $R como tú para ayudarme aquí. Si cualquier día buscas trabajo, ¡recuerda lo bien que paga Gazlowe!' WHERE `ID`=888 AND `locale`='esMX' AND MD5(`RewardText`)='97d5f00436d7fa5898021f3f4c347368';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Tú, al igual que el halcón trueno, deberías sentirte $gorgulloso:orgullosa;. Has derrotado a todos los enemigos que te hemos marcado y lo has hecho con fuerza, valor y honor. $B$BPero ahí no acaba tu camino, $N. De hecho, te darás cuenta de que los verdaderos cazadores siempre van a más, siempre siguen su camino con el mismo orgullo que me has demostrado. $B$BAhora debes seguir adelante.' WHERE `ID`=913 AND `locale`='esMX' AND MD5(`RewardText`)='fa7230f98c394f298f3f4ccc7461defd';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Saludos, $C. Me alegro de ver que estás $ginteresado:interesada; en colaborar en nuestra investigación. Queda mucho trabajo por delante y te mentiría si te dijese que no entraña peligro. Esperemos que esto no te haga desistir... aunque ya se ve que no es la primera vez que le plantas cara al peligro.' WHERE `ID`=936 AND `locale`='esMX' AND MD5(`RewardText`)='a59f1bc1e3af905720678dc2245ad9c6';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Has hecho un gran servicio a Auberdine, $gmuchacho:muchacha;. Cuidaremos bien de sus efectos. $B$BPor favor, acepta esto. Es lo mínimo que puedo hacer por alguien que ha tenido el valor suficiente para enmendar esta situación.' WHERE `ID`=982 AND `locale`='esMX' AND MD5(`RewardText`)='90ba7270fb8cf8de635db0493c4cc9ea';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Ah, aquí está! Llevo tiempo esperando este paquete con tierra rara. Espero que todavía esté en buen estado... $B$BGracias por traérmela, $N. Eres $gun:una; $R $gcomprometido:comprometida; con su tiempo.' WHERE `ID`=997 AND `locale`='esMX' AND MD5(`RewardText`)='8ac8ff044391052f2dd265d75447102a';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Saludos, $C. $B$BMe alegra ver que alguien como tú se preocupa por el bienestar de la naturaleza. He oído hablar de tus hazañas por lo que eres bien $grecibido:recibida; aquí. Al mirarte tengo la certeza de que el Círculo Cenarion recibirá la ayuda que necesita. $B$BNuestra relación con el Círculo Cenarion en el Claro de la Luna trasciende la barrera racial y política; no lo olvides nunca.' WHERE `ID`=1000 AND `locale`='esMX' AND MD5(`RewardText`)='bb8f00b2c03b7deab7bfe4b41aec0375';
UPDATE `quest_offer_reward_locale` SET `RewardText`='La caja mecánica cobra vida en cuanto introduces los ojos de trillador. Después de un lapso de tiempo, oyes una vocecilla familiar... $B$B"El vino de reptador es lo mejor..." *hip* $B$B"¿Eh? Oh, ¿ya la has arreglado? Vaya, sí que eres $grápido:rápida;. Dime, ¿quieres arreglar otra caja?" $B$BOyes lo que parece el sonido de un líquido vertiéndose en una copa y luego ruidos ansiosos de alguien tragando.' WHERE `ID`=1001 AND `locale`='esMX' AND MD5(`RewardText`)='0cd027fa183f02d9f953ab075a10d271';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Hola, $gciudadano:ciudadana;. Este es un lugar peligroso para las visitas. Yo no me quedaría mucho por aquí si valoras tu vida. $B$BSi tus preguntas son cortas, intentaré ayudarte. Mantén los ojos abiertos y ten cuidado con esos sucios ogros. Según los rumores, hay una base de la Horda cerca del pantano. Los infiltrados hacen todo lo que pueden para encontrarla, pero el proceso va lento y no hemos conseguido avanzar mucho.' WHERE `ID`=1266 AND `locale`='esMX' AND MD5(`RewardText`)='4c2a91d2e375baf96ae3d291c334a63e';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Vino Apestoso con las hierbas que le pedí y me dijo que le habías ayudado a salir de un aprieto. ¡Bien hecho! ¡$gUn amigo:Una amiga; de Apestoso es $gamigo mío:amiga mía;! $B$BPoco antes de dirigirse hacia el sur, hacia el pantano, me pidió que te diera esto si te veía.' WHERE `ID`=1270 AND `locale`='esMX' AND MD5(`RewardText`)='6165fbe33cdfe111bebe07367f2534cb';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¿Te envía Regthar? Entonces has venido a cazar centauros. Bien. $B$BEspero que hayas venido $gdescansado:descansada;. No sé cómo acabará nuestra campaña contra los centauros, pero sé que la lucha será larga. $B$BToma asiento y escucha.' WHERE `ID`=1362 AND `locale`='esMX' AND MD5(`RewardText`)='fa4b59ad671cf8b86aeecc729c40c893';
UPDATE `quest_offer_reward_locale` SET `RewardText`='La tierra me habla. Y me dice que has matado muchos Magram. Y eso está bien. $B$BSi eres $gamigo:amiga; de los Gelkis, escucha. Tengo dos misiones más para ti.' WHERE `ID`=1368 AND `locale`='esMX' AND MD5(`RewardText`)='bc12c3cda211e0d817257daad8e3829b';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¿Has conseguido el arma del terrorífico Noboru? ¿Eso quiere decir que está muerto? $B$BEste es un día de júbilo para El Puerto. Noboru y los suyos representaban una seria amenaza para nosotros pues vagaban por los pantanos matando a todos los draenei que se cruzaban en su camino. Sin duda, ponía en peligro nuestra existencia pero nosotros no teníamos la fuerza suficiente para hacerle frente. $B$BSomos afortunados por tenerte como $gamigo:amiga;, $N.' WHERE `ID`=1392 AND `locale`='esMX' AND MD5(`RewardText`)='3797876c43c910ea78dd0b80d3b020f0';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ah, $N. Hacía tiempo que no venías por aquí. Parece que hayan pasado muchas lunas desde que diste el primer salto que te inició en tu camino. $B$BY ahora regresas a mí más fuerte de lo que una vez fuiste... y más $gsabio:sabia;. Eso me complace y creo que deberías recibir una recompensa por haber superado mis pruebas.' WHERE `ID`=1394 AND `locale`='esMX' AND MD5(`RewardText`)='aa1dfbdf37cd669a620902966b03255a';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Esto es terrible! Pero supongo que era necesario. Si no lo hubieras hecho tú, seguramente mi gente habría intervenido. Supongo que debería darte las gracias... perdóname si no parezco muy sincera. No es mi intención ofenderte. $B$BAhora que sé qué suerte corrió mi hermano, parece que ha llegado el momento de que huya. Si aún sigue en pie tu ofrecimiento, aceptaré tu ayuda para escapar de este horrible lugar. $B$BCuando estés $glisto:lista;, podemos emprender nuestro camino hacia la salvación.' WHERE `ID`=1439 AND `locale`='esMX' AND MD5(`RewardText`)='172767786d21f84ec2f2a9be0b64dbe4';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¿Qué quieres, $gmuchacho:muchacha;? ¿No ves que tengo cosas que hacer aquí? ¿A quién le sobra el tiempo para perderlo con $gun:una; $R $gcharlatán:charlatana;? $B$B¡Hay trols saliendo de la carpintería! Habla rápido.' WHERE `ID`=1449 AND `locale`='esMX' AND MD5(`RewardText`)='7682f62d6d3988d7bca7a93a480a6193';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Hip! $B$BTe estoy mirando y no paras de moverte. Tás mareándome. ¡Jo, jo! $B$B¡Hip! $B$B¡Guau! ¿Lo has sentido? La tierra se mueve, $gamigo:amiga;. Necesito una copa. $B$B¡Hip!' WHERE `ID`=1451 AND `locale`='esMX' AND MD5(`RewardText`)='9f78242fb14140c86e4fc3057f253f40';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Aún no has sido $gprobado:probada; y estás al principio de tu aprendizaje, pero has demostrado que posees la habilidad suficiente para invocar y poseer a un diablillo. No te dejes engañar por su tamaño. No posee fuerza física, pero sí poderes y una inteligencia que te vendrán bien. $B$BAtiéndeme bien, $N, porque no repetiré esta lección; dejaré que la domines por tu cuenta.' WHERE `ID`=1470 AND `locale`='esMX' AND MD5(`RewardText`)='fefb1e6413827b3a9e514f24628858dc';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Mis más cordiales saludos, $N. Eres $gbienvenido:bienvenida; entre nosotros. Te convendría hacer un acopio de todas tus fuerzas... la tarea que te espera... es extremadamente ardua.' WHERE `ID`=1489 AND `locale`='esMX' AND MD5(`RewardText`)='31370a3c0ca3aef99b371bb762bb9bbf';
UPDATE `quest_offer_reward_locale` SET `RewardText`='$gOtro:Otra; $r, ¿eh? Espero que no hayas venido a por el orco, porque no sobrevivió; los goblins se encargaron de él. $B$BDijo algo de un jarabe curativo, pero poco más.' WHERE `ID`=1510 AND `locale`='esMX' AND MD5(`RewardText`)='4aaec8073e0389613ed41ed3de822c69';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Conseguido! No esperaba menos de mi $galumno:alumna; alumno. $B$BHas demostrado tu valía y yo te enseñaré a invocar a tu súcubo dominado. Ve y sigue aprendiendo; la próxima vez que nos veamos, habrás dominado a tu súcubo. $B$BDeja la pena de Dogran y Zankaja a los que somos más mayores, pero recuérdala, y que sirva de protección contra el poder oscuro que has aprendido a invocar hoy.' WHERE `ID`=1513 AND `locale`='esMX' AND MD5(`RewardText`)='96972bfbc2599d2cb4a0f5b8fd0b7735';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ah... $N... la tierra se complace de tenerte aquí. $B$B$gComprometido:Comprometida; en cuerpo y espíritu, sabiendo que las montañas son tu fuerza, las llanuras tu paciencia y el mundo tu esencia. $B$BLa humildad ante la tierra es todo lo que necesitas para pasar este rito. Pero los otros no son tan pasivos. Pueden ser caóticos y, en ocasiones, violentos. Pero esa es la naturaleza de los elementos, naturalezas duales en oposición. Debes aprender esto en toda su complejidad.' WHERE `ID`=1517 AND `locale`='esMX' AND MD5(`RewardText`)='39a39455804c6bfba33be4738cd33b28';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Oh, jo! Tómate un trago conmigo, $gmuchacho:muchacha;. A primera vista pareces muy $gduro:dura;, pero veamos si puedes arreglártelas con algunas jarras de las especialidades más potentes de El Cerdo Borracho $B$BO bien... ¿has venido para recibir instrucción?' WHERE `ID`=1638 AND `locale`='esMX' AND MD5(`RewardText`)='7af10321821b8d523ca8498168e93aa3';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Hola $gmuchachito:muchachita;! ¿Qué hace $gun:una; repipi como tú en El Cerdo Borracho? Ten cuidado, se te podría romper una uña...' WHERE `ID`=1639 AND `locale`='esMX' AND MD5(`RewardText`)='da3aa4b155a826a7a50b8897e88a41cf';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Hola de nuevo, $N. ¿Cómo van tus estudios del escrito sobre divinidad? $B$BSi lo has estudiado, deberías estar preparado para pasar una prueba. Siempre hay cosas que hacer en la ciudad y en nuestras tierras. Actos de compasión y comprensión, gente a la que ayudar, criaturas a las que matar... $B$BSi demuestras que tienes la paciencia necesaria para ayudar a otros, especialmente a los menos afortunados, demostrarás que estás en pleno uso de tus facultades y que eres $gun:una; siervo de la Luz.' WHERE `ID`=1642 AND `locale`='esMX' AND MD5(`RewardText`)='9c9a1f2a382736cf07ac856697e0e331';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡La tienes! Seguro que no quería separarse de ella pero has sido muy $gpersuasivo:persuasiva;. Bien hecho. $B$BPasemos ahora a tu lección...' WHERE `ID`=1665 AND `locale`='esMX' AND MD5(`RewardText`)='4c6727db42e07d88564c6c524e5872fd';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Bien hecho, $N. ¡Has superado La Reyerta! $B$BEres $gun digno:una digna; digno $C y es un honor instruirte...' WHERE `ID`=1719 AND `locale`='esMX' AND MD5(`RewardText`)='5a848a588481c819915ef03a7d6f63e8';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Bien hecho, $N. Ulag no era un agente menor de la Plaga. Has mostrado a los Guardias de la Muerte y, por tanto, a la Dama Oscura, que eres $gun:una; $C diestro y firme y que mereces seguir avanzando en tu instrucción.' WHERE `ID`=1819 AND `locale`='esMX' AND MD5(`RewardText`)='929c3862c7d71c95f60ab43a1c367891';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Muy bien hecho, $N! Al superar la prueba en Tierra de Gigantes has dado un gran paso adelante en la senda $gdel:de la; $C.' WHERE `ID`=1824 AND `locale`='esMX' AND MD5(`RewardText`)='a126793e4c826543e078b817fb04310d';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Oh, veo que eres prometedora, ¡sí, lo eres! Pero hace falta algo más que una promesa para ser $gun buen:una buena; $c. Y si no eres $gun buen:una buena; $c, eres $gun:una; $c $gmalo:mala;. Y los malos magos son parte del problema, ¡sí, lo son! $B$BUps, me estoy adelantando... ¡empecemos por el principio!' WHERE `ID`=1879 AND `locale`='esMX' AND MD5(`RewardText`)='b88382fdd7396f2fa38fd70404d4bcf1';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Saludos, $N. Fuiste $gsabio:sabia; al responder a mi llamada, y aún lo serás más si escuchas lo que voy a decirte...' WHERE `ID`=1881 AND `locale`='esMX' AND MD5(`RewardText`)='1668d1d33277ca90771d3add24d6aff8';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ave, $N. Loado seas, has respondido a mi petición de auxilio. Esperemos que estés $gpreparado:preparada; para esta tarea...' WHERE `ID`=1883 AND `locale`='esMX' AND MD5(`RewardText`)='00aa68789b7112c1db21767e27092dd5';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ah sí, el paquete de hierbas de Cañada Umbría. Es una lástima que no lo haya podido traer el propio Porthannius pues él y yo tenemos mucho de qué hablar. No obstante, me alegro de hayas venido a traerme las hierbas. $B$BYa que estás aquí, aprovecha para descansar. $gLos héroes:Las heroínas; han de velar por su fuerza y ánimo, y buscar descanso y solaz cuando sea necesario. Si no se proporciona paz al cuerpo y a la mente, el fracaso es inevitable. $B$BAsí pues... descansa.' WHERE `ID`=2159 AND `locale`='esMX' AND MD5(`RewardText`)='eae2605c9c34cba6e22a24f325cc38d7';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Ah, por fin! ¡Los suministros! Empezaba a preocuparme. Hemos tenido pocas noticias de Yunquemar desde que los troggs se hicieron con el paso. $B$BGracias por traerme esto, $N. Te lo ruego, ponte $gcómodo:cómoda;. Debes de estar $gcansado:cansada; del viaje.' WHERE `ID`=2160 AND `locale`='esMX' AND MD5(`RewardText`)='a1e81017020c581a1fe987179802e998';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¿Qué tienes ahí? ¡Vaya! ¿Dónde encontraste esto? $B$B¿De verdad? $B$B¿Qué hablaste de qué con quién? $B$B¡NO PUEDE SER VERDAD! $B$BMi $gquerido:querida; $C, ¡este puede ser el descubrimiento arqueológico del año! ¿¡Qué digo del año!? ¡Del siglo! Si estos discos son lo que creo que son, ¡tenemos delante la última pieza del rompecabezas! Esto podría demostrar de una vez por todas la legitimidad de la creación encantada de los enanos.' WHERE `ID`=2279 AND `locale`='esMX' AND MD5(`RewardText`)='5f9e1b200d8c46880d0d845fb212c3ae';
UPDATE `quest_offer_reward_locale` SET `RewardText`='$gPoderoso:Poderosa; $C, sé a qué has venido a las Tierras Inhóspitas. Me necesitas por mi vasto conocimiento de otras lenguas y estás buscando las piezas del collar que encontraste en Uldaman. $B$B¿Sorprendido? No lo estés tanto, mi trabajo consiste en averiguar estas cosas. Así pues, centrémonos en el diario y dime qué recibiré a cambio de su traducción. Créeme, no encontrarás a nadie más que pueda hacerlo. $B$BEs más, te haré una oferta mejor que la de Dran Droffers de modo que todavía puedas cumplir su trato. ¿Qué dices?' WHERE `ID`=2318 AND `locale`='esMX' AND MD5(`RewardText`)='ce189b41b187aaa0600a4b28aa38ca9e';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Lo que me trajiste superó todas mis expectativas; tengo un collar para mí, uno para ti y me ha sobrado para hacer 3 más. Voy a hacer un buen negocio, al margen de Rescates Droffers e Hijos. $B$BTen; tienes, $gamigo:amiga;. Te doy las gracias por tu ayuda y algo muy especial como muestra de gratitud.' WHERE `ID`=2341 AND `locale`='esMX' AND MD5(`RewardText`)='72711a6038577cf52a78c261b641342e';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Fantástico, encontraste algunas! Mil gracias, $N. ¡Eres $gel:la; $R más formal que he conocido! $B$BMe muero por probarlas en unos dispositivos que he fabricado. Apuesto que, en las circunstancias apropiadas, los dispositivos impulsados con estas piedras funcionarán, y funcionarán y funcionarán...' WHERE `ID`=2418 AND `locale`='esMX' AND MD5(`RewardText`)='18342bdcb5a537fe8f1165a232d6631e';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡La leyenda de los Omosh perdurará! $B$BHas demostrado tu eres $gherrero:herrera;, $N, y tu premio será ver tus armas y armaduras bañadas con la sangre de tus enemigos. $B$B¡Que tus creaciones protejan a tus aliados y destruyan a tus enemigos!|n' WHERE `ID`=2751 AND `locale`='esMX' AND MD5(`RewardText`)='921e5d697de247b69afcb175f5809429';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Por el vello del lomo de Pezuñanegra, ¡por $guno digno:una digna; de la Orden del mitril!' WHERE `ID`=2759 AND `locale`='esMX' AND MD5(`RewardText`)='dda0d36df2ba5dac6d14a12d972cc18c';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¿Vienes a ayudar? ¡Genial! $B$BNecesito una pieza para un experimento y me $gun:una; falta un $C valiente como tú para conseguirla.' WHERE `ID`=2769 AND `locale`='esMX' AND MD5(`RewardText`)='0abccc205bbff0b176ffc7fc479fdcb8';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Listo! ¡Cuando estés $gpreparado:preparada;, súbete a la plataforma!' WHERE `ID`=2843 AND `locale`='esMX' AND MD5(`RewardText`)='86eb73e9e071e0ab0856b0ff4a5ad289';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Bien, $N, me alegro de tenerte a bordo. Has tomado una buena decisión como $gpeletero:peletera;; quienes llevan armaduras de cuero te aclamarán cuando aprendas a crear partes de armaduras de cuero salvaje. $B$BPongámonos a trabajar, ¿por dónde quieres empezar?' WHERE `ID`=2847 AND `locale`='esMX' AND MD5(`RewardText`)='187e8d7ed55221105ca4360915ebc13d';
UPDATE `quest_offer_reward_locale` SET `RewardText`='El equipamiento Nochefugaz que me has traído es perfecto, $N. No esperaba menos de $gun peletero:una peletera; de tu calibre. $B$BTe has ganado este patrón. Te lo doy de buen grado y espero que te beneficies de él como mereces.' WHERE `ID`=2850 AND `locale`='esMX' AND MD5(`RewardText`)='ddf4a8966529461a33ddb399f6cae70b';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Oh, genial! ¡Los conseguiste! $B$BGracias, $N. ¡Eres $gun:una; $gauténtico:auténtica; salvavidas!' WHERE `ID`=2865 AND `locale`='esMX' AND MD5(`RewardText`)='f0edc7e67dc117d7c91e18330f1067b7';
UPDATE `quest_offer_reward_locale` SET `RewardText`='$gBienvenido:Bienvenida;, $N. Tu informe sobre la glorieta es... preocupante. Parece que, aunque los nagas no estuvieran planeando un ataque, su presencia es una mala señal para nuestra ofensiva en Feralas. En cualquier caso, aquí tienes tu compensación por tu servicio. $B$BParece que el Bastión Plumaluna necesita desesperadamente ayuda con el problema de los nagas Crestafuria. Quisiera ofrecerte a ti la misión, si te parece. Hay mucho que hacer.' WHERE `ID`=2867 AND `locale`='esMX' AND MD5(`RewardText`)='00413f7f404d3e1e7ee0a7379cd9e880';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Bien, $N! La muerte de Lord Shalzaru desconcertará a los nagas durante un tiempo, si no para siempre. La amenaza que suponen ahora está más descontrolada que nunca, y eso te lo debemos a ti. $B$BAquí tienes más dinero del tesoro del Bastión. Te has ganado cada pieza. Tú y los tuyos son siempre bienvenidos en el Bastión Plumaluna, $gamigo:amiga;. $B$BUna cosita más, antes de que te vayas, $N... si pudieras...' WHERE `ID`=2870 AND `locale`='esMX' AND MD5(`RewardText`)='a06ba0e7fc180be52743ab27e0a0c303';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Me alegra ver que te $ginteresado:interesada; interesando la exploración, $N! ¡Con esa maña que te das, podríamos desvelar secretos inimaginables! $B$BLos Discos de Norgannon en Uldaman contenían muchísima información; tú no llegaste a ver sino las capas superiores. Se dice que los Creadores tenían almacenes de información dispersos por todo Azeroth. Y eso nos lleva a Uldum...' WHERE `ID`=2963 AND `locale`='esMX' AND MD5(`RewardText`)='61a9b9e473a97c2d43bdffebb8334ba5';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ahora les enseñamos todo eso y ellos nos enseñan otras cosas. Nos hacemos una única raza... o casi. Somos aliados desde hace mucho, así que recuerda ayudarles. Y Jen''shan recordará ayudarte. $B$BJen''shan te instruye en las artes $gdel:de la; $C, te instruye bien. No olvides nunca, el $C es muy respetado en la tribu. Tú ir a tener un importante papel en el futuro... no olvides nunca. $B$BCuando lo necesites, ven a Jen''shan. Ella te enseña todo lo que pueda cuando crea que estás $gpreparado:preparada;.' WHERE `ID`=3082 AND `locale`='esMX' AND MD5(`RewardText`)='822b04fe5cbe357dd75a56c6f8af04d2';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Tú estar entre los seres más poderosos del planeta, $N... no hay duda. Y todos lo saben... ¡lo saben bien! $B$BPero debes estar $gcansado:cansada;! No haber orco, ni elfo, ni enano al que tú temas... pero haber cosas que no puedes ver. Magia ser poderosa. Te obliga a hacer cosas que no quieres hacer. Te hace creer que eres más poderoso de lo que ser. Ten paciencia. Sé $glisto:lista;. $B$BCuando creas que estás $gpreparado:preparada; para instruirte vuelve con Mai''ah. Te enseña lo que estás listo para aprender, sin problema.' WHERE `ID`=3086 AND `locale`='esMX' AND MD5(`RewardText`)='145c3500bcfa0cc50be099c05786fdf8';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Nos veremos muchas veces en el futuro, y en cada encuentro ganarás un poco más $gpoderoso:poderosa;... Tu espíritu arderá con brío, $N, como la llama eterna. $B$BVete ahora, $n. Ve y ponte a prueba. Estaré aquí si me necesitas.' WHERE `ID`=3093 AND `locale`='esMX' AND MD5(`RewardText`)='a038871f958a565b4755868f5883c751';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Debes volver a mí a menudo si quieres adquirir el poder necesario para destruir a quienes se nos oponen. Aún estás $gsometido:sometida; a las reglas de la magia, $N. La corrupción te seguirá como un lobo hambriento en la noche. Te darás cuenta de que su caricia es como una adicción, como $guna antigua:un antiguo; amante que aún quiere estar a tu lado. Pero esas cosas pueden evitarse. Esas cosas solo te controlan si se lo permites. $B$BAhora, vete. Y vuelve a mí cuando seas más fuerte.' WHERE `ID`=3098 AND `locale`='esMX' AND MD5(`RewardText`)='f4d42bd598b7586cb0e9f5070115f23b';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Había dicho que un esclavo es un esclavo al fin, aunque cambie de amo. ¿Lo recuerdas? Los dos sabemos que es esa clase de control —esa clase de poder— lo que ahora nos motiva. Queremos que las criaturas nos sirvan. Sabemos que somos más poderosos y merecemos más respeto que el que recibimos... y por eso buscamos conseguirlo.$B$BSeré tu aliado en esta lucha, la lucha por nuestra libertad. Libertad para buscar nuestras propias alianzas. Cuando estés sienta $gpreparado:preparada;, vuelve a verme y te enseñaré todo lo que sé.' WHERE `ID`=3099 AND `locale`='esMX' AND MD5(`RewardText`)='818ce6654b06fa4c89a0c6b4b0595c8e';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Oh, sí! Artes Arcanas... claro. $B$BEsto es lo que necesitas saber, $N: no te metas en muchos líos, reserva algún dinerillo para invitarme a cerveza... o comprarme algún hechizo... y mantente $galejado:alejada; de Gnomeregan. Eso es todo. ¡Que tengas un buen día! Estaré por aquí por si me necesitas, o por si quieres entrenar o... lo que sea.' WHERE `ID`=3114 AND `locale`='esMX' AND MD5(`RewardText`)='fe7e902f5eeef27df906709d28f63dec';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Saludos, joven. ¿Has venido para seguir el camino $gdel:de la; $c? $B$BMuy bien. Empecemos.' WHERE `ID`=3261 AND `locale`='esMX' AND MD5(`RewardText`)='a6d2e599149140da535ab35100b995d5';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Írguete y obtén $greconocido:reconocida;, $N, $gherrero:herrera; de la Orden del mitril.' WHERE `ID`=3321 AND `locale`='esMX' AND MD5(`RewardText`)='c67654cb151dc10998e739a155a77351';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Me produces asco, $R. ¿$gUn hombre hecho y derecho:Una mujer hecha y derecha; babeando sobre una pila de baratijas? ¡Qué pena das! Toma tu recompensa y desaparece de mi vista.' WHERE `ID`=3501 AND `locale`='esMX' AND MD5(`RewardText`)='400c4fc23a230afb50f0d25773e9a781';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Me produces asco, $R. ¿$gUn hombre hecho y derecha:Una mujer hecha y derecha; babeando sobre una pila de baratijas? ¡Qué pena das! Toma tu recompensa y desaparece de mi vista. $B$B¿Te suena? Debería, porque lo digo mil veces al día. $B$B¡Oh, cómo aborrezco este mundo!|n' WHERE `ID`=3502 AND `locale`='esMX' AND MD5(`RewardText`)='368a203a974eb1f9cc9374535b0af7c3';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Gracias por encontrar mi collar, $gseñor:señora; $C... Mi gatita también dice gracias, ¿a que sí, Effsee?' WHERE `ID`=3741 AND `locale`='esMX' AND MD5(`RewardText`)='4ed34adc1772c9c060adaf9ec86f9921';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Así que te ha enviado aquí mi hermano Argos, ¿eh? Supongo que debes de estar $gagotado:agotada; de tanto viaje. Pero tenemos mucho que hablar.' WHERE `ID`=3765 AND `locale`='esMX' AND MD5(`RewardText`)='97118d2df30624d17f09b54fd9154f7a';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Bien, $C, veo que fuiste $ginformado:informada; de que yo encabezaba la investigación en persona, y es evidente que viniste tan rápido como pudiste. $B$BAhora que estás aquí, presta atención, pues te daré los detalles una sola vez, no me gusta repetirme.' WHERE `ID`=3790 AND `locale`='esMX' AND MD5(`RewardText`)='297bbdd512ce68dc2c4617e7c5397ce2';
UPDATE `quest_offer_reward_locale` SET `RewardText`='He acabado contigo, $N. Has demostrado ser $gmerecedor:merecedora; de la libertad que te ha sido concedida. Muchos serán los que se alzarán contra ti por lo que eres ahora, pero debes saber que, intenten lo que intenten contra nosotros, somos libres y no volverán a encadenarnos. $B$BToma esto y ponte en camino. Tienes mucho que lograr, $C.' WHERE `ID`=3901 AND `locale`='esMX' AND MD5(`RewardText`)='dc5ed4681d5e356e16d89f516fa61f2a';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Buen trabajo, $N, sabía que no eras $gun:una; inútil. Ten, acepta uno de los mejores objetos que he encontrado entre los lotes que hemos reunido hasta ahora.' WHERE `ID`=3902 AND `locale`='esMX' AND MD5(`RewardText`)='fc357f7c773fec23b8dbae3f76820563';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¿Qué es esto? ¡¿Qué?! ¡Es un churumbele! ¿Dónde lo has conseguido? ¿Has estado curioseando por las instalaciones de Ventura y Cía. en Los Baldíos?$B$BDebes de ser muy valiente, o muy $gestúpido:estúpida;.' WHERE `ID`=3923 AND `locale`='esMX' AND MD5(`RewardText`)='bdc6e560cb276cf4615fdd28081844d3';
UPDATE `quest_offer_reward_locale` SET `RewardText`='<Thrall se muestra muy afectado por la información que acabas de darle.> $B$BUna nueva amenaza se cierne sobre el horizonte. Se acaban los años de Magni y con ello tendrá vía libre la estirpe no nata de Hierro Negro para gobernar Forjaz. $B$BHas cumplido lo que te había encargado y por ello serás $grecompensado:recompensada;. $B$B¡Márchate, $N! Debo discutir algo con Sylvanas y Cairne.' WHERE `ID`=4004 AND `locale`='esMX' AND MD5(`RewardText`)='4a3837d255ba43c5ec63132e4d596842';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Dios mío! ¿Estás $gseguro:segura; de que Incendius dijo "Ragnaros?"$B$B<Jalinda te tiende algo y te da una palmada en la muñeca y se queda pensativa.>' WHERE `ID`=4263 AND `locale`='esMX' AND MD5(`RewardText`)='68f6b34560833e01a9f2739397557427';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Bienvenido a casa, $N. Raschal llegó hace no mucho y me contó lo que ocurrió.$B$BYo... no, todo el Bastión, te agradece enormemente lo que has hecho. Raschal habría muerto si no hubieras llegado tú, y tu ayuda nos ha llegado por apenas la tasa de un mercenario. Eres $gun auténtico héroe:una auténtica heroína;. Siempre contarás con la amistad de Ginro Mechogar.' WHERE `ID`=4265 AND `locale`='esMX' AND MD5(`RewardText`)='4fa6c3b2391b65222e7ce9f1c0c6a41c';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Esta carne servirá, $N. Parece que Lar''korwi no pasa hambre, ¿eh? Me pregunto dónde habrá encontrado un trillanodonte... es extraño.$B$BDe cualquier modo, guardaré esto hasta que estés $gpreparado:preparada; pare enfrentarte a él. No te preocupes por mí, pues seguro que has enfadado tanto a Lar''korwi que no me hará daño hasta que te haya echado el diente a ti.' WHERE `ID`=4290 AND `locale`='esMX' AND MD5(`RewardText`)='4a8ea62d6215cf82bd4ff74d2eafe7cd';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Alabada sea la Madre Tierra! ¡Lo has conseguido! No cabe duda de que eres $gun:una; gran cazador, $N. Has demostrado poseer fortaleza de espíritu y una valentía inigualable, y además has incrementado tu fuerza. Mereces todo mi respeto.$B$BSolo el más poderoso de mis ancestros habría sido capaz de realizar una hazaña como la tuya. Enhorabuena.' WHERE `ID`=4292 AND `locale`='esMX' AND MD5(`RewardText`)='5d5653fa4bc0ccda13b10b93cb9d0514';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¿Qué es esto? ¡Ah! ¡Es el aroma de la cerveza Hierro Negro! La bebida me nubla la vista pero puedo decirte algo, $gseñor:señora;, ¡tú sí que eres $gun amigo:una amiga;!' WHERE `ID`=4295 AND `locale`='esMX' AND MD5(`RewardText`)='0cd984511b232215dbe6e08a7b47c9fa';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Ah, has encontrado la tablilla! ¡Y tu trascripción es excelente! ¿Seguro que eres $gun:una; $C; y no $gun:una; escriba?$B$BAquí tienes, $N. Aquí tienes el pago que te prometí.' WHERE `ID`=4296 AND `locale`='esMX' AND MD5(`RewardText`)='5f96c88f6ef7aa98141dbf1240bd1267';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Es una noticia excelente, $N. Con esas bestias fuera de nuestro camino podemos pensar en adentrarnos en Cuna del Invierno. ¿Estás $glisto:lista; para más?' WHERE `ID`=4521 AND `locale`='esMX' AND MD5(`RewardText`)='ccebe9ac0e4758eae058f147172add60';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Otro de los reclutas de Kaltunk, ¿eh?$B$BPues sí que están mal las cosas, si esto es lo mejor que puede ofrecer la Horda. No importa. Para cuando te llegue el momento de salir del Valle, serás $gun:una; $c $gdigno:digna; de la Horda.' WHERE `ID`=4641 AND `locale`='esMX' AND MD5(`RewardText`)='80a45253da39122b7b6b8342a60df0c5';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Vaya, diría que no has venido aquí solo a informarte! Los ciudadanos estarán encantados de saber que hoy podrán dormir un poco más tranquilos.$B$BHas traído un poco de paz y justicia a la gente de Auberdine, $N y por eso, quisiera ofrecerte esto como recompensa... Serás $gel héroe:la heroína; de las gentes de Auberdine.' WHERE `ID`=4740 AND `locale`='esMX' AND MD5(`RewardText`)='b005b8dab4d607f880f6f7b1fcecd247';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Eso es! Ya siento cómo vuelven mis poderes. Y mi mente ya no sufre el atroz dolor de la maldición de Urok.$B$B¡Gracias, $N! Estoy por encima de la humildad pero debo reconocer tu ayuda.$B$BY te deseo que la Fortuna te acompañe en tus viajes por la Cumbre de Roca Negra. Eres $gun necio:una necia; si crees que vas a alcanzar la cumbre pero tu valor es incuestionable.' WHERE `ID`=4867 AND `locale`='esMX' AND MD5(`RewardText`)='4798fd9ed712ce84cd9f1a043d9cf9d2';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Esto es exactamente lo que necesito, $N. Gracias. $B$BPermíteme recompensarte adecuadamente. Quizás no comprendas para qué podrías necesitar un instrumento así. Puede que ni siquiera sepas qué es. Ay... no puedo decirte cuándo te será de utilidad, pero tienes que saber que llegará un momento en el que lo encontrarás extremadamente útil. Decidas o no conservarlo hasta que llegue ese momento... esto, $gamigo mío:amiga mía;, es tuyo.' WHERE `ID`=4972 AND `locale`='esMX' AND MD5(`RewardText`)='ef1fb6d064f61e9f9914eaf6898110e5';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Lo has logrado! Cuando Lexlort tenga estos planos, se olvidará de todas esas cosas desagradables que quería hacerme. $B$B$N, ¡eres $gmi héroe:mi heroína;!|n' WHERE `ID`=4982 AND `locale`='esMX' AND MD5(`RewardText`)='396d6195da8ff18677cefbb7f4a2134a';
UPDATE `quest_offer_reward_locale` SET `RewardText`='"Sé que los pardos ahora están en paz, y su tormento ha terminado. Yo... tengo algo más para ti. Lo escribí en... en esta rama, porque presentía que mi tiempo en este reino estaba por terminar.$B$BAsí es... mi vida se acaba. Gracias de nuevo, $gamigo:amiga;... Las criaturas de esta tierra maldita pueden descansar... y ahora las acompañaré".$B$BCon esas últimas palabras, el druida emite una profunda exhalación hasta perder el aliento. Su cuerpo yace inmóvil en el piso de la cabaña.' WHERE `ID`=4985 AND `locale`='esMX' AND MD5(`RewardText`)='b9047dc6e8ebf96fd609e0843248ed78';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Esto... esto es muy extraño. Este druida, un druida tauren nada menos, te ha confiado mucha y valiosa información sobre la extensión de la peste de la Plaga. Me sorprende que un tauren diera a $gun:una; $R tal información y mucho más si todo lo que dices es cierto. Haremos un buen uso de esto, te lo prometo. Quizás el tauren no cayera tan lejos de Cenarius como Fandral podría pensar... $B$BErrr... de cualquier forma, por favor, acepta esto como muestra de gratitud del Círculo Cenarion.' WHERE `ID`=4986 AND `locale`='esMX' AND MD5(`RewardText`)='30aacc36fcde75f82a5da41a60786b45';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Que no falle tu disparo y la marca de tu arma sea verdadera, $R. $B$BEl espíritu de Agamaggan está contigo. Vuelve  aquí si quieres. Quebrantadientes volverá a bendecirte si el gran dios jabalí me considera $gdigno:digna;.' WHERE `ID`=5043 AND `locale`='esMX' AND MD5(`RewardText`)='228f7b3d2bf49fa6a77f790b8f783fae';
UPDATE `quest_offer_reward_locale` SET `RewardText`='$gBienvenido:Bienvenida; a las Tierras de la Peste, $ghéroe:heroína;. Esta es una de las fronteras más peligrosas de Azeroth, especialmente por la amenaza de la Plaga que se avecina desde el norte y el noreste. Me alegra saber que no has hecho oídos sordos a la llamada del deber y que te has puesto al servicio de un bien mayor. $B$BSi estás $glisto:lista; para ensuciarte las manos, aquí para $glos héroes dispuestos:las heroínas dispuestas; y capaces en la frontera de las Tierras de la Peste, hay mucho trabajo para héroes valientes y capaces.' WHERE `ID`=5090 AND `locale`='esMX' AND MD5(`RewardText`)='4cafcb47fd909fc3c34f405851600edf';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Misión cumplida, $N! Buena jugada, buena jugada.$B$BDéjame recompensarte por tu trabajo con algunas monedas de las arcas de Ventormenta. Te recomendaría gastar el dinero en algo que te ayude en tu próxima misión... la que te llevará a las ruinas de Andorhal.$B$B¡Deberás estar $gpreparado:preparada;! ¡Mantente alerta!' WHERE `ID`=5092 AND `locale`='esMX' AND MD5(`RewardText`)='9519f4bcd20fbcda451b6b74858a289d';
UPDATE `quest_offer_reward_locale` SET `RewardText`='$gBienvenido:Bienvenida; a las Tierras de la Peste. Esta es una de las fronteras más peligrosas de Azeroth, especialmente por la amenaza de la Plaga que se avecina desde el este. Me alegro de que hayas escuchado la llamada del deber y hayas venido a prestar servicio a la Horda. $B$BSi estás $gpreparado:preparada; para ponerte manos a la obra, hay mucho que puedes hacer aquí, en la frontera de las Tierras de la Peste.' WHERE `ID`=5093 AND `locale`='esMX' AND MD5(`RewardText`)='5cd8cc17f584fbe293dc52c4b1ec3f6f';
UPDATE `quest_offer_reward_locale` SET `RewardText`='$gBienvenido:Bienvenida; a las Tierras de la Peste. Esta es una de las fronteras más peligrosas de Azeroth, especialmente por la amenaza de la Plaga que se avecina desde el este. Me alegro de que hayas escuchado la llamada del deber y hayas venido a prestar servicio a la Horda. $B$BSi estás $gpreparado:preparada; para ponerte manos a la obra, hay mucho que puedes hacer aquí, en la frontera de las Tierras de la Peste.' WHERE `ID`=5095 AND `locale`='esMX' AND MD5(`RewardText`)='5cd8cc17f584fbe293dc52c4b1ec3f6f';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Que el poder de la Luz te ilumine en estos tiempos sombríos, $C. Me complace servirte como coordinadora en nuestro plan para sabotear las calderas de la Plaga. $B$BNuestro objetivo será alterar la composición de la peste que crean las calderas, convirtiéndola en algo que afecte negativamente a la Plaga. Para conseguir este cambio tendrás que acceder a las cuatro calderas de las Tierras de la Peste del Oeste. $B$BHas de estar $gpreparado, héroe:preparada, heroína;, ¡te espera una batalla gloriosa contra la vil Plaga!' WHERE `ID`=5215 AND `locale`='esMX' AND MD5(`RewardText`)='42bfd5a9eed96f51ff86f31b2638c2c0';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Desde las sombras, $ghermano:hermana; $R, te hago llegar mis saludos. Estoy aquí para servirte como coordinadora en nuestro plan para sabotear las calderas de la Plaga. $B$BNuestro objetivo será alterar la composición de la peste que crean las calderas, convirtiéndola en algo que afecte negativamente a la Plaga. Para conseguir este cambio tendrás que acceder a las cuatro calderas de las Tierras de la Peste del Oeste. $B$BHa llegado el momento de que lideres el ataque contra la Plaga, $ghéroe:heroína;.' WHERE `ID`=5228 AND `locale`='esMX' AND MD5(`RewardText`)='590b812d5ddde9a3490e16f34e49b71d';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Felicidades, $N, ¡has conseguido abrirnos la última caldera! El boticario Dithers pronto sabrá qué componentes se necesitan para la mezcla. $B$BEn cuanto a ti, seguro que el sumo ejecutor Derrington querrá agradecerte personalmente la ayuda que nos has prestado. Sin ti nuestra lucha contra la Plaga habría sido prácticamente insuperable. Muchas gracias, $gpoderoso:poderosa; $C.' WHERE `ID`=5236 AND `locale`='esMX' AND MD5(`RewardText`)='2e8cf1ccafbb22074c037c1d6a52a8c3';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Bien hecho, $R. Has demostrado que, aunque eres $gcompasivo:compasiva;, no te detendrás ante nada para acabar con los esbirros de Kel''Thuzad.|n' WHERE `ID`=5243 AND `locale`='esMX' AND MD5(`RewardText`)='04de39e3b4857cd983af0b5e0ad7bb81';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Hace muchos años que no recibo a $gun campeón:una campeona; entre nosotros. Eres $gel primero al:la primera a la; que Lord Maxwell recibe en años.' WHERE `ID`=5263 AND `locale`='esMX' AND MD5(`RewardText`)='08c02649d24f3a07420b85e5556a9bf5';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Eres $gun valioso aliado:una valiosa aliada;, $N. Recogerás los frutos de tu incondicional dedicación.' WHERE `ID`=5264 AND `locale`='esMX' AND MD5(`RewardText`)='62458747e0a45cf78392a8bf09fad077';
UPDATE `quest_offer_reward_locale` SET `RewardText`='No sé de qué conoces a mi hermano pero parece que confía en ti, $C. $B$BYo soy Nataka Cuerno Largo y te doy la bienvenida al Campamento del Espíritu Errante. ¡La ayuda de $gun:una; $C nunca viene mal! Habla con los demás, seguro que hay algo que puedas hacer.' WHERE `ID`=5361 AND `locale`='esMX' AND MD5(`RewardText`)='2d1d498f1ae2d8a4041e63f62907d7fa';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Felicidades, $N. ¡Es un placer recompensarte con una muestra de valor de El Alba Argenta!$B$BAdquirir una muestra de valor de esta forma indica que eres un auténtico héroe de la causa del bien. Valoramos todo esfuerzo hecho contra la Plaga, ¡pero acabar con uno de sus líderes es un auténtico avance hacia su derrota!$B$B¡Por El Alba, $ghermano:hermana;!' WHERE `ID`=5404 AND `locale`='esMX' AND MD5(`RewardText`)='c8c2c7b14c52409bfc6a5695cd982b83';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Felicidades, $N. ¡Es un placer recompensarte con una muestra de valor de El Alba Argenta!$B$BAdquirir una muestra de valor de esta forma indica que eres un auténtico héroe de la causa del bien. Valoramos todo esfuerzo hecho contra la Plaga, ¡pero acabar con uno de sus líderes es un auténtico avance hacia su derrota!$B$B¡Por El Alba, $ghermano:hermana;!' WHERE `ID`=5406 AND `locale`='esMX' AND MD5(`RewardText`)='c8c2c7b14c52409bfc6a5695cd982b83';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Felicidades, $N. ¡Es un placer recompensarte con una muestra de valor de El Alba Argenta!$B$BAdquirir una muestra de valor de esta forma indica que eres un auténtico héroe de la causa del bien. Valoramos todo esfuerzo hecho contra la Plaga, ¡pero acabar con uno de sus líderes es un auténtico avance hacia su derrota!$B$B¡Por El Alba, $ghermano:hermana;!' WHERE `ID`=5508 AND `locale`='esMX' AND MD5(`RewardText`)='c8c2c7b14c52409bfc6a5695cd982b83';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Saludos, $C. He dedicado una parte importante de mis recientes estudios a Scholomance y creo conocer un medio para adquirir una llave... una que te permita cruzar la puerta delantera.$B$BSolo puedo imaginar las atrocidades que podrán verse en su interior, $N. No sé cómo hacen $glos héroes:las heroinas;...' WHERE `ID`=5533 AND `locale`='esMX' AND MD5(`RewardText`)='37fbc245e2a112014e32e77944740172';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Muy bien, $C. Veo que no solo eres $ghabilidoso:habilidosa; sino también $gastuto:astuta;. La derrota de tales criaturas es un testimonio de tu lealtad a los inquilinos de la Madre Tierra, aunque no la reconozcas como tu propia deidad. Está presente en todas las cosas de este planeta y más allá. Sus ojos, uno oscuro y otro claro, viajan por el cielo siempre pendientes de nosotros.$B$BAcepta este puñado de monedas como muestra de aprecio por lo que has hecho.' WHERE `ID`=5536 AND `locale`='esMX' AND MD5(`RewardText`)='d5158968d719dd1f6106de5c8cf7a71e';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Que la Luz te guarde! $gBendito:Bendita; seas, joven.' WHERE `ID`=5544 AND `locale`='esMX' AND MD5(`RewardText`)='ce83656f66f027264a0c226740ae7e7d';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Eres $gdigno:digna; de elogios, $N. Tus esfuerzos han sido de gran ayuda en la lucha contra los demonios y todo Azeroth está más seguro gracias a ti.' WHERE `ID`=5581 AND `locale`='esMX' AND MD5(`RewardText`)='4fccc3e5fdc640c26add0748df6cbc83';
UPDATE `quest_offer_reward_locale` SET `RewardText`='La redención de Vadín será una tarea difícil. ¿Estás $gpreparado:preparada;?' WHERE `ID`=5742 AND `locale`='esMX' AND MD5(`RewardText`)='e14b33d2177a4353b07db7f4fa3bf776';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Sí, eso es! Yo... siempre me sorprenden tus muestras de astucia y valentía. Me dejan atónitos todos tus $gdispuesto:dispuesta; a hacer para alzarte con la victoria.$B$BAhora permíteme hacer mi pequeña parte. He preparado un disolvente especial con el que debería poder fijar el escarabeo como cabeza de la llave, imbuyéndola del poder para forzar la puerta de Scholomance.$B$BMe llevará solo un momento...' WHERE `ID`=5804 AND `locale`='esMX' AND MD5(`RewardText`)='61bedeecdb00f85918979b0fa6901c61';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Gracias, $N. Estas nos servirán.$B$BSi estás $glisto:lista;, podemos pasar a la fase siguiente.' WHERE `ID`=5901 AND `locale`='esMX' AND MD5(`RewardText`)='f838e6527b0425fc2c4641ffaa80e1ec';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡El Libro de los Ancestros! ¡El que tanto tiempo llevaba extraviado! Me aseguraré de que este libro llegue al Alto Consejo. Hoy has hecho algo magnífico. Deberíamos agradecértelo, y te lo agradecemos ¡como a $gun:una; $ghéroe:heroína;!|n' WHERE `ID`=6027 AND `locale`='esMX' AND MD5(`RewardText`)='d28f7dc51c0f2e10ce84fa5c075715d8';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Has hecho un buen trabajo, $N. Creo que estás $glisto:lista; para tu siguiente tarea.' WHERE `ID`=6062 AND `locale`='esMX' AND MD5(`RewardText`)='5c0577944fdd24475688d6fd0bf1a616';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Vaya, $gun:una; joven $C. Sí, te concederé las habilidades que necesitas para domar y guiar a una mascota. No solo podrás enseñar nuevas habilidades a tu mascota, además podrás darle de comer, e incluso resucitarla si cae en combate.$B$BAhora, retírate. Hablaremos más adelante.|n' WHERE `ID`=6081 AND `locale`='esMX' AND MD5(`RewardText`)='48b3e201debd80f34d1275d4675d9a8f';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Saludos, joven $C. Me alegra ver que estás $gdeseoso:deseosa; de aprender sobre la sanación de venenos.$B$BEn el pasado, muchos druidas eran sometidos a diversas pruebas, pero tu trabajo no implicará tal cosa. En El Cruce de Los Baldíos ha habido una epidemia de envenenamientos de animales, pero allí no han sabido controlarla. Un representante de El Cruce ha pedido ayuda al Claro de la Luna y nosotros vamos a enviarte a ti como respuesta. No se trata de un ejercicio práctico, el trabajo que tendrás que realizar es real. Tenlo en cuenta.' WHERE `ID`=6126 AND `locale`='esMX' AND MD5(`RewardText`)='45ab7bc02fd65be5a78f46eddf688379';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ya siento que la ira me abandona. ¿Qué haré con mi tiempo? Saber que el mal rondaba cerca de mis tierras era lo que mantenía mi mente ocupada, pero ahora está en reposo. Tal vez sea lo mejor... tal vez ahora pueda concentrarme en las bondades de la vida, como todo $r.$B$BAcepta esta recompensa por las molestias.' WHERE `ID`=6283 AND `locale`='esMX' AND MD5(`RewardText`)='3012efae19a486d931e3630405323db3';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Buena cacería, $N! Besseleth es una vieja depredadora de esta zona... No la echaré de menos. Acepta esta recompensa por ser $gel campeón:la campeona; del bosque.$B$B$B$BQuizás ahora, muchos más irán al Refugio Roca del Sol sin temer lo que acecha en la oscuridad.' WHERE `ID`=6284 AND `locale`='esMX' AND MD5(`RewardText`)='57d8735eb52d8c834c79a9e6f0239e64';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ah, un nuevo fardo de pellejos. ¡Me pondré a trabajarlos de inmediato!$B$BGracias, $ghermano:hermana;. Me has hecho un gran favor. Aquí tienes unas monedas por tu tiempo y los gastos del viaje.' WHERE `ID`=6362 AND `locale`='esMX' AND MD5(`RewardText`)='db4a3d992ed6b6ea8ec3cebd6cec6fb8';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Oh, qué maravilla! ¡Unas tajadas estupendas! Son de Zargh, ¿verdad? Ese $r sí que sabe robarle el corazón a una dama...$B$BOh, me muero por cocinarlas. ¡Aunque no demasiado! La carne es mejor cuando está roja, ¿no te parece?' WHERE `ID`=6384 AND `locale`='esMX' AND MD5(`RewardText`)='65b82c60d087e258ad93f9e4c1c665f5';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¿Tenemos tan pocos soldados aptos que Nefarian se dedica a enviarme crías? Nunca superarás mis pruebas, $gcachorrito:cachorrita;.' WHERE `ID`=6570 AND `locale`='esMX' AND MD5(`RewardText`)='643973c5cb0fe458f7c65f017f9a4197';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Dudaba de tu dedicación, $gmocoso:mocosa;. Has perseverado, dominando a nuestros enemigos, honorando a nuestro Vuelo.$B$BAhora debo preparar los cráneos para tu ascenso.' WHERE `ID`=6585 AND `locale`='esMX' AND MD5(`RewardText`)='593ac6f670901e61b1970dd2e9a14d58';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Fantástico, $gamigo:amiga;. Mi hermano las necesita vivitas y coleando, si no, se vuelven amargas... Y no nos gustan los kebabs de rata amargos, ¿verdad?' WHERE `ID`=6661 AND `locale`='esMX' AND MD5(`RewardText`)='628789ebbab0ca44724c6f03c8c20e7e';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Espléndidamente espléndido! Me alegra ver que has vuelto con el residuo, ¡y con todos tus apéndices intactos, cabeza y todo! Eso está muy bien... no es que el Ultra-reductor fuera peligroso, pero, oye...$B$BAh, y aprecio mucho tu ayuda, $N. De verdad, eres $gun buen amigo:una buena amiga; de los goblins de todo el mundo. Acepta esto como muestra de mi agradecimiento.' WHERE `ID`=7003 AND `locale`='esMX' AND MD5(`RewardText`)='87981c502334c975f59d0315e77a4c40';
UPDATE `quest_offer_reward_locale` SET `RewardText`='¡Hola, $N! Me alegra ver que $gun:una; $C como tú está impaciente por aportar su granito de arena a la Horda. Vuelve a hablar conmigo, tengo tareas vitales para ti...' WHERE `ID`=7123 AND `locale`='esMX' AND MD5(`RewardText`)='11f833dbdcfdcdc605adf7d493d91c83';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Para convertirte en $gun:una; soldado Lobo Gélido, hay que ponerte a prueba...' WHERE `ID`=7241 AND `locale`='esMX' AND MD5(`RewardText`)='597343fbc103aa13d122d477c80c7c90';
