UPDATE `quest_request_items_locale` SET `CompletionText`='Sé $gbienvenido, hijo:bienvenida, hija;. Siempre es un placer recibir a poderosos aventureros en el Templo. Si tienes tiempo, ¿podrás compartir alguna de tus historias con los aventureros más jóvenes? Sé que muchos de ellos sacarían provecho de tu sabiduría.$B$BAy, perdona mi mala educación. Has venido al Templo en busca de ayuda y yo abuso de tu amabilidad. Te ruego que me perdones. Dime qué podemos hacer por ti los siervos de la Luz.' WHERE `ID`=2972 AND `locale`='esMX' AND MD5(`CompletionText`)='211daafe5057909b5654998dd48e38d0';
