UPDATE `quest_offer_reward_locale` SET `RewardText`='Ich muss schon sagen, dies klingt überhaupt nicht gut. Ich wusste nicht, dass die Lage, in der Stoutmantle sich befindet, der unseren hier in Seenhain nicht unähnlich ist. Was kann nur so wichtig sein, dass es die Armee von Stormwind davon abhält, dem Volk, das sie beschützen soll, zu Hilfe zu eilen? Aber ich sollte nicht laut grübeln.$B$BHier, $GBote:Botin;. Nehmt diese Münzen als Bezahlung für Eure Verdienste um die Stadt entgegen. Es wäre möglich, dass ich Eure Hilfe ein weiteres Mal benötige.' WHERE `ID`=144 AND `locale`='deDE' AND MD5(`RewardText`)='1ec246b924d2c2e3118b7881f201e67e';
