UPDATE `quest_offer_reward_locale` SET `RewardText`='Sehr schön gemacht, $Galter Junge:die Dame;!' WHERE `ID`=194 AND `locale`='deDE' AND MD5(`RewardText`)='608bfffc7799a1bc8a3c27c9703b5d5b';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Hoho! Sieh an, wir haben hier $Geinen wahren Raptorentöter:eine wahre Raptorentöterin;! Sehr schön gemacht, $Galter Junge:werte Dame;!' WHERE `ID`=196 AND `locale`='deDE' AND MD5(`RewardText`)='17771203025d0863a70530bfa69107bb';
UPDATE `quest_offer_reward_locale` SET `RewardText`='$GMeister:Meisterin; $N, $Gder Raptorentöter:die Raptorentöterin;!$B$BKlingt gar nicht schlecht, wie?' WHERE `ID`=197 AND `locale`='deDE' AND MD5(`RewardText`)='743aa9aea5948c06976c67ba86a46754';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ihr habt Eure Mission gut erfüllt, $R. Der König selbst wäre stolz auf Euch.$B$BDie Verstärkung, die uns versprochen war, ist jedoch nie angekommen. Anscheinend ist die Front der Allianz getränkt von dem roten Blut unserer gefallenen Brüder. Die Nachricht von diesen Verlusten hinterlässt einen bitteren Nachgeschmack. Doch wir dürfen nicht zulassen, dass ihr Tod vergeblich war. In diesen finsteren Zeiten müssen wir zusammenstehen und den Ruhm der Allianz wieder aufleben lassen.$B$BSprecht wegen Eurer nächsten Aufgabe mit Gebirgsjäger Wallbang. Wir brauchen Euch jetzt mehr als je zuvor.' WHERE `ID`=237 AND `locale`='deDE' AND MD5(`RewardText`)='0197e172611d490eaa2e96936c8ec292';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ah, unsere Kraftquellen vom Typ 4711-FTZ! Normalerweise verwenden wir sie, um Brunnen anzutreiben, aber DANK DER WIDERWÄRTIGEN NOMADEN haben wir im Moment einen Überfluss an Kraftquellen.$B$BNatürlich kann ich Euch eine Kraftquelle für jedes beliebige schändliche Wissenschaftsexperiment besorgen, das Ihr vor mir zu verstecken sucht. Aber das kostet Euch etwas, $R. In Gadgetzan gibt es nichts umsonst.' WHERE `ID`=243 AND `locale`='deDE' AND MD5(`RewardText`)='7dc1d9087c8437fa91afa04da4eb89c8';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Indem Ihr die Anzahl der Gnolle verringert habt, habt Ihr Euch um das Wohlergehen des Sumpflandes gekümmert. Obwohl mein Vertrauen in Euer Volk in der Vergangenheit belastet wurde, $R, kann es vielleicht doch noch wieder hergestellt werden.' WHERE `ID`=276 AND `locale`='deDE' AND MD5(`RewardText`)='77aac24747466f5c2e9db5521d6e7547';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Dextren Ward hat also endlich für seine Verbrechen an der Menschheit bezahlt? Ich wünsche diesem Abschaum eine gute Reise. Und meinen Beifall an Euch, $Gmein Freund:liebe Freundin;! Ihr habt nicht nur den Familien der Toten den Seelenfrieden gebracht, den sie verdienen, sondern auch eine klare Botschaft an diese korrupten Bürokraten im Oberhaus geschickt. Stormwind muss sich der Probleme der Leute aus dem Dämmerwald annehmen, oder wir werden uns von ihrer Tyrannei befreien.' WHERE `ID`=377 AND `locale`='deDE' AND MD5(`RewardText`)='285ac150b08a3c07fda51ea225f80678';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ihr habt meine Werkzeuge? Gut gemacht, $GJunge:Mädchen;, gut gemacht! Ich habe gerade vor einer Stunde meine letzte Zahnratsche zerbrochen, und ich brauche eine, um die Reparatur an Pilot Stonegears Belagerungsmaschine abzuschließen. Gut, dass Ihr diese Werkzeuge hierher geschafft habt, $N.$B$BHier, nehmt diese Münzen, für Eure Hilfe.' WHERE `ID`=400 AND `locale`='deDE' AND MD5(`RewardText`)='ace6a974df1ae2c876516a9221348492';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Es sieht so aus, als hättet Ihr mich gefunden, junger $R. Melithar ist ein weiser Druide, wenn er Euch geschickt hat.' WHERE `ID`=458 AND `locale`='deDE' AND MD5(`RewardText`)='e8483b4a99b59d43128edcc674d080a4';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Hallo $N. Ihr seid hier wegen des Auftrags, den ich habe, hm? Es tut gut zu sehen, dass Ihr ein junger $R seid, dessen Blut bei der Aussicht auf Abenteuer in Wallung gerät.' WHERE `ID`=467 AND `locale`='deDE' AND MD5(`RewardText`)='9142242d082ef6b0f6fdbee0fef175b8';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Welcher $Gmutiger:mutige; $C bringt Kunde aus Menethil? Ah, $N werdet Ihr genannt.$B$BIhr bringt Hoffnung in eine hoffnungslose Situation. Gut zu wissen, dass der junge Harlo überlebt hat. Auf der Flucht wurde ihm eine ernste Wunde zugefügt. Wir hatten kaum die Zeit, ihn auf dem Rücken des letzten überlebenden Reittiers unseres Regiments fortzuschicken.$B$BAber wir sind hier in einer gefährlichen Lage. Dun Modr ist gefallen, und wir sind nur ein Schatten des großen Regiments, das wir einmal waren.' WHERE `ID`=472 AND `locale`='deDE' AND MD5(`RewardText`)='100b2b621266cdabf56d5c841738a5a4';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ihr hattet Erfolg, $Gjunger:junge:c; $C! Gut gemacht. Und gerade rechtzeitig, wie ich hinzufügen möchte.' WHERE `ID`=483 AND `locale`='deDE' AND MD5(`RewardText`)='873b28468f50320597c0b16d1d63bc08';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ihr habt den guten Leuten von Dolanaar und Darnassus gute Dienste geleistet, $Gtapferer:tapfere:c; $C. Als Mitglied der Schildwache von Teldrassil beglückwünsche ich Euch zu Euren Bemühungen.' WHERE `ID`=487 AND `locale`='deDE' AND MD5(`RewardText`)='b634911cd3f994981ba57f2a328130ec';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ha ha! Wirklich hervorragend.$B$BWer hätte jemals gedacht, dass ein $R mir, Zenn Foulhoof, meine Wünsche erfüllen würde? Selbst ich hätte es nicht geglaubt. Aber so geht es nun mal... unsere so geliebte Welt ist doch voller Überraschungen.$B$BEin Hoch auf die Naiven und Gutgläubigen!' WHERE `ID`=488 AND `locale`='deDE' AND MD5(`RewardText`)='f31bf168066064d71b075cca5a10f55d';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Wie nett $Gein netter:eine nette:r; $R! Ich wusste, dass Ihr nützlich sein würdet!' WHERE `ID`=489 AND `locale`='deDE' AND MD5(`RewardText`)='82a8b010bba437c1a342f59893c60ab7';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ihr seid Farrens $GJunge : Mädchen; für alles, wie?$B$BWenn Ihr Farren beim Sammeln dieser Köpfe behilflich wart, dann vielen Dank. Southshore braucht eifrige Arbeiter und große Bemühungen um seinen Schutz aufrechtzuerhalten.' WHERE `ID`=560 AND `locale`='deDE' AND MD5(`RewardText`)='e2255cc78ec3257c4a3f820a70555dd8';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ja. Diese werden mir gute Dienste leisten. Wenn mein Geist befreit wurde, werde ich mit drei guten Dienern in das Nether eintreten!$B$BIhr seid eine Zierde Eures Klans, $R, und Ihr habt mich beschwichtigt.' WHERE `ID`=585 AND `locale`='deDE' AND MD5(`RewardText`)='5db09b357ca15ce9872f0d339acdb087';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Wir haben den Angriff überlebt!$B$BOhne Euch hätten wir es nicht geschafft, $N.$B$BSobald die Flut kommt, werden wir hier wegsegeln. Wenn Ihr nicht ein so viel versprechender Held wärt, würde ich Euch einen Platz in meiner Crew anbieten. Aber ich seh schon, Ihr habt Größeres vor.$B$BAuch wenn Ihr nur ein schwacher $R seid...' WHERE `ID`=667 AND `locale`='deDE' AND MD5(`RewardText`)='cad5b323b8b2bdf3cf0b02c245551b8f';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Die $R von Narache danken Euch, $N. Das war sehr vielversprechend.' WHERE `ID`=747 AND `locale`='deDE' AND MD5(`RewardText`)='b05320a78be90cf65de4c8d5985624f9';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Die $R von Narache danken Euch, $N. Eines Tages wird man Euch in Thunder Bluff bestimmt wegen Eurer Jagdfertigkeiten verehren.' WHERE `ID`=750 AND `locale`='deDE' AND MD5(`RewardText`)='98ca0a47e6bc28622fedc59fc6cbca63';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ihr habt diese Kanne wohl auf Großmutters Bitte hin zurückgetragen.$B$BEure Bereitschaft anderen zu helfen und für die $R im Camp Narache zu sorgen, lässt mich glauben, dass die $R in Thunder Bluff eines Tages stolz auf Euch sein können.' WHERE `ID`=753 AND `locale`='deDE' AND MD5(`RewardText`)='01a8907a5c3978a58227986ab7c8c38e';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Die Nachricht von Eurer Tat hat mich soeben erreicht - die Tiere im Umkreis des Brunnens trinken bereits wieder gierig daraus.$B$BIhr habt dem Land einen großen Dienst erwiesen, $N. Und Ihr habt dem Volk der $R einen großen Dienst erwiesen.' WHERE `ID`=754 AND `locale`='deDE' AND MD5(`RewardText`)='41dddd8fd0ed5b935888e71bc96ff23d';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ich weiß, dass es nicht leicht war, an diese Federkiele heranzukommen, $N. Ihr habt damit bewiesen, dass Ihr $Gein würdiger:eine würdige:c; $C seid. Es ist gut, Euch hier in Bloodhoof zu haben.' WHERE `ID`=761 AND `locale`='deDE' AND MD5(`RewardText`)='f1c65e28f10b01ff26ad44aef3ebb85c';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ich glaube nicht, dass man dieses Signal fehldeuten oder ignorieren kann, oder? Die Venture Company wird die $R nicht mehr auf die leichte Schulter nehmen oder so arrogant sein zu glauben, dass wir ihren Diebstahl der natürlichen Rohstoffe um uns herum einfach so widerstandslos hinnehmen.' WHERE `ID`=764 AND `locale`='deDE' AND MD5(`RewardText`)='8235282ac726fde75fcb9e70bf7b1bcc';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Das ist in der Tat sehr beunruhigend! Aber durch diese Informationen können wir all unsere Brüder in Bloodhoof aufrufen, uns bei der Abwehr des Angriffs zu helfen. Ihr habt das Leben vieler $R gerettet, $N.' WHERE `ID`=781 AND `locale`='deDE' AND MD5(`RewardText`)='5f7e1fc075d611073f5877e0bb002435';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Es ist schön zu sehen, dass uns noch mehr unserer Verbündeten von so weit entfernt wie Thunder Bluff zu Hilfe kommen, $R. Ich heiße Euch erneut willkommen.' WHERE `ID`=854 AND `locale`='deDE' AND MD5(`RewardText`)='5873e4eb3650984912e1e134d7a9a8cc';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ja, ja... viel Freude, da endlich <schnaubt> die Borstennacken den Schmerz meines Stammes kennen, $R. Das sollte ich fühlen, aber das ist nicht  der Fall.$B$BMan hilft seinen Leuten und sie ehren einen. Quetschzahn hilft seinen Leuten, und was tun sie? Sie drehen ihm den Rücken zu. Sie vergessen ihn und lassen ihn in einem Käfig verrotten!$B$BIch helfe ihnen sogar hinter Gittern und sie schicken niemanden, um mich zu retten!' WHERE `ID`=878 AND `locale`='deDE' AND MD5(`RewardText`)='38a752f23cab4af34a66130e7036ea9c';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Dann ist es vollbracht. Besser, wenn es so endet, sagt Quetschzahn. <schnaubt> Sie hätten <schnaubt> sicherstellen sollen, dass ich tot bin, als sie mir den Rücken zuwendeten, statt mich <schnaubt> in diesem verlassenen Käfig zu lassen.$B$BJetzt gibt es für Euch nur noch eine Aufgabe zu beenden, $R.' WHERE `ID`=879 AND `locale`='deDE' AND MD5(`RewardText`)='ec4c864012af08adfe36043f7a0a4790';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Was für eine Erleichterung, dass ich all mein Zeug zurückhabe, also danke ich für Eure Hilfe, $N. Wisst Ihr, ein $R wie Ihr wäre für meine Unternehmung hier sehr von Nutzen. Solltet Ihr jemals auf Arbeitssuche sein, denkt daran, wie gut Gazlowe für Dienstleistungen zahlt!' WHERE `ID`=888 AND `locale`='deDE' AND MD5(`RewardText`)='adb0043ccb0749fa4179c9261a982f0d';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Gut. Geht mit Agammagans Geist als Anführer, $R. Kehrt zu mir zurück, wenn Ihr mehr von Agammagans Magie benötigt.' WHERE `ID`=889 AND `locale`='deDE' AND MD5(`RewardText`)='bceaad1b70a824660b08e4777d27d8c5';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ah, ich sehe, Ihr wart damit beschäftigt, $N. Gras zu lauern und Streuner zu jagen. Glaubt Ihr, dass es an der Zeit ist, einem Champion unter ihnen gegenüberzutreten?' WHERE `ID`=903 AND `locale`='deDE' AND MD5(`RewardText`)='a7c06da1032d237a81cdfbfa63853948';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ahhh... Womit habe ich die außerordentlich große Ehre Eurer Begleitung verdient, oh $R? Wahrlich sagt dies viel über meine momentanen Gefährten aus - ohne meine Gastgeber, die edlen Grells und Satyrn, beleidigen zu wollen -, aber man könnte Eure Anwesenheit durchaus als Verbesserung betrachten.$B$BAber bitte, lasst Euch durch mein unzivilisiertes Gerede nicht von hier vertreiben. Es ist in der Tat schon viele Jahre, sogar Jahrzehnte her, dass ich solch höfliche Begleitung hatte.' WHERE `ID`=954 AND `locale`='deDE' AND MD5(`RewardText`)='e4407a55d78a62b7f6943ef4e5c344f7';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ah, es ist da! Ich habe schon eine ganze Weile auf diese rare Erde gewartet. Hoffentlich ist sie noch frisch...$B$BDanke, dass Ihr sie mir gebracht habt, $N. Ihr seid $Gein:eine:r; $R, $Gder:die:r; sich noch die Zeit nimmt.' WHERE `ID`=997 AND `locale`='deDE' AND MD5(`RewardText`)='84c4bee2ebf9c4290b1ed1bc5be72a9e';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Danke, $R, Ihr seid sehr freundlich. Der Geist meiner Schwester ist dankbar für Eure Bemühungen.' WHERE `ID`=1032 AND `locale`='deDE' AND MD5(`RewardText`)='9ca28331f17e90c397ce4985a7cc835a';
UPDATE `quest_offer_reward_locale` SET `RewardText`='$R, hä? Muss gestehen, solche wie Euch sieht man hier nicht oft. Sucht Ihr jemanden, hä? Einen Moment, das steht bestimmt in einer meiner Listen.$B$BHier zieht ein Haufen Volk durch, also gebt mir einen Moment Zeit.' WHERE `ID`=1039 AND `locale`='deDE' AND MD5(`RewardText`)='f62c51fac0ed8efa91e68c30901c22bc';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Grenka war selbst nach $R-Standards mächtig. Ihr solltet stolz auf Eure heutige Leistung sein.$B$BBeim Test des Glaubens hast du die Kraft des Geistes gezeigt, und jetzt auch Belastbarkeit im Kampf gegen die Harpyien der Wildfedern, doch die Zeit ist reif für einen neuen Test.' WHERE `ID`=1150 AND `locale`='deDE' AND MD5(`RewardText`)='b82d9ef70dfebbb5c304c3613e5b1771';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Sehr gut, $R. Ich vermissen Sachen sehr. Ich Euch jetzt mögen.' WHERE `ID`=1166 AND `locale`='deDE' AND MD5(`RewardText`)='86395f1401e83047cbcbbe471d3fe98e';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ihr tötet viele der Armee der schwarzen Großdrachen. Ihr Kriegerheld, $R.$B$BMacht Tharg glücklich.' WHERE `ID`=1168 AND `locale`='deDE' AND MD5(`RewardText`)='3c80c238cce2fe3728db8ef7070b8176';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ihr, $R, habt Pozzik geholfen, richtig? Ich war einst wie Ihr, rannte in der Boxengasse herum und machte jede Arbeit, die die Mechaniker mich tun ließen.$B$BJetzt seht mich an! Der Super-Rennfahrer des Goblin-Teams!' WHERE `ID`=1186 AND `locale`='deDE' AND MD5(`RewardText`)='dc7959a30e90d42b03a03fe502165578';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Was wollt Ihr, $GJunge:Mädchen;? Seht Ihr denn nicht, dass ich mich hier um Probleme kümmern muss? Wer hat schon Zeit, hier rumzustehen und mit einer Quasselstrippe von <Volk> zu plaudern?$B$BEs kommen Trolle aus dem Unterholz! Fasst Euch kurz.' WHERE `ID`=1449 AND `locale`='deDE' AND MD5(`RewardText`)='e54570e5bec2e73c12c7226b7cabd0fc';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Um... hi. Meine Name ist Randis und ich glaube du suchst nach mir? Ihr seid ein Abenteurer, genauso wie es meine Mama und mein Papa waren. Ich bin so glücklich Euch zu treffen!$B$BHoffentlich erleben wir zusammen viele lustige Sachen. Es gibt so viele Sachen, die ich gerne einmal machen würde und die Matrone hat gesagt, dass Ihr diese Woche so etwas wie $Gmein großer Bruder:meine große Schwester; seid. Das finde ich toll!' WHERE `ID`=1468 AND `locale`='deDE' AND MD5(`RewardText`)='5f42e4b9145e2de5d5eeb99e337b9589';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ein $R, hm? Ich hoffe, Ihr seid nicht wegen ihm gekommen. Er hat es nicht geschafft. Diese Goblins haben ihn alle gemacht.$B$BEr sagte nur, er bräuchte ein Heilgebräu, sonst nichts.' WHERE `ID`=1510 AND `locale`='deDE' AND MD5(`RewardText`)='1dd428991ce294c8568d0b037da0b9e5';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ja?$B$BMmm, ich habe das Gefühl, als wüsste ich, was Ihr mich fragen wollt: was veranlasst jemanden, hier im tiefsten Brachland zu leben, ständig von Stachelebern bedroht und ohne Schutz? Wir alle haben unsere Gründe, mit denen wir unser Tun rechtfertigen. Die wahre Frage ist jedoch, was führt einen bescheidenen $R in die entlegensten Winkel des Brachlandes, um mit einer Frau zu sprechen, die sich eindeutig nicht um ihr Wohlergehen schert?$B$BIch wette, die Antwort darauf kennen wir beide.' WHERE `ID`=1530 AND `locale`='deDE' AND MD5(`RewardText`)='3dfe74a1ff6e6ee9603b59aa8fa0b36a';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ich kann nicht glauben, dass Ihr sie gefunden habt! Ihr seid der $R mit dem meisten Glück in Kalimdor!' WHERE `ID`=1579 AND `locale`='deDE' AND MD5(`RewardText`)='fe660356c12bd9fc9dfe0e18b522d3d8';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Sehr gut, sehr gut! Ihr habt Eure Sache gut gemacht, $N. Vielleicht ist das Interesse, das man Euch entgegenbringt, ja doch gerechtfertigt.$B$BAber das müssen andere entscheiden... vorausgesetzt, Euer Wichtel überwältigt Euch nicht und bereitet damit Eurer Karriere ein vorzeitiges Ende. Vorerst bin ich schon damit zufrieden, dass Ihr die ersten Monate als $C vermutlich überleben werdet.$B$BEin Wort zu dem Wichtel, $N. Lasst Euch, wie jeder $R weiß, nicht von der Größe täuschen, seine Magie kann sehr gefährlich sein.' WHERE `ID`=1599 AND `locale`='deDE' AND MD5(`RewardText`)='ba6caa5de287acd2f8cfde6f918d6075';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ich kann Euch nicht genug danken, $GBruder:Schwester;.$B$BDa Ihr das Symbol des Lebens tragt, kann ich nur vermuten, dass Tiza und Muiredon Euch hergeschickt haben.$B$BEs stimmt, ich wurde Opfer der Dunkeleisenzwerge, als ich versuchte, eines der Manuskripte zu bekommen: Es gelang mir so lange durchzuhalten, bis Muiredon entkommen konnte, aber das Licht hätte mich fast in sich aufgenommen, als Ihr gekommen seid. Dass Ihr mächtig genug wart, das Symbol zu benutzen, bedeutet eine große Zukunft für Euch, doch davon wollen wir später sprechen.' WHERE `ID`=1783 AND `locale`='deDE' AND MD5(`RewardText`)='9e94b7ab74bb2945087b655bb2007a16';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ordentlich gemacht, $N! Diese Lektion wird der Dämon nicht so schnell vergessen.$B$BEr wird es sich zweimal überlegen, ehe er seinen hässlichen Kopf noch einmal in diese Welt steckt und nach dem dummen sterblichen Wesen sucht, das ihn besiegt hat. Diesmal wahrscheinlich mit Freunden. Großen, schuppigen Freunden, die nichts lieber machen als Euch in kleine $R-Stücke zu reißen.$B$BIch hab Euch doch keine Angst gemacht, oder ...$N?' WHERE `ID`=1955 AND `locale`='deDE' AND MD5(`RewardText`)='d91825de48ef8de61be4aa3602b87913';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Es wird Zeit, loszuziehen, $R - die Welt wartet.' WHERE `ID`=2259 AND `locale`='deDE' AND MD5(`RewardText`)='270bda43e6565f77427ebd614adc106c';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Wurde auch Zeit, dass ihr auftaucht! Ich hätte fast meine Wette mit Olaf verloren!$B$BEr hat gewettet, dass ihm sein Bart bis zu den Knien wachsen würde, ehe ihm wieder $Gein:eine:r; $R vor die Augen kommen würde. Aber jetzt seid Ihr hier, und wie Ihr sehen könnt, fehlen Olafs Bart noch ein paar Zoll.$B$BDanke, $N. Ich werde den Gewinn mit Euch teilen.' WHERE `ID`=2398 AND `locale`='deDE' AND MD5(`RewardText`)='2e2ed6ade65f36552107ea49716e0fba';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Oh prima, Ihr habt welche gefunden! Vielen Dank, $N. Ihr seid der verlässlichste $R, den ich je getroffen habe!$B$BIch kann es kaum erwarten, sie an einigen der Geräte auszuprobieren, an denen ich rumgebastelt habe. Ich wette, dass unter den richtigen Umständen ein Gerät, das mit so einem Stein angetrieben wird, läuft und läuft und läuft ...' WHERE `ID`=2418 AND `locale`='deDE' AND MD5(`RewardText`)='4fa4b10aad53034de0315b4ca1fcb0d4';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ich habe mich endlich der Kontrolle der Knarzklauen entzogen. Danke, $N.$B$BNun kann mein Geist auf immer friedlich im Smaragdgrünen Traum verweilen.$B$BVielleicht treffen wir uns eines Tages wieder, $Gjunger Freund:junge Freundin;. Doch zunächst nehmt bitte diese Belohnung als Zeichen meiner Dankbarkeit an.' WHERE `ID`=2561 AND `locale`='deDE' AND MD5(`RewardText`)='d110b7cef6eb51b1e6aa37b4021b4452';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ich stelle mir gern vor, dass das Letzte, was ihm durch den Kopf ging, bevor er zu Boden sank, Euer Fuß war, $R. Jetzt, da Thermaplugg tot ist, sind wir der Verwirklichung unseres Plans, Gnomeregan wiederzuerobern, einen Schritt näher gekommen.' WHERE `ID`=2929 AND `locale`='deDE' AND MD5(`RewardText`)='cbc27a6462607ac042726946a9e4ad12';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Belgrom hat Euch also hergeschickt. Ihr kommt gerade rechtzeitig, $R.$B$BLasst mich die Situation erklären und dann könnt Ihr entscheiden, ob Ihr Euch der Herausforderung gewachsen fühlt... Doch wenn Belgrom Euch geschickt hat, dann besteht sicher kein Zweifel an Eurem Mut.' WHERE `ID`=2981 AND `locale`='deDE' AND MD5(`RewardText`)='7bb55e885d0aa0c51d0765773d80123c';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Oh, ja! Arkane Künste... klaro.$B$BDas müsst Ihr wissen, $N: Geht Ärger möglichst aus dem Weg. Spart einige Münzen auf, um mir ein Bier zu kaufen... oder irgendwelche Zauber, die Ihr wollt. Und bleibt auf jeden Fall weg von $Reregan. Ansonsten wünsche ich Euch einen angenehmen Tag! Ich werde hier sein, wenn Ihr mich braucht oder trainieren wollt... oder was auch immer.' WHERE `ID`=3114 AND `locale`='deDE' AND MD5(`RewardText`)='9cac69075b564345378ff63344ec6904';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Was ist denn das?$B$BOh nein, das kann ich gar nicht glauben! Wisst Ihr, was Ihr da habt, $R? Dies ist das Horn von Margol! Margol ist der Fluch eines jeden Archäologen, der jemals seinen Fuß in die sengende Schlucht gesetzt hat.$B$BKann ich es behalten?' WHERE `ID`=3182 AND `locale`='deDE' AND MD5(`RewardText`)='12d407e857a27e69b1185d415213c27a';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ihr widert mich an, $R. $GEin erwachsener Mann:Eine erwachsene Frau;, sabbernd über einem Haufen Plunder? Jämmerlich! Nehmt Eure Belohnung und geht mir aus den Augen.' WHERE `ID`=3501 AND `locale`='deDE' AND MD5(`RewardText`)='e3264dd90fe02ded950262791fcdf8f6';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ihr widert mich an, $R. $GEin erwachsener Mann:Eine erwachsene Frau;, sabbernd über einem Haufen Plunder? Jämmerlich! Nehmt Eure Belohnung und geht mir aus den Augen.$B$BKommt Euch das bekannt vor? Das sollte es, denn ich sage das ungefähr tausend Mal am Tag.$B$BOh, wie ich diese Welt verabscheue.' WHERE `ID`=3502 AND `locale`='deDE' AND MD5(`RewardText`)='3dce3f7e51e7d77f417690bc1fd37560';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Hier ist Eure erste Gnomen-Ingenieur-Mitgliedskarte!$B$BDiese Karte wurde für vierzehn Tage im Voraus bezahlt; alle Karten laufen nach zwei Wochen Aktivität ab. Ist das geschehen, zahlt Ihr Euren nächsten Beitrag bei einem beliebigen Gnomen-Ingenieurskunstlehrer ein, um eine weitere Karte zu erhalten. Ohne die Karte wird Eure Mitgliedschaft zeitweilig unterbrochen und Ihr habt keinen Zugriff auf neue Baupläne.$B$BDas hat natürlich keinen Einfluss auf das, was Ihr bereits wisst. Einmal Gnomen-Ingenieur, $N.' WHERE `ID`=3641 AND `locale`='deDE' AND MD5(`RewardText`)='20bb572efaeaf0bf0572c8638e284317';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ich danke Euch für Euer Kommen, $Gmüder Reisender:müde Reisende;! Erlaubt mir, mich vorzustellen - ich bin Quintis Jonespyre, Druide und bescheidener Diener von Malfurion und dem Zirkel des Cenarius. Meine Kollegen (General Shandris Feathermoon und das Protektorat - vielleicht habt Ihr schon von uns gehört) und ich möchten mit Euch über die Arbeit sprechen, die Ihr für Fandral Staghelm in Darnassus erledigt.$B$BBevor wir weitermachen, möchte ich Euch jedoch bitten, unser Gespräch für Euch zu behalten. Wenn Ihr damit kein Problem habt, dann können wir fortfahren.' WHERE `ID`=3787 AND `locale`='deDE' AND MD5(`RewardText`)='67e82a658b120b7fab93206845af6ec8';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ich danke Euch für Euer Kommen, $Gmüder Reisender:müde Reisende;! Erlaubt mir, mich vorzustellen - ich bin Quintis Jonespyre, Druide und bescheidener Diener von Malfurion und dem Zirkel des Cenarius. Meine Kollegen (General Shandris Feathermoon und das Protektorat - vielleicht habt Ihr schon von uns gehört) und ich möchten mit Euch über die Arbeit sprechen, die Ihr für Fandral Staghelm in Darnassus erledigt.$B$BBevor wir weitermachen, möchte ich Euch jedoch bitten, unser Gespräch für Euch zu behalten. Wenn Ihr damit kein Problem habt, dann können wir fortfahren.' WHERE `ID`=3788 AND `locale`='deDE' AND MD5(`RewardText`)='67e82a658b120b7fab93206845af6ec8';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Oh, danke, $N! Ihr habt meine Ernte gerettet! Und ich hoffe, Ihr habt einigen von diesen Defias gezeigt, dass sie hier nicht so einfach Ärger machen können.$B$BWir sind zur Zeit zwar knapp an Wachen, aber glücklicherweise haben wir $GHelden:Heldinnen; wie Euch, die uns beschützen!' WHERE `ID`=3904 AND `locale`='deDE' AND MD5(`RewardText`)='33850c95a28313a9499b0fcd0691ce62';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Wir haben nicht viel Zeit. Hört gut zu, $R. Was ich Euch zu sagen habe, ist vertraulich und nur für Eure Ohren bestimmt.' WHERE `ID`=3981 AND `locale`='deDE' AND MD5(`RewardText`)='94dbdb38a857d5d33fc10d0bff849c97';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ausgezeichnete Arbeit, $N, jedes Teilchen hiervon wird, sobald wir es geläutert haben, dabei helfen, den Teufelswald zurückzugewinnen. Hier, nehmt einige Dosen der cenarischen Pflanzensalbe und begebt Euch in den Wald. Wir dürfen nicht damit zögern, das Land der Verderbnis zu entreißen, $R!' WHERE `ID`=4105 AND `locale`='deDE' AND MD5(`RewardText`)='cac5e6ca5084efb8aa22b76b7c1daf83';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ausgezeichnete Arbeit, $N, jedes Teilchen hiervon wird, sobald wir es geläutert haben, dabei helfen, den Teufelswald zurückzugewinnen. Hier, nehmt einige Dosen der cenarischen Pflanzensalbe und begebt Euch in den Wald. Wir dürfen nicht damit zögern, das Land der Verderbnis zu entreißen, $R!' WHERE `ID`=4110 AND `locale`='deDE' AND MD5(`RewardText`)='cac5e6ca5084efb8aa22b76b7c1daf83';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Was ist denn das? Ah! Das riecht wie Dunkeleisenbier! Das Trinken verschleiert meine Sicht, aber ich sehe, dass Ihr, $Gwerter Herr:holde Dame;, ein echter Freund seid!' WHERE `ID`=4295 AND `locale`='deDE' AND MD5(`RewardText`)='f54d946339a75aeb07dead440ebbab7a';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Es hat Kariel mehrere Eurer Lebensspannen gekostet, den Buchband fertig zu stellen, den Ihr jetzt in der Hand haltet, $R. Und wozu das alles? Damit sein Jünger in der brennenden Steppe stehen und seine Forschungen missbrauchen kann, um ein unendliches Verlangen nach dem Arkanen zu befriedigen ... Verflucht sei diese elende Sucht.$B$BEuer Mangel an Mitgefühl und Eure unstillbare Gier ekeln mich an. Hinfort mit Euch!' WHERE `ID`=4482 AND `locale`='deDE' AND MD5(`RewardText`)='ac1195194df8deaf93041d720e66ed44';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ich kann Euch nicht belügen, $R. Ich brauchte das Geld! Kibler bezahlt mich sehr, sehr gut - viel besser als es das KEK je könnte.$B$BAber bitte zweifelt nicht an meiner Loyalität! Warum, glaubt Ihr, bin ich wohl hier? Um diesem verrückten Goblin ein paar Eier von exotischen Tieren oder ähnlichen Unfug zu bringen? Nein, nur jemand, der wirklich absolut dämlich ist, würde zur Blackrockspitze kommen, um nach Tieren zu suchen. Tja, ich glaube nicht, dass es allzu viele Leute dieser Art auf der Welt gibt.$B$B$B$BDas würde uns gerade noch fehlen, dass sich solche Leute noch vermehren.' WHERE `ID`=4981 AND `locale`='deDE' AND MD5(`RewardText`)='1d8551623605c30593a9afa070cfe869';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Das... ist ziemlich seltsam. Dieser Druide - ein Taurendruide noch dazu - hat Euch eine Menge wertvoller Informationen bezüglich des Ausmaßes der Seuche der Geißel anvertraut. Es überrascht mich, dass ein Tauren einem wie Euch, $R, Informationen überlassen würde, noch dazu freiwillig, wenn es stimmt, was Ihr sagt. Wir können sie aber wirklich gut gebrauchen. Vielleicht sind die Tauren ja doch nicht so weit von Cenarius abgefallen, wie Fandral meint...$B$BÄhm, wie dem auch sei, bitte nehmt dies als Zeichen des Danks des Zirkels des Cenarius.' WHERE `ID`=4986 AND `locale`='deDE' AND MD5(`RewardText`)='6fa1c0508ea874f3512378551a75767a';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Möge Eure Zielgenauigkeit unfehlbar sein und Eure Waffe Euch nie im Stich lassen, $R.$B$BAgammagans Geist ist mit Euch. Kehrt  zu mir zurück, wenn Ihr wünscht. Quetschzahn wird Euch wieder segnen, wenn der große Gott der Eber mich als würdig ansieht.' WHERE `ID`=5043 AND `locale`='deDE' AND MD5(`RewardText`)='33b0dc4fe3e851a9b7d4b4f371f8c141';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Eure Feinde sollten Euch noch mehr fürchten, $R. $B$BErzählt Quetschzahn Geschichten von Eurer Schlauheit im Kampf, wenn wir uns das nächste Mal treffen - sei es in diesem Leben oder im nächsten.' WHERE `ID`=5044 AND `locale`='deDE' AND MD5(`RewardText`)='6ae3953768157e2e3d090a28a9121121';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Unsere größten Krieger und unsere größten <schnaubt> Schamanen würden Eure Willenskraft beneiden, $R.$B$BErledigt noch mehr dieser Borstennacken, wissend, dass sie Euch nicht stoppen können!' WHERE `ID`=5045 AND `locale`='deDE' AND MD5(`RewardText`)='7516e5eb032ee8bc487881d530ea3e60';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Zieht in den Krieg, $R.' WHERE `ID`=5046 AND `locale`='deDE' AND MD5(`RewardText`)='4152da9de600c42fe3353ebe3059a94e';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ah, Ihr versteht also. <schnaubt> Meine Worte waren in Euren Ohren nicht verloren, $R. Quetschzahn mag eingekerkert sein, aber kein Käfig kann Agammagans Macht stoppen! $B$BDie Berührung des Splitters, das Gefühl... es ist schon lange her, $R.$B$BWisst Ihr, wie es ist? Wenn man seiner Macht beraubt wird?$B$BAber das ist eine andere Geschichte. Ich habe Euch Informationen versprochen. Ich habe Euch Agammagans Macht versprochen. Meine Leute haben Quetschzahn den Rücken zugewandt. Nun lasse ich Euch auf sie los.' WHERE `ID`=5052 AND `locale`='deDE' AND MD5(`RewardText`)='ac56ad5ded0df837f11f68aded072972';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Wir lernen aus den Erfahrungen unseres Lebens, $N. Ich bin sicher, dass Ihr durch die Euren nur stärker und weiser geworden seid. Ihr seid innerlich gewachsen, seitdem wir das letzte Mal miteinander gesprochen haben.$B$BNehmt dies als Erinnerung an die schwierigen Aufgaben, die Ihr als $C bewältigt habt, $R, und wisset, dass Euch mein Respekt und meine Bewunderung immer sicher sein werden.' WHERE `ID`=5057 AND `locale`='deDE' AND MD5(`RewardText`)='05565a880759f8b93aff14524337218f';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Aus den Schatten, Bruder $R, entbiete ich meine Grüße. Ich werde als Eure Koordinatorin für unseren Plan zur Sabotage der Kessel der Geißel dienen.$B$BUnser Ziel wird darin bestehen, die Zusammensetzung der Seuche, die die Kessel erzeugen, in etwas zu verwandeln, das sich negativ auf die Geißel auswirkt. Um diese Veränderung zu bewirken, müsst Ihr freien Zugriff auf jeden der vier Kessel hier in den Westlichen Pestländern sicherstellen.$B$BDie Zeit ist gekommen, dass Ihr den Sturm gegen die Geißel anführt.' WHERE `ID`=5228 AND `locale`='deDE' AND MD5(`RewardText`)='8bfdb01c950d84dd339c0a0a1cfab69b';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Gut gemacht, $R. Ihr habt bewiesen, dass Ihr, auch wenn Ihr anderen gegenüber tolerant seid, vor nichts Halt machen werdet, um die Diener von Kel''Thuzad zu vernichten.' WHERE `ID`=5243 AND `locale`='deDE' AND MD5(`RewardText`)='777b71f9b06c1c40c82245501f1e8236';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Gut gemacht, $R. Jetzt muss ich mir mein Erbe sichern...' WHERE `ID`=5341 AND `locale`='deDE' AND MD5(`RewardText`)='851055968c6b7f27091f7cdd27b9bb56';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Glückwunsch, $N... ich bin erfreut, Euch mit einer Ehrenmarke der Argentumdämmerung zu belohnen!$B$BAuf solche Art eine Ehrenmarke zu erhalten, zeigt, dass Ihr ein wahrer Held der Sache des Guten seid. Wir schätzen alle Bemühungen, die gegen die Geißel aufgebracht werden, aber einen ihrer Anführer auszuschalten, bedeutet wahrlich, ihnen eine vernichtende Niederlage beizubringen!$B$BFür die Dämmerung, $Gmein Bruder:meine Schwester;.' WHERE `ID`=5404 AND `locale`='deDE' AND MD5(`RewardText`)='43d09ebfc7432745b914f61dfc785136';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Glückwunsch, $N... ich bin erfreut, Euch mit einer Ehrenmarke der Argentumdämmerung zu belohnen!$B$BAuf solche Art eine Ehrenmarke zu erhalten, zeigt, dass Ihr ein wahrer Held der Sache des Guten seid. Wir schätzen alle Bemühungen, die gegen die Geißel aufgebracht werden, aber einen ihrer Anführer auszuschalten, bedeutet wahrlich, ihnen eine vernichtende Niederlage beizubringen!$B$BFür die Dämmerung, $Gmein Bruder:meine Schwester;.' WHERE `ID`=5406 AND `locale`='deDE' AND MD5(`RewardText`)='43d09ebfc7432745b914f61dfc785136';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Glückwunsch, $N... ich bin erfreut, Euch mit einer Ehrenmarke der Argentumdämmerung zu belohnen!$B$BAuf solche Art eine Ehrenmarke zu erhalten, zeigt, dass Ihr ein wahrer Held der Sache des Guten seid. Wir schätzen alle Bemühungen, die gegen die Geißel aufgebracht werden, aber einen ihrer Anführer auszuschalten, bedeutet wahrlich, ihnen eine vernichtende Niederlage beizubringen!$B$BFür die Dämmerung, $Gmein Bruder:meine Schwester;.' WHERE `ID`=5508 AND `locale`='deDE' AND MD5(`RewardText`)='43d09ebfc7432745b914f61dfc785136';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ihr seid ein leuchtendes Beispiel des Anstands, $R! Es ist lange her, dass ich das Blut von Helden in meinen Adern gefühlt habe. Eure Taten der Tapferkeit sind wahrlich erhebend!' WHERE `ID`=5543 AND `locale`='deDE' AND MD5(`RewardText`)='17227f0b98dbdb8958d3587f0a7f3ad0';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ich war Tirions engste Beraterin, als er noch Lord von Mardenholde war. Ich habe mich offen gegen das Urteil des Ordens der Silberhand ausgesprochen und wurde wegen meiner Unverschämtheit verbannt.$B$BEr hat in seinem Leben viel Herzeleid und viele Enttäuschungen erlitten, $R. Seid Ihr bereit, das den Fordrings angetane Unrecht wieder gut zu machen?' WHERE `ID`=5861 AND `locale`='deDE' AND MD5(`RewardText`)='195232e955b3130b38f7264c9f1ed26f';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ausgezeichnete Arbeit, $N, jedes Teilchen hiervon wird, sobald wir es geläutert haben, dabei helfen, den Teufelswald zurückzugewinnen. Hier, nehmt einige Dosen der cenarischen Pflanzensalbe und begebt Euch in den Wald. Wir dürfen nicht damit zögern, das Land der Verderbnis zu entreißen, $R!' WHERE `ID`=5884 AND `locale`='deDE' AND MD5(`RewardText`)='cac5e6ca5084efb8aa22b76b7c1daf83';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ausgezeichnete Arbeit, $N, jedes Teilchen hiervon wird, sobald wir es geläutert haben, dabei helfen, den Teufelswald zurückzugewinnen. Hier, nehmt einige Dosen der cenarischen Pflanzensalbe und begebt Euch in den Wald. Wir dürfen nicht damit zögern, das Land der Verderbnis zu entreißen, $R!' WHERE `ID`=5889 AND `locale`='deDE' AND MD5(`RewardText`)='cac5e6ca5084efb8aa22b76b7c1daf83';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Willkommen, $N. Ich spüre, dass Eure erste Begegnung mit dem großen Bärengeist genauso verlief wie bei allen Druiden, wenn sie die ersten Schritte auf dem Pfad der Klaue tun... etwas verwirrend, aber sehr eindrucksvoll. Ich weiß, dass es für mich damals auch so war.$B$BDer große Bärengeist ist schon so lange ein Teil von Azeroth wie Azeroth in den Himmeln existiert. Wir $R hören solchen Geistern genau zu und wir alle profitieren von deren Absichten. Nun ist es an der Zeit für Eure erste Prüfung dieser Absichten. Hört mir gut zu...' WHERE `ID`=5932 AND `locale`='deDE' AND MD5(`RewardText`)='093ed86c095bf6e6dfddb0ae63af207c';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ihr habt bei der Heilung der kranken Gazellen des Brachlands wahre Wunder gewirkt. Sie waren das arglose Opfer einer größeren Besudelung und Verderbnis geworden, die sich über das Land ausbreitete. Ihr $R brennt darauf, die Wege des Cenarius zu verstehen. Ihr habt, wie Eure Ältesten in Thunder Bluff, den Beweis angetreten, dass die Notwendigkeit des Gleichgewichts künstliche Barrieren zwischen den Völkern überwindet.$B$B$N, Ihr habt Euren Wert als Freund der Natur und des Zirkels unter Beweis gestellt - nehmt dies als Symbol dafür.' WHERE `ID`=6129 AND `locale`='deDE' AND MD5(`RewardText`)='678f203b986a818b226bd75bafee6791';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ah, ein neues Bündel Bälge. Ich werde mich sofort damit an die Arbeit machen!$B$BDanke, $G Bruder:Schwester;. Ihr habt mir einen großen Dienst erwiesen. Hier habt Ihr ein paar Münzen für eure Zeit und Reisekosten.' WHERE `ID`=6362 AND `locale`='deDE' AND MD5(`RewardText`)='477abfa8b7d082e3540b34580c409257';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Es gibt nur einen Weg in den Hort des Großdrachen, $R.$B$BWisst Ihr, nur die Stärksten des schwarzen Drachenschwarms dürfen den Hort der Brutmutter betreten. Es müssen viele Prüfungen überwunden werden und der Schlüssel, mit dem man hineingelangt, wurde von General Drakkisath persönlich zeremoniell verzaubert!$B$BDa Ihr nicht zu den schwarzen Großdrachen gehört, werdet Ihr wohl auf einige Schwierigkeiten stoßen, wenn Ihr Einlass verlangt.' WHERE `ID`=6567 AND `locale`='deDE' AND MD5(`RewardText`)='cac38b5928eb8b8f696550ae842dee8a';
UPDATE `quest_offer_reward_locale` SET `RewardText`='<Myranda hält die Notiz, schweigt eine Weile, dann lächelt sie.>$B$BWie geht es ihm? Rexxar, meine ich. Oh, bitte, schaut nicht so überrascht drein. Der Brief besteht absichtlich nur aus einem leeren Blatt. Er trägt die Absichten und Gedanken des Schreibers. Angesichts des Inhalts ist es kein Wunder, dass Rexxar so verfahren ist. Stellt Euch vor, man hätte Euch gefangen oder getötet und diese Informationen entdeckt!$B$BAch, wie dem auch sei! Myranda wird Euch helfen, $R. Ich schulde dem Kriegshäuptling noch einen oder zwei Gefallen.' WHERE `ID`=6568 AND `locale`='deDE' AND MD5(`RewardText`)='955002857c68c039a826d2e5bd6e2267';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Lasst Myranda mal sehen, $R.$B$BAh ja, ausgezeichnet.$B$BAus diesen Reagenzien wird Myranda ein Medaillon für Euch fertigen, mit dem Ihr eine Illusion erzeugen könnt, die den Torhüter des schwarzen Drachenschwarms täuschen wird.' WHERE `ID`=6569 AND `locale`='deDE' AND MD5(`RewardText`)='cc453fd48719cedbe7963314fa3fa59e';
UPDATE `quest_offer_reward_locale` SET `RewardText`='<Dirge spuckt Leder aus.>$B$BPfft...$B$B<Dirge hustet laut.>$B$BWas? Ihr müsst wissen, dass Leder erstaunlich reich an Proteinen und arm an Kohlehydraten ist, $R.' WHERE `ID`=6612 AND `locale`='deDE' AND MD5(`RewardText`)='2c8f1e9f7f8842a421309b6acdf1cde0';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Das ist es, $R! Das ist es! Jetzt kann ich die große Aufgabe der Vereinigung der Stämme angehen. Seid bedankt.$B$BNehmt bitte dies für Eure Bemühungen. Ich hoffe, dass über unserem nächsten Treffen ein glücklicherer Stern stehen wird.' WHERE `ID`=7067 AND `locale`='deDE' AND MD5(`RewardText`)='ae5b6d544b3cc5e3200e8eed0c446d38';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Excellent! Ich bin ein Tauren, der sein Wort hält, $R. Die Pfeile gehören Euch.' WHERE `ID`=7341 AND `locale`='deDE' AND MD5(`RewardText`)='c372f9ae24fb39a25db7c481c1bbc8cf';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Achtet darauf, Euch während der Verzauberung nicht selbst weh zu tun, $R.' WHERE `ID`=7484 AND `locale`='deDE' AND MD5(`RewardText`)='6f2cf55f1fe51cd3b55974770ef5b45d';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Gut gemacht, $R. Solltet Ihr noch weitere Folianten finden, zögert nicht sie uns zurückzubringen.$B$BNatürlich erhaltet Ihr eine Belohnung, wenn Ihr uns einen vermissten Folianten zurückbringt. Mit der Zeit ändern wir die Belohnungen oder fügen neue hinzu.' WHERE `ID`=7498 AND `locale`='deDE' AND MD5(`RewardText`)='a807aa75d986779e0139562dd17e06e9';
