UPDATE `quest_offer_reward_locale` SET `RewardText`='Ja, das wird gehen. Während der vor Euch liegenden Prüfungen werdet Ihr mehr als einmal Eure Opferbereitschaft beweisen müssen. Ich bin froh das Ihr dazu bereit seid. Opferbereitschaft ist eine der grundlegensten Eigenschaften die man besitzen muss, um den Pflichten eines $C nachkommen zu können... ich denke, was das betrifft, muss ich Euch keine Lektion mehr erteilen. Am Ende, ist dieser Weihrauchschwenker das Werkzeug, mit dem Ihr Gerechtigkeit walten lassen werdet, unter all den gequälten Seelen, in den für uns verlorenen Ländereien.' WHERE `ID`=7639 AND `locale`='deDE' AND MD5(`RewardText`)='fe3030c3bc23deeaed82dc58c5e490d1';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Gut gemacht, $Gmein Sohn:meine Tochter;.$B$B< Lydros reißt eine Seite aus dem Buch> $B$BIch bin sicher Ihr habt eine Verwendung für dieses Rezept.' WHERE `ID`=7649 AND `locale`='deDE' AND MD5(`RewardText`)='71c6245a5974d213095654b9761df928';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Gut gemacht, $Gmein Sohn:meine Tochter;.$B$B< Lydros reißt eine Seite aus dem Buch> $B$BIch bin sicher Ihr habt eine Verwendung für dieses Rezept.' WHERE `ID`=7650 AND `locale`='deDE' AND MD5(`RewardText`)='71c6245a5974d213095654b9761df928';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Isch hätt'' nie gedacht, dasch ich diiieschem Ganoven nochmal in die Augen schauen würde!$B$BOhne den Rescht voo'' ihm sieht er doch viiel bescha aus, findet Ihr nisch?$B$BHier''s Eure Belohnung *hicks*, $R.' WHERE `ID`=7701 AND `locale`='deDE' AND MD5(`RewardText`)='7f6f697509822ef4358251bc94e9e2ff';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Wow... Ihr SEID $Gde\\'' wahre König:di\\'' wahre Königin;! Ich nie gedacht, dass ich je wiedersehen diese Stulpen in meinem Leben!  Es aussehen als ob sie kein Mojo mehr haben... vielleicht de'' gruselige Elf hat sich an Stulpen versucht und sie kaputt gemacht.$B$B Guckt - dieses Zeichen auf de'' Stulpen ist ein sehr sehr sehr altes Zeit Symbol. Älter als Gordok, sagen sie. Nun, als Captain von de'' Gordok, bekommen eines immer und immer wieder beigebracht - wie man machen Zeichen wieder lebendig, um geben den Stulpen die Kraft zurück!$B$BIch werde es für Euch tun, $GKönig:Königin;! Hier, nehmen Stulpen und herrschen AUF EWIG!' WHERE `ID`=7703 AND `locale`='deDE' AND MD5(`RewardText`)='f8b64e4ba2c7426aa2fb0f3abadb22a2';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ah, gute Arbeit $R. Die Revantusk danken Euch für Euren Beitrag.' WHERE `ID`=7828 AND `locale`='deDE' AND MD5(`RewardText`)='dfdb48a5b54c2c794e7741cab860c681';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Mein geliebter Bruder, wie sehr ich dich vermissen werde...$B$BDanke für Eure Hilfe, $N. Ihr seid $Gein wahrer Held:eine wahre Heldin; für mich.' WHERE `ID`=7849 AND `locale`='deDE' AND MD5(`RewardText`)='01e2d03d7d8ac83f416d865c735bfee6';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Unsere Überzeugungen unterscheiden sich zwar, aber unsere Gründe sind gerechtfertigt. Bezwingt unsere Feinde, $Gedler:edle; $C.' WHERE `ID`=8047 AND `locale`='deDE' AND MD5(`RewardText`)='94242ef012eb69513338ea15c7fce838';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ihr habt vollbracht, was nur wenige hätten tun können. Ihr habt die Diener Hakkars in die Knie gezwungen. Ihr habt ihnen gezeigt, zu was ein Freidenker fähig ist. Ihr habt uns bewiesen, dass auch ein Ungläubiger in diesem Stamm anerkannt werden kann. Ihr seid mehr als mächtig. Ihr SEID die Macht.$B$BNehmt die Brustplatte, $N. Zerstört diejenigen, die sich Euch in den Weg stellen.' WHERE `ID`=8055 AND `locale`='deDE' AND MD5(`RewardText`)='7878ae9c9c9248f4b98b2af3cff4e3fe';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Beeindruckend... Ihr habt das erforderliche Symbol der Macht erfolgreich beschafft, $N. Eure vollbrachten Taten in Zul''Gurub im Namen der Zandalar sind sagenhaft; von nun an werdet Ihr in unserem Stamm angesehen werden. Hier ist Eure Tunika, $Gmächtiger:mächtige; $C!' WHERE `ID`=8065 AND `locale`='deDE' AND MD5(`RewardText`)='6ac38e82ac0995a5dc4c5bd3adebd8e3';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Eure Reise hat gerade erst begonnen, $Gjunger:junge; $C. Vielleicht werdet Ihr eines Tages selbst den Maelstrom besuchen und in das Herz der Welt blicken.$B$BIch wünsche Euch innere Stärke und Tapferkeit, $Gmein Freund:meine Freundin;!' WHERE `ID`=8148 AND `locale`='deDE' AND MD5(`RewardText`)='00e4ba9b11c0610a8c96518348070580';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Das ist ein Sieg, den es auszukosten gilt, $N! Der Untergang Schattensichels sollte den schwachen Halt, der die spirituelle Ebene zusammenhält, wieder herstellen.$B$BIhr habt die an Euch gestellten Anforderungen bei weitem übertroffen, obwohl Ihr nichts von einer Belohnung oder Entschädigung gewusst habt. Ihr seid wahrhaftig ein ehrenhafter $C, $Gmein Freund:meine Liebe;.$B$BIch weiß, dass der Erhalt der spirituellen Ebene Lohn genug sein sollte, aber bitte - akzeptiert dieses bescheidene Geschenk als meinen persönlichen Dank.' WHERE `ID`=8258 AND `locale`='deDE' AND MD5(`RewardText`)='33ba750cca239f489e2aac6ca5fd9f2e';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Fantastisch! Geht nicht zu weit weg, $N. Vielleicht haben wir noch die eine oder andere Aufgabe für Euch.' WHERE `ID`=8310 AND `locale`='deDE' AND MD5(`RewardText`)='928873b107dd6fb66cc6701ed118febf';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Seit Ihr Burg Cenarius betreten habt, war mir klar, dass Ihr $Gein mächtiger:eine mächtige:c; $C seid. Macht weiter so!' WHERE `ID`=8348 AND `locale`='deDE' AND MD5(`RewardText`)='d83dd46468e6e6a9305261e7bac61c52';
UPDATE `quest_offer_reward_locale` SET `RewardText`='$N! Ihr seid $G der Mann:die Frau;!!!$B$BIch bin mir sicher, dass das Kartell mir jetzt wieder freundlicher gestimmt sein wird, nun da Ihr mir mit dem Südmeerabschaum geholfen habt. Lasst mal sehen, womit könnte ich Euch belohnen? Und wenn ich Euch ein paar Münzen gäbe, damit Ihr Euch hier etwas aussucht? Na, seid Ihr damit einverstanden?' WHERE `ID`=8366 AND `locale`='deDE' AND MD5(`RewardText`)='c82c8e2bd7c7e688673c39a763f4248d';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ausgezeichnete Arbeit, $N. Ihr sein $Gein wertvoller Verbündeter:eine wertvolle Verbündete;.' WHERE `ID`=8539 AND `locale`='deDE' AND MD5(`RewardText`)='b0f92e8fcf6ba66c43f2c081f489f541';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ihr habt meine Schärpe wiedergefunden? Dann... müsst Ihr Mok''rash den Meeresriesen getötet haben! Hurra!$B$BIch freue mich, dass dieser räudige Schurke tot ist - Mok''rash war einer von drei Meeresriesen, die meine Schiffe zerstört und meine Crew umgebracht haben.$B$BDrei Mal.$B$BIhr seid $Gein:eine:c; $C von Ehre, $N.' WHERE `ID`=8552 AND `locale`='deDE' AND MD5(`RewardText`)='4551fe64c0d1697561d5c9a480fc782e';
UPDATE `quest_offer_reward_locale` SET `RewardText`='<Narain studiert eifrig das Geschriebene.>$B$BAußerordentlich, $R! Was ist das? Ich kann kein Wort Drachisch lesen.' WHERE `ID`=8575 AND `locale`='deDE' AND MD5(`RewardText`)='f5d22926507a06883ffa052228a9019e';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ich kann es nicht glauben, dass er mich gefunden hat. Dabei war ich mir so sicher, dass er meine Spur verloren hat, als ich in der Scherbenwelt war. Ich gehe nicht zu ihm zurück, $R! Niemals und nie wieder! Ich habe genug davon, sein ''Bester Freund für immer'' zu sein, oder sollte ich besser sagen, sein Vollzeitsklave.' WHERE `ID`=8577 AND `locale`='deDE' AND MD5(`RewardText`)='2af3b0fd351ea5b452f4fe556614ad79';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ravenholdt dankt Euch, $N! Sucht Euch was aus!' WHERE `ID`=9023 AND `locale`='deDE' AND MD5(`RewardText`)='4413137f7bce33531c6346360ead8ad9';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ihr habt''s verdient, $N. Beschwert Euch also nicht. Erfüllt Euren Auftrag oder lasst es bleiben.' WHERE `ID`=9142 AND `locale`='deDE' AND MD5(`RewardText`)='5f3c5b7650c938d5aa3aa084b110d032';
UPDATE `quest_offer_reward_locale` SET `RewardText`='<Mataus steckt das Gold in seine Taschen.>$B$BViel Spaß mit den Reparaturkoten, $R. Naxxramas geht recht ''lieblos'' mit Außenstehenden um.' WHERE `ID`=9211 AND `locale`='deDE' AND MD5(`RewardText`)='9c4ecdb230575296b605797d3babf0a6';
UPDATE `quest_request_items_locale` SET `CompletionText`='Vielleicht habe ich mich nicht klar genug ausgedrückt, $GKandidat:Kandidatin;. Um Euren Wert als $GDiener:Dienerin; der Volksmiliz und $GDiener:Dienerin; des Lichtes zu beweisen, müsst Ihr 15 Fallensteller der Defias und 15 Schmuggler der Defias erschlagen und zu mir zurückkehren, sobald Ihr dies getan habt.' WHERE `ID`=12 AND `locale`='deDE' AND MD5(`CompletionText`)='a043bbb0933a220c5cf5451973e5a387';
UPDATE `quest_request_items_locale` SET `CompletionText`='Was bringt Ihr mir da, $R?' WHERE `ID`=169 AND `locale`='deDE' AND MD5(`CompletionText`)='3d7f00d72c64fba2da204c5172232294';
UPDATE `quest_request_items_locale` SET `CompletionText`='Was macht Ihr denn hier, $N? Ihr solltet durch das Unterholz kriechen und versuchen, 10 Schattentatzenpanther zu töten! Ich dachte, Ihr hieltet Euch für $Geinen Großwildjäger:eine Großwildjägerin;?' WHERE `ID`=192 AND `locale`='deDE' AND MD5(`CompletionText`)='95de9ed68a9559b5e794a13cca221520';
UPDATE `quest_request_items_locale` SET `CompletionText`='Ja? Was wollt Ihr? Oh, Vorräte von den Goblins. Seltsam, dass ein $R das Paket abliefert, normalerweise schicken sie einen ihrer eigenen Leute. Na, egal. Ihr habt die doch wohl hoffentlich nicht angefasst? Gut, gut... Wir wollen ja nicht, dass unseren Minen irgendwas passiert, oh nein.' WHERE `ID`=198 AND `locale`='deDE' AND MD5(`CompletionText`)='ef4f373695c06a093c4e86010d470206';
UPDATE `quest_request_items_locale` SET `CompletionText`='Ah, wie ich sehe, seid Ihr zurück, $Galter Junge:mein Mädchen;. Auch mich hat König Bangalash schon oft dazu gebracht, dass ich auf Händen und Füßen ins Lager zurückgekrochen kam. Haltet durch.' WHERE `ID`=208 AND `locale`='deDE' AND MD5(`CompletionText`)='6316da13a26763a8fdb6797986b3b9c8';
UPDATE `quest_request_items_locale` SET `CompletionText`='Wir brauchen mehr Zeit, $R. Ihr habt den Befehl, 10 Stonesplitter-Schädelhauer und 10 Stonesplitter-Seher zu töten. Setzt den Feind unter Druck, bis wir Verstärkung erhalten. Jetzt ist nicht die Zeit für Müßiggang.' WHERE `ID`=237 AND `locale`='deDE' AND MD5(`CompletionText`)='e45c1cd463f9ae24d8c45db47e7fadc3';
UPDATE `quest_request_items_locale` SET `CompletionText`='Kein Glück gehabt? Macht Euch nix draus, $Ner…$B$BNicht jeder kann so gut sein wie ich.' WHERE `ID`=257 AND `locale`='deDE' AND MD5(`CompletionText`)='c26b10646192244e64507a75dd8203c0';
UPDATE `quest_request_items_locale` SET `CompletionText`='Es ist ganz normal, dass man sich selbst bemitleidet, wenn man sich vor jemandem blamiert, der so viel jünger ist als man selbst. Macht Euch nichts draus, $Nah…$B$BWie? Hab ich mir Euren Namen falsch gemerkt?' WHERE `ID`=258 AND `locale`='deDE' AND MD5(`CompletionText`)='c9d4c808fae61c328afe2171f873e91c';
UPDATE `quest_request_items_locale` SET `CompletionText`='Ruht Euch erst einmal aus, $GBruder:Schwester;. Ich sehe Euch an, dass Ihr weit gereist seid und eine schwere Bürde tragt. Könnt Ihr mir erzählen, was diesen dunklen Schatten über Euch wirft?' WHERE `ID`=269 AND `locale`='deDE' AND MD5(`CompletionText`)='ba625fac4537ddc8e0bb4de03c99b3dd';
UPDATE `quest_request_items_locale` SET `CompletionText`='Eure Aufgabe steht noch an, $Gjunger:junge; $C.' WHERE `ID`=276 AND `locale`='deDE' AND MD5(`CompletionText`)='a686ba6a409d2fb1baedab1f2f791888';
UPDATE `quest_request_items_locale` SET `CompletionText`='Ich kann manchmal in meinen Träumen das unselige Stöhnen meiner Brüder hören! Bitte, $Gguter Herr:gute Dame;, befreit sie von ihren Fesseln und lasst ihre Schreie verstummen.' WHERE `ID`=289 AND `locale`='deDE' AND MD5(`CompletionText`)='deec03fd04069379c839f75068648f48';
UPDATE `quest_request_items_locale` SET `CompletionText`='Seid gegrüßt und fühlt Euch willkommen, $Gedler Herr:edle Dame;. Habt Ihr schon einmal einen unserer ausgezeichneten Weine versucht?' WHERE `ID`=332 AND `locale`='deDE' AND MD5(`CompletionText`)='26dc7416b3baf9e9629587fddfca8d10';
UPDATE `quest_request_items_locale` SET `CompletionText`='Ihr seid den ganzen weiten Weg von Stormwind gekommen? Ich habe gehört, es wird da unten in den Menschenlanden dank herumlaufender Briganten und Orcs etwas brenzlig. An einem solchen Ort kann $Gein:eine; $C sich perfekt beweisen!' WHERE `ID`=353 AND `locale`='deDE' AND MD5(`CompletionText`)='e1934798aebd097228ef018dab519768';
UPDATE `quest_request_items_locale` SET `CompletionText`='Ja, $Gwerter Herr:werte Dame;? Was gibt es denn?' WHERE `ID`=511 AND `locale`='deDE' AND MD5(`CompletionText`)='d4a204142f3d8cce778083682a0b3a45';
UPDATE `quest_request_items_locale` SET `CompletionText`='Na, wie läufts denn, $R?' WHERE `ID`=647 AND `locale`='deDE' AND MD5(`CompletionText`)='8b1db8c3134be0e35b73f0cd2a164757';
UPDATE `quest_request_items_locale` SET `CompletionText`='Ihr seid also $N, $Gder:die; $C? Neuigkeiten über Eure Hilfe gegenüber der Allianz sind weit gereist, wisst Ihr?$B$BIn welcher Angelegenheit tretet Ihr heute vor mich?' WHERE `ID`=683 AND `locale`='deDE' AND MD5(`CompletionText`)='aa78cb19f3d0ddebc8ff21c91353c0a1';
UPDATE `quest_request_items_locale` SET `CompletionText`='Ah, ja. Wieder $Gein Reisender:eine Reisende;, $Gder:die; nach etwas von den Zwergen sucht.$B$B$GSire:Madame;, es tut mir wirklich Leid, aber ich habe jetzt keine Zeit, sinnlose Fragen zu beantworten.' WHERE `ID`=724 AND `locale`='deDE' AND MD5(`CompletionText`)='324030229e7e24c17fc4d9cde4b9c802';
UPDATE `quest_request_items_locale` SET `CompletionText`='Ah, Ihr seid $Gein:eine; besonders $Geifriger:eifrige; $C, wie ich sehe. Seid Ihr hier, um aus meiner Sammlung zu lernen? Gut!$B$BAber seid gewarnt: Genau wie Wissen den Starken Macht verleiht... treibt es die Schwachen in den Wahnsinn.' WHERE `ID`=728 AND `locale`='deDE' AND MD5(`CompletionText`)='b50870339d984b88d071aaad79ebfda6';
UPDATE `quest_request_items_locale` SET `CompletionText`='Was kann ich für Euch tun, $R?' WHERE `ID`=741 AND `locale`='deDE' AND MD5(`CompletionText`)='4cffa03215f45cfc081ab3a93f45da0a';
UPDATE `quest_request_items_locale` SET `CompletionText`='Meine ergebensten Grüße, $C. Womit kann ich $Gmeinem Bruder:meiner Schwester; heute behilflich sein?' WHERE `ID`=829 AND `locale`='deDE' AND MD5(`CompletionText`)='4c91dc96ce48f46513c9a5be28d0cabd';
UPDATE `quest_request_items_locale` SET `CompletionText`='Fürchtet Euch nicht vor den Gewässern, $R.' WHERE `ID`=873 AND `locale`='deDE' AND MD5(`CompletionText`)='1309692dedf924a54bb613a2e89090db';
UPDATE `quest_request_items_locale` SET `CompletionText`='Mehr Informationen <schnaubt> für die Horde gibt es, wenn Ihr die Weisen der Borstennacken getötet habt, $R.  Nicht einen Moment früher! Quetschzahn ist kein Narr.' WHERE `ID`=878 AND `locale`='deDE' AND MD5(`CompletionText`)='68bdcb101bd64b06de0594aec2fbbfa2';
UPDATE `quest_request_items_locale` SET `CompletionText`='Wie läuft Eure Jagd, $R? $B$BThork glaubt, dass er die Wahrheit darüber kennt, wer die Überfälle auf sein Volk angeführt hat,  aber er wird bald erfahren, wie sehr er sich irrt, wenn Ihr erst Erfolg gehabt habt.$B$BMein Tod ist unabwendbar, aber Ihr habt meinen Feinden große Schmerzen bereitet, sodass Quetschzahn nichts bereut.' WHERE `ID`=879 AND `locale`='deDE' AND MD5(`CompletionText`)='942fb96dee92f7a2c4d48ad39ffee04e';
UPDATE `quest_request_items_locale` SET `CompletionText`='Hallo, $Gwerter Herr:werte Dame;.$B$BDarf ich Euch ein paar meiner Folianten zeigen?' WHERE `ID`=968 AND `locale`='deDE' AND MD5(`CompletionText`)='85b320341862d64de215d36d08c7c945';
UPDATE `quest_request_items_locale` SET `CompletionText`='Die Schildwachen hier in Ashenvale tun was sie können, aber solchen wie Euch, $R, verdanken wir den Boden, den wir wieder zurückgewonnen haben.' WHERE `ID`=1046 AND `locale`='deDE' AND MD5(`CompletionText`)='09994214f2f65ce62c0e918c8169cc01';
UPDATE `quest_request_items_locale` SET `CompletionText`='Habt Ihr dat Sapta, $GBruda:Schwesta;?$B$BIch kenne noch jemanden, der Probleme hatte, nachdem er den verderbten Wassergeist besiegt hadde - hat wohl zu lange gewartet und kam für seinen Jeschmack zu schnell aus der Geisterwelt. Würde nich gern seh''n, dass dat noch wem passiert, also werde ich hier noch ''ne Weile wart''n und sichergehen, dat sonst keiner meine Hilfe braucht.' WHERE `ID`=1103 AND `locale`='deDE' AND MD5(`CompletionText`)='6e3fef7339aa629d9c018ac677d304bb';
UPDATE `quest_request_items_locale` SET `CompletionText`='Hallo, hallo. Und was führt einen so edlen Eurer Art nach Booty Bay, $R?' WHERE `ID`=1118 AND `locale`='deDE' AND MD5(`CompletionText`)='dcefa4f67f34472f67edd0870cffedfc';
