UPDATE `quest_request_items_locale` SET `CompletionText`='Da Ihr offensichtlich kein Magier seid, frage ich mich, ob ich Euch überhaupt trauen kann. Ich kann die Macht des Arkanen an Euch riechen, aber Ihr scheint Euch dem Gestank der Verderbnis entzogen zu haben, der Eurer Art so bereitwillig anhängt.$B$BJa, $Gein:eine; $C ... $Gein:eine; $C ist gekommen, um mich um Hilfe zu bitten.$B$BNun, was kann ich für Euch tun, $N?' WHERE `ID`=1799 AND `locale`='deDE' AND MD5(`CompletionText`)='e7a818e84a9e47cffd4b97e5c25ae491';
UPDATE `quest_request_items_locale` SET `CompletionText`='Wie vermag ich Euch dienlich zu sein, $Gjunger Freund:junge Freundin;? Seid Ihr hier, um Euch im Gasthaus auszuruhen? Benötigt Ihr einen Ruhestein?' WHERE `ID`=2159 AND `locale`='deDE' AND MD5(`CompletionText`)='4cd08453d22e4836333c30bf1ed6ed32';
UPDATE `quest_request_items_locale` SET `CompletionText`='Ihr habt es Euch überlegt, ja? Ihr seid $Gein schlauer:eine schlaue; $C, wenn Ihr dieses Angebot annehmt - Ihr und ich werden beide bekommen, was wir wollen, und ''Droffers und Sohn Bergungen'' werden denken, dass sie bekommen, was sie wollen.' WHERE `ID`=2338 AND `locale`='deDE' AND MD5(`CompletionText`)='a2c1596077b97a351f392c597e715713';
UPDATE `quest_request_items_locale` SET `CompletionText`='Habt Ihr Grimmeiche schon gefunden, $R?' WHERE `ID`=2499 AND `locale`='deDE' AND MD5(`CompletionText`)='ab1d2c42e0d7d36fce3921c0184cf4a0';
