UPDATE `quest_request_items_locale` SET `CompletionText`='Zeigt mir, dass Ihr es ernst meint, $R.' WHERE `ID`=2752 AND `locale`='deDE' AND MD5(`CompletionText`)='4c10a2bb1fc3131472a248e052282ca5';
UPDATE `quest_request_items_locale` SET `CompletionText`='Seid gegrüßt, $R... Eurem Aussehen nach seid Ihr ein Lederer wie ich. Seid Ihr hier, um etwas von meinem Geschick zu erlangen, oder habt Ihr vielleicht andere Geschäfte mit mir zu besprechen?' WHERE `ID`=2853 AND `locale`='deDE' AND MD5(`CompletionText`)='f80d2853d28b42d535f8f6d590f581c6';
