UPDATE `quest_request_items_locale` SET `CompletionText`='Ja, kann ich Euch helfen?$B$BMoment, Ihr seid doch $Gder:die; $C, $Gder:die; General Feathermoon und Latro mit der Bedrohung durch die Naga geholfen hat, nicht? Ich bin Vestia, Latros - ähm, natürlich Latronicus’ Frau. Es ist mir eine Freude, Eure Bekanntschaft zu machen!$B$BDoch entschuldigt, Ihr seid sicher geschäftlich hier. Habt Ihr etwas für mich - von ihm vielleicht?' WHERE `ID`=2871 AND `locale`='deDE' AND MD5(`CompletionText`)='dbedd4c0128ab9711027cfa96696386d';
UPDATE `quest_request_items_locale` SET `CompletionText`='Hallo, $Gedler:edle; $C. Der Tag war lang und nicht ein einziges Experiment ist geglückt... Ich hoffe, Ihr bringt mir gute Neuigkeiten.' WHERE `ID`=2933 AND `locale`='deDE' AND MD5(`CompletionText`)='75827b0c13025c023bea994adb52f9c1';
