UPDATE `quest_request_items_locale` SET `CompletionText`='$R, noch einer zur Verstärkung unserer Reihen. Mir soll''s recht sein.$B$BIhr tut Euch wahrscheinlich schwer damit, eine gute Waffe wie beispielsweise eine Axt zu werfen, aber ein Speer ist genauso gut wie jede andere Waffe.$B$BWillkommen im Tal der Prüfungen.' WHERE `ID`=3065 AND `locale`='deDE' AND MD5(`CompletionText`)='0f5ae523d110215e7e437ca56a635951';
UPDATE `quest_request_items_locale` SET `CompletionText`='Ich heiße Euch willkommen, $GBruder:Schwester;. Ich wusste, Ihr würdet kommen. Es war nur eine Frage der Zeit.$B$BWas ich sagte, hat Euch interessiert, nicht wahr? Es schlug eine Saite an... etwas in Euch wusste, dass meine Worte wahr waren. Gut.$B$BDoch wisset dies: Ich bin kein Verräter an Sylvanas. Wenn überhaupt, würde sie meine Worte zu schätzen wissen, wenn man bedenkt, dass es ihre eigenen Überzeugungen waren, die die Verlassenen in die Situation gebracht haben, in der sie sich jetzt befinden.' WHERE `ID`=3099 AND `locale`='deDE' AND MD5(`CompletionText`)='668599c3fc9e7e6641d84fab5930b47a';
UPDATE `quest_request_items_locale` SET `CompletionText`='Ah, nun, ein weiteres Memorandum von einem $R im Einsatz... ist das nicht kurios.$B$BNein, nein, ich mache mich nicht über Euch lustig, Kleiner. Eure Zähigkeit verdient Respekt, so viel ist sicher. Ich wäre genauso verärgert, wenn Ironforge von Dunkeleisenzwergen eingenommen würde, glaubt also nicht, dass ich kein Mitgefühl verspüre für Eure Not...' WHERE `ID`=3112 AND `locale`='deDE' AND MD5(`CompletionText`)='0a241efe8ed58d4324fbb5c7206fe348';
UPDATE `quest_request_items_locale` SET `CompletionText`='Ja, wie war das, $R? Sprecht lauter, bitte. Nach einigen Bieren höre ich nicht mehr so gut.' WHERE `ID`=3114 AND `locale`='deDE' AND MD5(`CompletionText`)='1ad61df22be3c6cba698c641e3fdf373';
UPDATE `quest_request_items_locale` SET `CompletionText`='Ah, guten Tag, $Gjunger Herr:junge Dame;. Hättet Ihr gern eine Führung durch das Museum?' WHERE `ID`=3182 AND `locale`='deDE' AND MD5(`CompletionText`)='68f91d33a93d24028afad7cb0020189c';
UPDATE `quest_request_items_locale` SET `CompletionText`='Liebe Güte $N, diese Stadt ist für Leute wie mich nicht sehr geeignet. Hier gibt es ja ebenso viele widerliche Kreaturen wie in $Reregan vor diesem Unfall!$B$BHabt Ihr meine Habseligkeiten? Falls nicht... oje, wer weiß, was die Trolle damit angestellt haben...' WHERE `ID`=3361 AND `locale`='deDE' AND MD5(`CompletionText`)='217967f674382bb8af8104776f51766e';
UPDATE `quest_request_items_locale` SET `CompletionText`='Spitzhauer wird uns nicht mehr belästigen, sobald Ihr mir den Beweis seines Todes liefert. Ich will seinen Kopf, $N.$B$BWir $R leben für die Jagd und es gibt keine größere Jagd als gegen einen, der schlau genug ist, uns vielleicht auch zu jagen. Wenn Ihr in dieser Aufgabe erfolgreich seid, werdet Ihr anfangen zu begreifen, was ich meine.' WHERE `ID`=3376 AND `locale`='deDE' AND MD5(`CompletionText`)='81e6dc8dc2e0cfae461abbba164f823d';
UPDATE `quest_request_items_locale` SET `CompletionText`='Lasst mich beenden, w... $R.' WHERE `ID`=3441 AND `locale`='deDE' AND MD5(`CompletionText`)='634642467d6715f1b440d918624921c1';
