UPDATE `quest_request_items_locale` SET `CompletionText`='Ja, bitte? Was kann ich für Euch tun, $R? Ich bin fürchterlich beschäftigt und viele Kunden warten auf meine Dienste. Vielleicht könnt Ihr Euch ein wenig beeilen? Ich will ja nicht unhöflich sein, aber ich habe einfach keine Zeit - nicht, wenn ich mit all meiner Arbeit fertig werden möchte.' WHERE `ID`=4450 AND `locale`='deDE' AND MD5(`CompletionText`)='ee5d174a3dff2226c2d37d52262fd9ec';
