UPDATE `quest_offer_reward_locale` SET `RewardText`='Quoi ! Vous y êtes arrivé?$B$BSuivez mon conseil, $Nama, que ce succès ne vous monte pas à la tête ! N''importe quel gamin impubère équipé d''un arc aurait pu abattre de tels… oisillons. Et j''espère que vous n''aimez pas trop tâter de la Buse, hein ? Nous ne voudrions pas que cet oiseau devienne une espèce en voie de disparition.$B$BBien, euh... Il ne sera jamais dit que Daryl le Jeune ne tient pas sa parole.' WHERE `ID`=257 AND `locale`='frFR' AND MD5(`RewardText`)='86f6318b94322d7a5a4501c5652eff16';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Alors finalement Dextren Ward a payé ses crimes sans nom ? Bonne chose de s''être débarrassé de ce salaud, je vous le dis. Et toutes mes félicitations, mon $gami:amie; ! Non seulement vous avez apporté aux familles des défunts la paix qu''elles méritent, mais vous avez aussi envoyé un message limpide à ces bureaucrates corrompus de la Maison des Nobles. Stormwind doit s''occuper des besoins du peuple du bois de la Pénombre ou nous nous débarrasserons de leur tyrannie.' WHERE `ID`=377 AND `locale`='frFR' AND MD5(`RewardText`)='ce5cabf27294144717e8aa2592ab7d8b';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Vous avez mes outils ? Bien joué, bien jeune $ghomme:fille;, très bien ! Je viens de casser il y a une heure mon rochet à dents et j''en ai besoin pour finir de réparer l''engin du Pilote Stonegear. Vous avez fait du bon travail en ramenant ces outils ici, $N.$B$BVoilà, prenez ces pièces pour votre peine.' WHERE `ID`=400 AND `locale`='frFR' AND MD5(`RewardText`)='55746881ecf625ef8faea3194c60d21c';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ah, c''est une bonne chose que l''apothicaire Johaan me fasse envoyer ses découvertes. Avec tout ce qui arrive ici, j''en oublierais presque qu''on fait aussi des recherches hors de Lordaeron et des Clairières de Tirisfal. À propos, je devrai faire envoyer ces échantillons à la nécropole prochainement.$B$BMais vous devez excuser mes divagations. Restez donc quelques jours aux Pins argentés, $N. On a toujours besoin $C mages compétents comme vous.' WHERE `ID`=445 AND `locale`='frFR' AND MD5(`RewardText`)='1ea06cb67133330e74a752b2b285b98d';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Vous avez prouvé votre allégeance à la Nature de belle façon, $N. $gUn:Une; jeunes $C comme vous ont un avenir prometteur.' WHERE `ID`=457 AND `locale`='frFR' AND MD5(`RewardText`)='7796844e1f90c809be6dbf77d20399bd';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Lequel de $C braves guerriers nous arrive de Menethil ? $N, c''est ainsi qu''on vous appelle ?$B$BVous apportez de l''espoir, dans une situation désespérée. Je suis vraiment heureux d''apprendre que le jeune Harlo a survécu. En fuyant, il a été gravement blessé. Nous avons juste eu le temps de le renvoyer sur le dos du dernier coursier du régiment.$B$BMais maintenant nous devons faire face à une situation périlleuse. Dun Modr est tombé et nous ne sommes plus que l''ombre du valeureux régiment que nous étions jadis.' WHERE `ID`=472 AND `locale`='frFR' AND MD5(`RewardText`)='e9ba222394bee85ae67710fb6ae1d41a';
UPDATE `quest_offer_reward_locale` SET `RewardText`='À présent, il est temps pour le grand Bartolo d’endosser son habit de magicien ! Je n''ai pas besoin de bâton de sorcier, ni de bâtonnet de $C. Car moi, le Grand Bartolo, fais de la magie avec une simple aiguille et du fil.' WHERE `ID`=565 AND `locale`='frFR' AND MD5(`RewardText`)='ac1977230ae5f5b453f614f25675efd6';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Belle performance, $N ! Et juste avant que je doive embarquer, en plus ! Je ne pourrai jamais vous remercier assez, $gvieil ami: vieille amie;.' WHERE `ID`=587 AND `locale`='frFR' AND MD5(`RewardText`)='6df2e18f0d1ae820d5bb8452bfd309b2';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Excellent, $gmonseigneur:madame;. C''est un bon départ vers la collection complète des Glyphes dont nous aurons besoin pour retirer Trol''kalar de la tombe de Trollbane.' WHERE `ID`=639 AND `locale`='frFR' AND MD5(`RewardText`)='7ef9736c2d46ac616c604e1f6915b7cc';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ah ! Rien de tel que le tord-boyaux de Foggy MacKreel pour vous réchauffer par une journée fraîche. Et moi qui pensais que ce parasite serait de nouveau en retard pour payer son ardoise. Merci, mon $gami:amie; ! Merci infiniment !' WHERE `ID`=647 AND `locale`='frFR' AND MD5(`RewardText`)='07a49c6d23e234b6afd26ac5b1c105c2';
UPDATE `quest_offer_reward_locale` SET `RewardText`='<Myzrael parle à travers la pierre.>$B$BVous l''avez fait ! Vous avez ouvert les Pierres de lien ! Je sens mes entraves se relâcher et je sais que je serai bientôt libre.$B$BVous êtes $gun:une; noble $C, $N. Mon sauveur !' WHERE `ID`=651 AND `locale`='frFR' AND MD5(`RewardText`)='f263ac674f7f7e7db9787a84620cf841';
UPDATE `quest_offer_reward_locale` SET `RewardText`='La Dame m''a annoncé votre venue, $C. Vous êtes $gle bienvenu:la bienvenue; dans ma demeure, car vous, comme moi, êtes au service d''une cause supérieure.' WHERE `ID`=653 AND `locale`='frFR' AND MD5(`RewardText`)='4ee1b3642925f5f6281fd25f14e3f68a';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Ainsi, Malin vous a $genvoyé:envoyée; ? Je me fiche de savoir si Muradin est revenu d''entre les morts et vous a envoyé ici sur un dragon. Je ne suis pas disponible. Parlez à Kryten si vous avez besoin de quelque chose.' WHERE `ID`=690 AND `locale`='frFR' AND MD5(`RewardText`)='cd61c18e8133f1cd738e4029e0f883fa';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Oh ! Salutation, Félicitations, $gfrère:soeur;.$B$BEt priez les habitants d''en dessous.' WHERE `ID`=727 AND `locale`='frFR' AND MD5(`RewardText`)='f878c8eec8331cb7726a0436f845efeb';
UPDATE `quest_offer_reward_locale` SET `RewardText`='$gBienvenu:Bienvenue; à la nouvelle frontière, $N. Ashenvale est une terre d''opportunités, où $gun jeune:une jeune; $C comme vous peut avoir de nombreuses chances de prouver sa vaillance. Faites le tour de l''Avant-poste et n''oubliez pas de voyager jusqu''à la Grève de Zoram, étant donné que la Horde a aussi un autre Avant-poste, là-bas.$B$BVotre présence ici me dit que vous êtes venu pour en apprendre plus sur l''art de la chasse. Écoutez attentivement, et je partagerai volontiers avec vous le savoir qui vous manque.' WHERE `ID`=742 AND `locale`='frFR' AND MD5(`RewardText`)='4ea9b257ca055b40108a9d92331bbaa7';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Les $R de Narache vous remercient, $N. Vous avez un $gprometteur:prometteuse;.' WHERE `ID`=747 AND `locale`='frFR' AND MD5(`RewardText`)='ad3172745864f11c23dc03b1b9347925';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Les $R de Narache vous remercient pour toutes ces provisions, $N. Vos compétences pour la chasse sont exceptionnelles et vous vaudront la célébrité, un jour, à Thunder Bluff.' WHERE `ID`=750 AND `locale`='frFR' AND MD5(`RewardText`)='effe30ae4b45b81c33f256b2eb6c9add';
UPDATE `quest_offer_reward_locale` SET `RewardText`='C''est le Chef Hawkwind qui vous a $genvoyé:envoyée; ? Passer l''épreuve des Rites de la Terre-mère n''est pas une partie de plaisir, croyez-moi...' WHERE `ID`=755 AND `locale`='frFR' AND MD5(`RewardText`)='0750c2ccfba6df93a098c0f274e50e89';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Je sais que collecter ces plumes n''était pas une tâche facile, $N. Vous venez de prouver que vous étiez l''un $C chamans les plus méritants. Nous sommes heureux, au village Bloodhoof, de vous compter parmi nous.' WHERE `ID`=761 AND `locale`='frFR' AND MD5(`RewardText`)='8b72d260539d7ff38d7902c5a8f90199';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Parfait, $N. Les $C qui se respectent savent toujours que faire d''un tel sac, sur un champ de bataille.$B$BJe salue votre force et votre engagement à mourir au nom de la Horde !' WHERE `ID`=791 AND `locale`='frFR' AND MD5(`RewardText`)='2813b7ddaa544d3f18f63d5b7cbb5345';
