UPDATE `quest_offer_reward_locale` SET `RewardText`='Quand on aura fini de causer, allez parler aux autres citoyens de la Vallée. Ils vous demanderont de faire des trucs pour eux... ça mettra vos talents à l''épreuve et vous montrera les dangers de cette contrée.$B$BQuand vous aurez gagné en expérience et en sagesse, vous aurez besoin que $C, vous montre de nouvelles techniques. Revenez $C voir Jen''shan. Je vous ferai savoir ce que je peux vous apprendre.' WHERE `ID`=3087 AND `locale`='frFR' AND MD5(`RewardText`)='6f3ab7ab6a8cfe7383a5d2867e319306';
UPDATE `quest_offer_reward_locale` SET `RewardText`='Très bon travail, $R. Si vous trouvez d’autres livres, n’hésitez pas à nous les retourner.$B$BAu fur et à mesure que le temps passe, nous avons tendance à évoluer et à ajouter de nouvelles récompenses pour le retour des livres disparus.' WHERE `ID`=7502 AND `locale`='frFR' AND MD5(`RewardText`)='8b75bdcb0f24f5cfd972b819ce3966a1';
