UPDATE `quest_offer_reward_locale` SET `RewardText`='Il vaut mieux rester à l’écart d’un assassin de votre on the talisman, $C. Vos ennemis doivent apprendre le respect ! Et vous l’obtiendriez quand vos adversaires verront la lueur de la Main de la Mort… trop tard…' WHERE `ID`=8142 AND `locale`='frFR' AND MD5(`RewardText`)='645a7fdb56f5a6752f73378d7133f7cf';
