UPDATE `quest_request_items_locale` SET `CompletionText`='Le désert, c''est pas un bon endroit pour avoir faim, mon $gami:amie;, ça je peux vous le dire !$B$BHé ! Qu''est-ce qu''il y a là-bas...' WHERE `ID`=718 AND `locale`='frFR' AND MD5(`CompletionText`)='9daedab09bfa50b0ff6731d8bb5b2983';
