UPDATE `quest_request_items_locale` SET `CompletionText`='Ah ! Nous avons $gun passionné:une passionée; $C pressé, à ce que je vois. Vous venez pour apprendre ? Bien !$B$BMais faites attention : le savoir donne le pouvoir si on est capable de le maîtriser... Sinon il vous rend fou.' WHERE `ID`=728 AND `locale`='frFR' AND MD5(`CompletionText`)='2594c0b0be9284a1fdb13d3c4a58bea1';
UPDATE `quest_offer_reward_locale` SET `RewardText`='皇家药剂师学会失去了博拉尔德实在是太可惜了。但通过你的努力，还有药剂师伦弗利尔对博拉尔德留下的东西的详细研究，我们仍然能为黑暗女士帮忙。$B$B我们正在做一件伟大的事业，$N。如果你不是那么擅长作战就好了，那样的话，我一定会举荐你进入学会的。' WHERE `ID`=451 AND `locale`='zhCN' AND MD5(`RewardText`)='97f49407424634f3b6c5e6f0fc4efc11';
UPDATE `quest_offer_reward_locale` SET `RewardText`='巫师们的魔法被驱散了，节点也回到了休眠状态。并且我们也给了达拉然那些专横的巫师们以沉重的打击。干得漂亮，$N。$B$B但我们仍然要保持警惕，无论如何，这能量节点的位置离我们实在太近……我们必须得为以后好好打算打算。' WHERE `ID`=480 AND `locale`='zhCN' AND MD5(`RewardText`)='22069ff3ec2c9eefb7df4f5ce4be0d2e';
UPDATE `quest_offer_reward_locale` SET `RewardText`='这真不是个好消息，$N。如果达拉尔的推测没错的话——他一向不会出错——我们就必须快点行动了。$B$B我必须先和他谈谈，再制订一个袭击计划。但是与此同时，我们得让达拉然法师们的计划进程慢下来。' WHERE `ID`=482 AND `locale`='zhCN' AND MD5(`RewardText`)='d30dc8e8840cb4727134e81fb2de0523';
UPDATE `quest_offer_reward_locale` SET `RewardText`='……这是什么？图勒拿着我们的魔杖？我一直以为这件象征着我们友谊的东西被巫妖王给毁掉了！$B$B他一定没有使用过这把魔杖，否则我会感应到。真幸运他没有用它……$B$B这是一个令人兴奋的发现。我对你感激不尽，$N，我要好好地酬谢你。' WHERE `ID`=491 AND `locale`='zhCN' AND MD5(`RewardText`)='7e08be8bcfdd328249198998528e4b0a';
UPDATE `quest_offer_reward_locale` SET `RewardText`='$N，你认真地完成了我交给你的任务，这让我感到很欣慰。尊重这片土地和生活在这片土地上的生命，这一点很重要。死亡和生命是一个轮回……这是无法避免的。任何生命都要经历这种轮回。好好思考我说的话，希望你永远都不要忘记。' WHERE `ID`=745 AND `locale`='zhCN' AND MD5(`RewardText`)='2780419e284ca5253c281f2ba8623a8b';
UPDATE `quest_offer_reward_locale` SET `RewardText`='谢谢你，$N。这下莫高雷的野生动物都可以安心了。而且这样也可以告诉那些矮人，挖掘土地不是获得知识的好方法。' WHERE `ID`=746 AND `locale`='zhCN' AND MD5(`RewardText`)='dcba005ff793aff85d4dd664291211f6';
UPDATE `quest_offer_reward_locale` SET `RewardText`='你的事迹刚刚传到我这里，井边的野兽已经在迫不及待地饮水了。$B$B你为这片土地立下了大功，$N，也为$R一族立下了大功。' WHERE `ID`=754 AND `locale`='zhCN' AND MD5(`RewardText`)='532a7e002281a18a62fde58bd8b32c35';
UPDATE `quest_offer_reward_locale` SET `RewardText`='我知道收集这些羽毛不是简单的事，$N。你已经证明了你是一个优秀的$C。' WHERE `ID`=761 AND `locale`='zhCN' AND MD5(`RewardText`)='73f3aaf0dfc69ace55b2df96afef26a6';
UPDATE `quest_offer_reward_locale` SET `RewardText`='不要害怕，$N。你已经通过了幻象仪祭。' WHERE `ID`=772 AND `locale`='zhCN' AND MD5(`RewardText`)='30cc4b7bf86d724243e3ef3a856b9673';
UPDATE `quest_offer_reward_locale` SET `RewardText`='你在通过大地之母仪祭的过程中已经显示了你的勤奋和努力，$N。$B$B我们是先祖之魂，我们代表了那些为保卫雷霆崖而付出生命的勇敢的$R。现在，我把保卫这里的神圣职责交给你。$B$B你已经通过了智慧仪祭，年轻的$C。你可以骄傲地走进雷霆崖了。' WHERE `ID`=773 AND `locale`='zhCN' AND MD5(`RewardText`)='2b05704d921dcd5243bb4d59d8118b69';
UPDATE `quest_offer_reward_locale` SET `RewardText`='我有一些关于上古战争的记录，尤其是关于永恒之井大爆炸前后的记录。这样看来，亚米萨兰的毁灭并不令人感到奇怪。$B$B谢谢你，$N。在你的帮助下，我在这里的工作终于算是完成了，我现在就开始准备向议会递交一份全面的报告。' WHERE `ID`=953 AND `locale`='zhCN' AND MD5(`RewardText`)='67eed777baf6012a9571f3afcaa387e0';
UPDATE `quest_offer_reward_locale` SET `RewardText`='这……这真让我难以置信，我现在拿着的竟是束缚了我那么长时间的东西。我们不要浪费时间了，$N。当封印被摧毁以后，我又可以自由自在地在林间漫步了。' WHERE `ID`=956 AND `locale`='zhCN' AND MD5(`RewardText`)='9b54c5a912f52e6d0d3b0d1bc1ed9f4d';
UPDATE `quest_offer_reward_locale` SET `RewardText`='我自由了，$N，自由！我终于可以亲眼目睹世界上的万事万物了……之前我很少能知道关于外面世界的东西。在我被囚禁之前，永恒之井还存在着，上层精灵们侍奉着我们无比敬爱的女王艾萨拉。$B$B我能感受到囚禁我的人，也就是我以前的主人，埃瑟里克斯，他依然活着……我内心的绝望早已化成复仇的信念！' WHERE `ID`=957 AND `locale`='zhCN' AND MD5(`RewardText`)='3b5da4669466fa4117d4a1607b67e384';
UPDATE `quest_offer_reward_locale` SET `RewardText`='谢谢你，$N。或许如果由我亲自来做的话会更好一些……不过，即使是经过了几千年，我也不忍心对我的至爱痛下杀手。$B$B请让我安静一会儿，让我一个人来体味这悲伤……' WHERE `ID`=963 AND `locale`='zhCN' AND MD5(`RewardText`)='b5e7e7cefa91a1011b48b8c28414e7c6';
UPDATE `quest_offer_reward_locale` SET `RewardText`='非常感谢你，$N。这应该能为解开术士聚集之谜提供一些帮助……$B$B嗯~~……暗滩教派？我以前从没听说过这伙人。由于对他们几乎一无所知，我自然也就不可能了解他们的计划。$B$B时间紧迫，你必须尽快把警报传给德尔格伦。' WHERE `ID`=966 AND `locale`='zhCN' AND MD5(`RewardText`)='034718d01673e2ac8bb5177d377d30ef';
UPDATE `quest_offer_reward_locale` SET `RewardText`='确实如此。在我们的城市里出现了一股魔法波动，我们还不清楚它的起源，也无从得知它到底是好是坏。我们必须搜集更多的消息……$B$B$N，你来执行这个任务。' WHERE `ID`=1959 AND `locale`='zhCN' AND MD5(`RewardText`)='89baa2aaf799580ba5d1c544882e8d72';
UPDATE `quest_offer_reward_locale` SET `RewardText`='今天你为我们提供了很大的帮助，这些生物选择在黑海岸结束生命，现在我们终于有机会解开这一谜团了。他们可能是从泰达希尔附近逃来这里的，这可是件麻烦事。如果你在旅途中见到了其它此类的生物，就请告知我，我们在这里的研究才刚刚开始。$B$B我谨代表月神殿，请你收下它作为回报。谢谢你，$N！' WHERE `ID`=4681 AND `locale`='zhCN' AND MD5(`RewardText`)='39f8edad2f11fcf6026f37eebda171b7';
UPDATE `quest_offer_reward_locale` SET `RewardText`='那么水晶确实存在了，$N？嗯……不管怎么说，你出色地完成了任务，干得漂亮！$B$B这块水晶到底是什么东西？这只是许多问题中的一个。另一个浮现在我脑中的问题是，为什么枭兽会被它吸引？这水晶是自然形成的呢，还是邪恶的产物？$B$B我还有很多问题，但我们还需要仔细研究那块水晶才能得到更多答案。' WHERE `ID`=4811 AND `locale`='zhCN' AND MD5(`RewardText`)='036b07d852547b3b0907155276431889';
UPDATE `quest_offer_reward_locale` SET `RewardText`='那么，看起来即使我们对这块水晶有了进一步的了解，其结果也不过是发现了更多有待回答的问题！$B$B我要把你汇报的这些情报交给奥伯丁的议会，他们可能会制定后续的计划，嗯，我是说假设他们能制定出计划来的话……现在，东边的威胁一时半会还不会对我们造成什么伤害。$B$B至于你，请拿着这个。这是给你的奖赏，$N。' WHERE `ID`=4813 AND `locale`='zhCN' AND MD5(`RewardText`)='d026b3f429ec9e64c0d2152bbaacba29';
UPDATE `quest_offer_reward_locale` SET `RewardText`='欢迎回来，$N。我感觉到你在第一次与巨熊之灵会面时，跟别的追寻熊的力量的$C一样……感觉有些困惑，但是意愿很强烈。我以前也是这样的。$B$B只要艾泽拉斯世界存在，巨熊之灵就是它的一部分。我们要依赖它的智慧和力量来完成我们的任务。现在，你应该接受第一个试炼了。仔细听好……' WHERE `ID`=5932 AND `locale`='zhCN' AND MD5(`RewardText`)='4f5d0deaaa165fe230af5c85a9ddcae8';
UPDATE `quest_offer_reward_locale` SET `RewardText`='你终于大步迈进了一个更加广阔的世界，$N。我感觉到你已经掌握了巨熊之灵所传授的知识，还有月爪枭兽曾经拥有的力量。$B$B在你的面前没有其它的障碍了……现在，让我告诉你成为一个利爪$C意味着什么吧！' WHERE `ID`=6002 AND `locale`='zhCN' AND MD5(`RewardText`)='2dea9b99f023bdd34edeab5e1196498b';
UPDATE `quest_offer_reward_locale` SET `RewardText`='感谢你救了我的朋友，$N。我会将这些计划呈交给我的指挥官，我们将给予那些十字军一个终生难忘的“盛迎”。$B$B我深知我们内部有许多人并不信任你们$C，但我十分清楚，你是一名彻头彻尾的被遗忘者。我绝不会忘记此事，并且我定会让其他人知晓你今日在此地的所作所为。' WHERE `ID`=94440 AND `locale`='zhCN' AND MD5(`RewardText`)='d24ea586ec940db7847556931eb39264';
UPDATE `quest_offer_reward_locale` SET `RewardText`='生命符记仅能由准备好运用圣光最伟大恩赐之一的$C进行使用。我很荣幸你能成为我们的一员，现在我将救赎的恩赐授予你。有了它，你便能够复活倒下的同伴了。请明智地运用这份全新的恩典。$B$B你为被遗忘者以及提尔之卫的$C皆做出了卓越的贡献。我们为赢得被遗忘者同胞的信任与支持所采取的任何行动皆是物有所值的。愿圣光与你同在，$N。' WHERE `ID`=94441 AND `locale`='zhCN' AND MD5(`RewardText`)='349b4ccaac4575900dc21fe82dd42f03';
UPDATE `quest_request_items_locale` SET `CompletionText`='你搞到腐皮豺狼人的脓液了吗，$N？' WHERE `ID`=443 AND `locale`='zhCN' AND MD5(`CompletionText`)='75bd829f654f94d241b327fbcbb003a3';
UPDATE `quest_request_items_locale` SET `CompletionText`='你好，$N。比索说了些什么？' WHERE `ID`=446 AND `locale`='zhCN' AND MD5(`CompletionText`)='99ac02bf9e940b5c0ac17addf102b6b4';
UPDATE `quest_request_items_locale` SET `CompletionText`='来幽暗城有什么事，$N?' WHERE `ID`=451 AND `locale`='zhCN' AND MD5(`CompletionText`)='c0d8cf892fe0a2ab185b4648a9c2bd6a';
