UPDATE `quest_request_items_locale` SET `CompletionText`='$N，你战胜图勒·鸦爪了吗？' WHERE `ID`=491 AND `locale`='zhCN' AND MD5(`CompletionText`)='acce1a838ca656d190a3d561a6b4468e';
