UPDATE `quest_request_items_locale` SET `CompletionText`='你好，$N。你带来损坏的工具了吗？矮人的挖掘行动会激怒莫高雷的科多兽，我们必须阻止他们这种玷污大地的行为！' WHERE `ID`=746 AND `locale`='zhCN' AND MD5(`CompletionText`)='0e6e5400f7ec133230c44a68842b6d7d';
