UPDATE `quest_request_items_locale` SET `CompletionText`='$N，你弄到赤鳞镰爪龙的角了吗？那些角会让我大赚一笔！' WHERE `ID`=865 AND `locale`='zhCN' AND MD5(`CompletionText`)='bfacbb9702374ed15b49a88bb63951ff';
